INSERT INTO public.ap_email_templates (id, key, label, subject, body, updated_at, updated_by) VALUES
	('8175e5a3-b4cd-4972-b5da-2ffc42f7f084', 'approve', 'Approve the partnership', 'Your partnership is approved', 'Hi {{faculty_name}},
INSERT INTO public.ap_settings (id, is_open, intro_copy, confirmation_copy, enabled_partnership_types, google_appointments_url, updated_at, updated_by) VALUES
	(true, false, 'Tell us about the partnership you have in mind. A staff member will review your inquiry and follow up by email — submitting this form does not guarantee a partnership, publication, distribution, or news coverage.', 'Thank you. We will review your inquiry and follow up by email. Submitting this form does not guarantee a partnership, publication, distribution, or news coverage.', '{classroom_visit,station_immersion,applied_project,internship_practicum,faculty_research,other}', NULL, '2026-11-05 23:48:53.631188+00', NULL);
INSERT INTO public.bk_settings (id, is_open, intro_copy, confirmation_copy, closed_copy, offered_packages, updated_at, updated_by) VALUES
	(true, false, 'Tell us what you have in mind — a webcast, a studio or field production, editing, or airtime for a university message. Our production staff will review the request, estimate it, and follow up by email. Submitting this form does not book a date or commit the station to the work.', 'Thank you. Our production staff will review your request and follow up by email with an estimate. Nothing is booked until you approve that estimate.', 'We are not taking new production requests right now. Please check back later, or contact the station directly.', '{}', '2026-11-05 23:48:53.631188+00', NULL);
INSERT INTO public.ep_form_fields (id, key, label, help_text, field_type, options, required, active, sort_order, created_at, updated_at) VALUES
	('32994652-14fb-4468-a981-1e2f19fa6f55', 'summary', 'Summary', 'What is the story? Two or three sentences.', 'long_text', NULL, true, false, 1, '2026-11-05 23:48:31.381169+00', '2026-11-05 23:48:31.821815+00'),
	('6a99fbb2-7567-4f4c-a046-852f9b4ae392', 'why_now', 'Why now?', 'What makes this timely — a news peg, a season, a decision coming up?', 'long_text', NULL, true, false, 2, '2026-11-05 23:48:31.381169+00', '2026-11-05 23:48:31.821815+00'),
	('d9bf446f-937c-4aa1-9212-9b3692971c96', 'sources', 'Possible sources', 'Who could we talk to? Note any access you already have.', 'long_text', NULL, false, false, 3, '2026-11-05 23:48:31.381169+00', '2026-11-05 23:48:31.821815+00'),
	('d8baa822-2998-4d6d-a56b-8696d86600ae', 'format', 'Suggested format', NULL, 'select', '["Spot news", "Feature", "Interview / two-way", "Series", "Digital-first"]', false, false, 4, '2026-11-05 23:48:31.381169+00', '2026-11-05 23:48:31.821815+00'),
	('875454b4-b82b-4be5-8851-4db0aaa28b2b', 'summary', 'Pitch summary', 'In two or three sentences, what is the story? Identify what is happening, who or what is affected, and why it matters.', 'long_text', NULL, true, true, 1, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('bc340e8d-24de-4f37-8364-711277563212', 'central_question', 'Central reporting question', 'What specific question will the reporting try to answer?', 'long_text', NULL, true, true, 2, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('7d3646a3-9dbf-4b83-9a79-0ea7948e3172', 'why_now', 'Why now?', 'What development, decision, trend, deadline, discovery, or strategic moment makes this timely?', 'long_text', NULL, true, true, 3, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('daeb92c4-f48b-4456-8aca-62be675a9eb6', 'public_stakes', 'Public stakes', 'What is at stake, and for whom? Consider effects on lives, rights, safety, finances, opportunity, public resources, or community life.', 'long_text', NULL, true, true, 4, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('348acdd8-30fc-4e53-a472-8d3ad7c445f3', 'perspectives', 'Relevant people and perspectives', 'Who is directly affected, who holds power or responsibility, and whose experience or perspective should the reporting include?', 'long_text', NULL, true, true, 6, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('3dbd7bf2-2238-4ef7-a5c5-8e3dc6e5a112', 'format', 'Suggested format', NULL, 'select', '["Brief / spot item", "Standard story", "Interview / two-way", "Explainer / service", "Enterprise feature", "Accountability / investigative", "Audio feature", "Series / continuing coverage", "Undetermined"]', true, true, 9, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('02dd661e-f641-435f-9520-d24a5c7b3088', 'urgency', 'Urgency or publication window', NULL, 'select', '["Immediate / same day", "Near term / several days", "Time-bound / known date", "Planned / several weeks", "Long-range / enterprise", "No firm deadline"]', true, true, 10, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('983b2550-4507-4ed8-a86f-04c84e2da830', 'sources_materials', 'Known sources, documents, data, records, or links', NULL, 'long_text', NULL, false, true, 11, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('3d608160-f8dc-4633-946c-438fc2b270ac', 'audio_visual', 'Audio, scene, visual, archive, map, or graphic opportunities', NULL, 'long_text', NULL, false, true, 13, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('e6c0f7e9-bb65-4e6e-8b68-23d7f4e7849c', 'support_needs', 'Collaboration or specialized support needed', NULL, 'long_text', NULL, false, true, 14, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('9996c608-b169-41e6-a498-118dee4f04d6', 'resource_estimate', 'Resource estimate', NULL, 'select', '["Small", "Moderate", "Significant", "Unknown"]', false, true, 15, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.821815+00'),
	('cbd7b7b0-5592-47e4-af4f-404fad638f4a', 'primary_pillar', 'Primary coverage pillar', 'Choose the pillar this pitch most advances, or one of the status options if it doesn''t map to a current pillar. Pillars and their guiding questions are configured in Settings → Pillars.', 'select', NULL, true, true, 7, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:31.912822+00'),
	('1a3ebe53-2129-477d-84ce-8ef2527d5cc5', 'pillar_contribution', 'Contribution to sustained coverage', 'How would this reporting advance the station''s understanding or coverage of the selected priority? Required when a defined pillar is selected above — not when the pitch is outside current pillars, emerging, or an immediate need.', 'long_text', NULL, false, true, 8, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:53.631188+00'),
	('596106e8-108c-46d4-b096-217264094f8b', 'prior_coverage', 'Related station coverage or existing reporting', NULL, 'long_text', NULL, false, true, 12, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:53.631188+00'),
	('02ad978d-8e8f-4e82-b2c9-7f153cc53ba0', 'reporting_approach', 'Proposed reporting approach', 'Briefly describe likely evidence, source categories, records or data, locations or scenes, and what the station could contribute beyond existing coverage.', 'long_text', NULL, true, true, 5, '2026-11-05 23:48:31.821815+00', '2026-11-05 23:48:53.631188+00');
