INSERT INTO public.tools (id, key, name, description, route, status, enabled, default_access, sort_order, created_at, updated_at) VALUES
	('cb8769f3-27c0-44f4-9b32-30682e734e3a', 'editorial-planning', 'Editorial Planning', 'Submit, review, and evaluate story pitches for editorial meetings.', '/editorial', 'available', true, 'invite_only', 1, '2026-11-05 23:48:31.339796+00', '2026-11-05 23:48:31.339796+00'),
	('efffdd6d-223e-4b00-a77e-459442295763', 'remote-interview', 'Remote Interview', 'Record remote interviews, capturing each participant locally at full quality.', '/remote-interview', 'in_development', true, 'invite_only', 2, '2026-11-05 23:48:31.339796+00', '2026-11-05 23:48:31.633097+00'),
	('afcedc31-3687-4acf-b5b8-4a162971f070', 'audience-listening', 'Audience Listening', 'Collect recorded answers from the public to a short set of questions, and review them here.', '/audience-listening', 'available', true, 'invite_only', 4, '2026-11-05 23:48:31.988484+00', '2026-11-05 23:48:31.988484+00'),
	('503e8057-ca63-47a3-ad8b-4f73983b8ef9', 'transcription', 'Sourcework', 'Turn raw interviews into production-ready audio excerpts: transcribe, identify speakers, correct the transcript, and export actualities.', '/sourcework', 'available', true, 'invite_only', 5, '2026-11-05 23:48:31.495247+00', '2026-11-05 23:48:32.229545+00'),
	('5dc6dd04-1994-4398-bd91-e7e1703f4fd1', 'roadmap', 'Roadmap', 'Ask for what these tools should do next, vote on what other people asked for, and follow what is planned, in progress, and shipped.', '/roadmap', 'available', true, 'approved_staff', 5, '2026-11-05 23:48:32.468652+00', '2026-11-05 23:48:32.468652+00'),
	('623be0fc-f911-4079-a7af-4816e1fda37c', 'editorial-inquiry', 'Editorial Inquiry', 'Turn a broad guiding question into concrete, reportable story questions by growing a question tree in collaboration with an AI model.', '/editorial-inquiry', 'available', true, 'invite_only', 9, '2026-11-05 23:48:34.471824+00', '2026-11-05 23:48:34.471824+00'),
	('12dbe4e7-6851-453d-a437-277c6c2c1eb1', 'resources', 'Resources', 'Station procedures, a guide to every tool in the portal, and notes on what changed.', '/resources', 'available', true, 'approved_staff', 10, '2026-11-05 23:48:36.124228+00', '2026-11-05 23:48:36.124228+00'),
	('ff2e6b11-9c01-41fc-9d20-d5827dfdda89', 'log', 'On Air', 'The broadcast day: the program schedule, clocks, rundowns, the content library, and the DAD log.', '/log', 'available', true, 'invite_only', 7, '2026-11-05 23:48:32.771119+00', '2026-11-05 23:48:38.225271+00'),
	('90f557ed-b526-402b-8a58-b86f585ec57d', 'underwriting', 'Traffic', 'What must air and proof that it did: underwriters, agreements, copy, placement, exceptions, and affidavits.', '/underwriting', 'available', true, 'invite_only', 8, '2026-11-05 23:48:33.32384+00', '2026-11-05 23:48:38.225271+00'),
	('6f1f53ed-1018-4dc7-851c-013ee96986c3', 'bookings', 'Bookings', 'University production work: capacity, rates, and cost recovery — the rate model, the term plan, requests and estimates.', '/bookings', 'available', true, 'invite_only', 11, '2026-11-05 23:48:38.412454+00', '2026-11-05 23:48:38.412454+00'),
	('77595aed-d7c4-4d01-906f-873793f07658', 'academic-partnerships', 'Academic Partnerships', 'Faculty inquiries for the station''s media partnership program, from submission through active partnership.', '/academic-partnerships', 'available', true, 'invite_only', 6, '2026-11-05 23:48:32.585239+00', '2026-11-05 23:48:53.631188+00'),
	('f8675e26-b588-4deb-b1fb-1ceb0127109d', 'website', 'Website', 'Sign in to the station''s website content system to write, review and publish stories, manage sponsors and agreements, and review listening answers.', '/website', 'available', false, 'invite_only', 12, '2026-11-05 23:48:42.878594+00', '2026-11-05 23:48:53.631188+00');
INSERT INTO public.rc_articles (id, slug, kind, title, summary, body, area, owner_role, tool_id, screen_keys, released_on, sort_order, source, version_note, needs_review, edited_since_release, version, created_at, updated_at, updated_by) VALUES
	('30e775ce-9c91-4ceb-a45b-77f137872dd8', 'log-schedule-a-program', 'guide', 'Schedule a program', 'See the week, change when a program airs, and find programs that still need a clock.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Schedule", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": " tab is where the schedule and every clock are reached from. Its row of pages is ", "type": "text"}, {"text": "Programs", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (what airs when), ", "type": "text"}, {"text": "Automation", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (when no one is in the studio), and ", "type": "text"}, {"text": "Underwriting", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (hours closed to underwriting credits). Scheduling and changing a clock are the program director''s tasks.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "See the schedule", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Week", "type": "text", "marks": [{"type": "bold"}]}, {"text": " view shows the week as a grid, one column per day, with each program at its air time and the clock it runs on. Behind the programs, grey shading is the automated hours and red hatching is the hours closed to underwriting, each edited on its own page. Programs still on the shared placeholder clock are shaded amber. Select a block to see its details, then ", "type": "text"}, {"text": "Edit schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Open program", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Use Prev, Next, and Today to change the week. The ", "type": "text"}, {"text": "List", "type": "text", "marks": [{"type": "bold"}]}, {"text": " view shows the same programs as a table.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find what needs attention", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the list, ", "type": "text"}, {"text": "Needs a clock", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows the programs still on the placeholder clock, and ", "type": "text"}, {"text": "Not scheduled", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows programs with no current schedule. Clocks no program uses are listed under ", "type": "text"}, {"text": "Unused clocks", "type": "text", "marks": [{"type": "bold"}]}, {"text": " below the list.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Change when a program airs", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the program. Under ", "type": "text"}, {"text": "When it airs", "type": "text", "marks": [{"type": "bold"}]}, {"text": " each schedule shows its days and time; select ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The clock it runs on is changed in the same editor.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose the days, the start time, and the length. The quick buttons set weekdays, the weekend, or every day.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Set when the schedule starts and, if it stops, when it ends. Pick the clock it runs on.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Check the preview on the right. It shows the times, the next airing, and whether another program airs at the same time on those days. An overlap is a warning; it doesn''t stop you saving.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Save schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Rundowns that were already generated keep the clock they were built from; a new clock applies to rundowns generated from then on.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add a schedule", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "+ Add a time", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a program''s page, choose its days, time, and clock, and save. If the clock doesn''t exist yet, select ", "type": "text"}, {"text": "Create a clock for this program", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a program''s details", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Details", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel on a program''s page holds its name, kind, description, and NPR connection. The program director selects ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the panel to change them in place, then ", "type": "text"}, {"text": "Save changes", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Collection ID", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is NPR''s ID for the program. With it set, On Air reads that day''s NPR stories for the program''s rundowns. Leave it blank to stop reading NPR for the program.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Feed''s first hour (Eastern)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " only matters for NPR''s multi-hour shows, whose hours alternate on the feed. It lines up NPR''s hours with ours so estimated story times are right. Leave it on ", "type": "text"}, {"text": "Same as our schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": " unless NPR''s first hour differs.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Changing the collection ID clears the program''s saved NPR stories from today on, so the next look fetches the new ones. Earlier dates keep what they had.", "type": "text"}]}]}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.program,log.program.schedule}', NULL, 20, 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', false, false, 6, '2026-11-05 23:48:36.124228+00', '2026-11-05 23:48:39.815325+00', NULL),
	('cd2b236c-6dfe-4c02-84fc-684f56e89c1d', 'roadmap-curate-requests', 'guide', 'Curate requests', 'Move requests through the roadmap statuses on the board.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Curators decide what happens to each request. A curator is anyone an administrator has given the Curator role on ", "type": "text"}, {"text": "Roadmap", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/roadmap"}}]}, {"text": "; administrators curate too.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Move a request", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the Roadmap. As a curator you see a board with a column for each of the six statuses.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Drag a card to the status it should have. A move the status rules don''t allow is ignored and the card returns to its column.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dropping a card on ", "type": "text"}, {"text": "Declined", "type": "text", "marks": [{"type": "bold"}]}, {"text": " asks for a reason first. The reason is shown on the request.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "You can also change a request''s status from its own page.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Everyone else sees the grouped list of decided requests, not the board.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Status changes are recorded in the audit log.", "type": "text"}]}]}]}]}', NULL, NULL, '5dc6dd04-1994-4398-bd91-e7e1703f4fd1', '{roadmap.board,roadmap.post}', NULL, 20, 'release', 'Contextual screen links preserved in the existing guide', false, false, 2, '2026-11-05 23:48:36.124228+00', '2026-11-05 23:48:39.862284+00', NULL),
	('b94314f4-e29d-42ea-a494-82f10d6b6d3c', 'audience-listening-create-and-publish', 'guide', 'Creating and publishing a query', 'Ask up to five questions, configure who can be asked what, then publish as a standalone page or a Grove embed.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "query", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/audience-listening"}}]}, {"text": " is a public listening initiative: up to five ordered questions, published as its own page or embedded in a Grove article, with the answers coming back to you here.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Create a query", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "From the query list, select ", "type": "text"}, {"text": "New query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fill in an internal title (for your own list), a public title (what a listener sees), and a public introduction saying why you''re asking and what you''ll do with the answers. Select ", "type": "text"}, {"text": "Create query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "You land on the new query''s Questions tab.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add questions", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fill in a question''s prompt, and optionally public guidance, internal context (staff-only), a maximum answer length, and whether it''s required.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Add question", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Repeat for up to five questions.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Reorder or duplicate a question with the buttons on its card, or remove one — before anyone has answered.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Configure settings", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Settings tab covers everything about how the query behaves, separate from its questions:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Participant information", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — which details (name, city, email, phone, a free-text note) to ask for, each set to don''t ask, optional, or required. Asked once for the whole submission, never per question.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Consent and attribution", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — three separate questions that stay separate on the record: permission to be contacted, permission to be named, and the option to request anonymity. Permission to be contacted is not permission to be named, and asking for anonymity is neither. The consent terms text itself is required and is recorded with the submission at the moment it''s accepted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Opens and closes dates", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — both optional; leaving them blank means the query opens as soon as you select ", "type": "text"}, {"text": "Open for responses", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and stays open until you close it. Someone already recording when a close date passes may still finish and submit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Transcription", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — manual (send answers after reviewing them) or automatic (every answer is queued the moment it''s submitted, then sent in one click from the Submissions tab).", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Publish it", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the query''s header — visible from any tab — select ", "type": "text"}, {"text": "Open for responses", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Until then, the public link and embed code don''t work, even for someone who already has them.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Go to the Share tab for a ", "type": "text"}, {"text": "Copy link", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button for the standalone public page, and a ", "type": "text"}, {"text": "Copy embed code", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button for a ready-made Grove iframe snippet — paste it into a Grove Responsive Embed element unchanged. If you add or remove questions later, copy the embed code again.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Preview", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (always available, even on a draft) to walk through the query as a participant would — nothing is submitted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once a query has submissions, question wording stays editable, but removing or reordering questions is no longer offered — an answer keeps the exact wording it was asked under.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The header''s action changes with status: open queries offer ", "type": "text"}, {"text": "Close query", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (stops new responses; anyone already recording can still finish); closed ones offer ", "type": "text"}, {"text": "Open for responses", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Archive query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A query can be deleted only before it has any submissions, from the Settings tab. Once a submission exists, archiving — which keeps every response, answer, and transcription link — is how you finish with it.", "type": "text"}]}]}]}]}', NULL, NULL, 'afcedc31-3687-4acf-b5b8-4a162971f070', '{audience-listening.queries,audience-listening.query}', NULL, 10, 'editor', 'Contextual screen link in existing instructions', false, false, 5, '2026-11-05 23:48:36.445146+00', '2026-11-05 23:48:39.951425+00', NULL),
	('d98b0090-6ccd-4091-b422-601d7326ece0', 'editorial-run-a-planning-meeting', 'guide', 'Run a planning meeting', 'Build a slate, score it independently, then decide from the ranked agenda.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A planning meeting moves through three stages: Scoring open, Agenda, and Concluded. Editors run it; reviewers and editors score; contributors can follow along. The Meetings tab lists every meeting with its slate, filtered by In progress or Concluded.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Set it up (editors)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Meetings tab, select ", "type": "text"}, {"text": "New meeting", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose the date and select ", "type": "text"}, {"text": "Create meeting", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the meeting. Select ", "type": "text"}, {"text": "+ Add pitch", "type": "text", "marks": [{"type": "bold"}]}, {"text": " above the slate, choose a pitch from the backlog and select ", "type": "text"}, {"text": "Add to slate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Repeat for each pitch. A pitch can also be added from its own page''s ⋮ menu.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Score the slate (reviewers and editors)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The slate is a list beside the pitch: a filled dot marks each pitch you have scored. On a phone the list becomes a strip above the pitch, with ", "type": "text"}, {"text": "Previous", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Next", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and a picker. ", "type": "text"}, {"text": "Show the full pitch", "type": "text", "marks": [{"type": "bold"}]}, {"text": " expands the answers below the summary.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose a score for each criterion. On a computer, hover a number to read what it means; on a touch screen the meaning of the chosen number is shown under the scale. Institutional modifiers are optional.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose a recommendation, flag any concerns, and add a comment if it helps the room. ", "type": "text"}, {"text": "Save review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " saves and stays; ", "type": "text"}, {"text": "Save and go to next unscored", "type": "text", "marks": [{"type": "bold"}]}, {"text": " saves and opens the next pitch you have not scored.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Scoring is independent: nobody sees anyone else''s scores or comments until the editor closes scoring.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Decide (editors)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Close scoring & build agenda", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The slate is ranked by adjusted score, and the strip at the top counts pitches, reviews and decisions made.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An amber ", "type": "text"}, {"text": "Split", "type": "text", "marks": [{"type": "bold"}]}, {"text": " badge means reviewers'' core scores are far apart — worth discussing. Open ", "type": "text"}, {"text": "Scores, recommendations and comments", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to see why.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For each pitch, choose a ", "type": "text"}, {"text": "Decision", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — Assign, Defer or Archive — and select ", "type": "text"}, {"text": "Record", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Assign asks for the reporter; Defer and Archive take an optional rationale. A decided pitch shows its outcome; select ", "type": "text"}, {"text": "Change", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to revise it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Conclude meeting", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the main action once the agenda is built. It asks you to confirm and names any pitch still undecided, which is recorded as deferred. A concluded meeting is a permanent record.", "type": "text"}]}]}]}]}', NULL, NULL, 'cb8769f3-27c0-44f4-9b32-30682e734e3a', '{editorial.meeting}', NULL, 20, 'release', 'The slate list and strip, Save and go to next unscored, the Decision select, and Conclude as the main action', false, false, 4, '2026-11-05 23:48:36.556372+00', '2026-11-05 23:48:42.75501+00', NULL),
	('89f6a164-b011-4cc5-9d3e-13bfe7c4b27a', 'audience-listening-publish-a-query', 'guide', 'Create and publish a query', 'Ask the public up to five recorded questions from a story or a link.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A query is a recorded callout: up to five questions a listener answers out loud, from a standalone page or an embed in a story.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Create it", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "New query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Give it an internal title (the newsroom''s name for it), a public title, and a public introduction saying why you''re asking and what you''ll do with the answers. Select ", "type": "text"}, {"text": "Create query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the ", "type": "text"}, {"text": "Questions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, add each question: the prompt, optional guidance, a maximum length, and whether it''s required.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the ", "type": "text"}, {"text": "Settings", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, choose which details to ask participants for, the consent and attribution questions, and optional opening and closing dates.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Preview", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to walk through it as a participant would. Nothing is submitted.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Publish it", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Open for responses", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Until then the public link doesn''t work, even for someone who has it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the ", "type": "text"}, {"text": "Share", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, copy the public link for newsletters and social posts, or the Grove embed code to paste into a Grove Responsive Embed element unchanged. If you add questions later, copy the embed code again.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once a query has submissions, question wording can still change, but questions can''t be removed or reordered. Each answer keeps the exact question it was asked.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Close query", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to stop new responses. Anyone already recording can still finish and submit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A query can be deleted only before it has any submissions. After that, archive it.", "type": "text"}]}]}]}]}', NULL, NULL, 'afcedc31-3687-4acf-b5b8-4a162971f070', '{audience-listening.queries,audience-listening.query}', NULL, 10, 'release', 'Written for the Resources backfill', false, false, 1, '2026-11-05 23:48:36.556372+00', '2026-11-05 23:48:36.556372+00', NULL),
	('63f0b6a0-82e3-4e29-9e63-d833bcdbca04', 'academic-partnerships-work-the-pipeline', 'guide', 'Work an inquiry through the pipeline', 'Move faculty inquiries through the seven stages, or close them with a disposition.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Faculty inquiries from the public form arrive in the ", "type": "text"}, {"text": "New", "type": "text", "marks": [{"type": "bold"}]}, {"text": " column of the Pipeline. From there they move through Reviewing, Meeting Requested, Scoping, Approved, Active, and Completed.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Move an inquiry", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Drag the card to another column.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Or use the stage menu under the card. It works by keyboard, screen reader, and touch.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the inquiry''s own page, change its ", "type": "text"}, {"text": "Stage", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and select ", "type": "text"}, {"text": "Save", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Work the inquiry", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select the card to open it. The original response is at the top.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Set an ", "type": "text"}, {"text": "Owner", "type": "text", "marks": [{"type": "bold"}]}, {"text": " so the team knows who has it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Record an ", "type": "text"}, {"text": "Assessment", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — overall fit, capacity, and timing — and a ", "type": "text"}, {"text": "Next action", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with a date. The date shows on the card.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add internal notes. Everything is recorded in the inquiry''s ", "type": "text"}, {"text": "Activity", "type": "text", "marks": [{"type": "bold"}]}, {"text": " log.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Close one without completing it", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Under ", "type": "text"}, {"text": "Disposition", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose Deferred, Declined, Withdrawn, or Archived and select ", "type": "text"}, {"text": "Apply", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Every choice except Archived needs a reason. The inquiry leaves the board but keeps the stage it reached; find it on ", "type": "text"}, {"text": "All submissions", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and select ", "type": "text"}, {"text": "Reopen", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to bring it back.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Coordinators can also delete an inquiry permanently from the Danger zone at the bottom of its page.", "type": "text"}]}]}', NULL, NULL, '77595aed-d7c4-4d01-906f-873793f07658', '{academic-partnerships.pipeline,academic-partnerships.submission}', NULL, 10, 'release', 'Written for the Resources backfill', false, false, 1, '2026-11-05 23:48:36.556372+00', '2026-11-05 23:48:36.556372+00', NULL),
	('58b99723-7e12-4ed7-9913-37ea8382641f', 'academic-partnerships-email-faculty', 'guide', 'Email a faculty member', 'Send a templated reply, such as an invitation to meet, from the inquiry.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Replies to an inquiry start from a template, filled in with the inquiry''s details.", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "In the ", "type": "text"}, {"text": "Email", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel on the inquiry''s page, choose a ", "type": "text"}, {"text": "Template", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", such as Invite to meet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add a sentence or two specific to this inquiry under ", "type": "text"}, {"text": "Add context", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and check the preview.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Send email to", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and the faculty member''s address. For an invitation to meet, the inquiry moves to Meeting Requested and records that the appointments link was shared, unless you untick those boxes.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Sending it yourself", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Open email draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Copy draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to send from your own mail, then ", "type": "text"}, {"text": "I sent this email", "type": "text", "marks": [{"type": "bold"}]}, {"text": " so the activity log records it. When the portal isn''t set up to send email, this is the only path.", "type": "text"}]}]}', NULL, NULL, '77595aed-d7c4-4d01-906f-873793f07658', '{academic-partnerships.submission}', NULL, 20, 'release', 'Written for the Resources backfill', false, false, 1, '2026-11-05 23:48:36.556372+00', '2026-11-05 23:48:36.556372+00', NULL),
	('d42c0047-1a5b-4ab1-9155-1c13ef073672', 'academic-partnerships-form-settings', 'guide', 'Share the inquiry form and change its settings', 'The public link, the Grove embed, and what coordinators can change.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Settings holds the public inquiry form''s link and embed, and its configuration. Everyone on the tool can read it; only coordinators can change it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Share the form", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Copy the ", "type": "text"}, {"text": "Public link", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or the ", "type": "text"}, {"text": "Grove embed code", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to paste into a Grove Responsive Embed element unchanged.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Change it (coordinators)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Untick ", "type": "text"}, {"text": "Accepting submissions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to close the form. Turn on only the partnership types you''re ready to take.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Edit the introductory and confirmation copy, and the Google Appointments URL used by Invite to meet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Edit each email template''s subject and body. Tokens such as {{faculty_name}} are filled in when a template is used.", "type": "text"}]}]}]}]}', NULL, NULL, '77595aed-d7c4-4d01-906f-873793f07658', '{academic-partnerships.settings}', NULL, 30, 'release', 'Written for the Resources backfill', false, false, 1, '2026-11-05 23:48:36.556372+00', '2026-11-05 23:48:36.556372+00', NULL),
	('377411a5-b19e-445c-81d6-4ac3f11f5a0b', 'underwriting-exceptions-makegoods-affidavits', 'guide', 'Exceptions through affidavits: overview', 'How missed credits, makegoods and affidavits fit together; use the dedicated guides for current controls.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "For current actions, use ", "type": "text"}, {"text": "Exceptions and makegoods", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/underwriting/underwriting-exceptions-and-makegoods"}}]}, {"text": " and ", "type": "text"}, {"text": "Affidavits", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/underwriting/underwriting-affidavits"}}]}, {"text": ". The overview below describes how those workflows connect.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "When a credit airs as anything other than scheduled, an exception is raised automatically — nobody has to go looking for it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Exceptions", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The exceptions list filters to all, open, awaiting agency approval, or resolved.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On one, review what happened, record the agency''s answer if the contract requires approval, schedule a makegood if one''s owed, then set a resolution and select ", "type": "text"}, {"text": "Save", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Waiving an exception needs a manager — anyone else''s attempt is refused.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Makegoods", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A makegood awaiting a slot is normally picked up automatically the next time auto-fill runs. To schedule one by hand, pick an open break and a message (default: next in rotation) on the makegoods list, and select ", "type": "text"}, {"text": "Schedule makegood", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Affidavits", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose the contract and a period, and select ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " again to confirm. The affidavit page previews the document, with a ", "type": "text"}, {"text": "Preview draft PDF", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button before certification.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Certifying is manager-only: fill in a title and select ", "type": "text"}, {"text": "Certify and store PDF", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". This freezes the affidavit as a signed PDF, with its checksum recorded — a correction afterward is always a new affidavit, never an edit to this one.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An affidavit lists only aired credits, in Central time, with no dollar amounts — a rep sends it to the client directly.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Re-generating for the same contract and period is fine; it produces a new, separately versioned affidavit rather than overwriting the previous one.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.exceptions,underwriting.affidavits}', NULL, 38, 'editor', 'Reclassified combined guide as overview; linked specialized guides and assigned screen contexts', false, false, 2, '2026-11-05 23:48:36.644012+00', '2026-11-05 23:48:39.917661+00', NULL),
	('5ed0ee31-d996-40e4-ab6a-d941f118ea26', 'underwriting-copy-and-placement', 'guide', 'Copy, rotation, and placing a credit', 'Link a contract''s messages, weight their rotation or dedicate one to a line where the order says so, then place a credit manually or let auto-fill do it.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A credit needs approved ", "type": "text"}, {"text": "copy", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/copy"}}]}, {"text": " behind it before it can run anywhere.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Copy", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the contract''s Copy tab, select ", "type": "text"}, {"text": "+ New message", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Link existing…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to attach a script. A draft message can be approved right from its card — only approved copy rotates or gets placed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Copy shared across more than one contract shows which others use it, right on its edit card.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Rotation", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Rotation is automatic: each contract cycles through its own linked messages in broadcast order, with nothing for staff to pick. An aired, frozen, or manager-overridden placement is a fixed point that rotation won''t move.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Rotation weights", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "By default every message on a contract airs equally often. When an order asks for one message to air more than another, open ", "type": "text"}, {"text": "Rotation weight…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from the message''s menu and set a whole number from 1 to 20.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Messages rotate in proportion to their weights: a weight of 2 against 1 airs the first twice as often, spread through the run rather than in a block.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Weights compare messages that rotate together: the contract''s general messages, or the messages dedicated to one line. Only approved messages count.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The card reads ", "type": "text"}, {"text": "airs 2 of every 3 spots", "type": "text", "marks": [{"type": "bold"}]}, {"text": " once the weights differ. Aired credits count toward the ratio, and changing a weight re-sequences only credits that have not aired.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A weight belongs to the message on this contract; the same message on another order keeps its own.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "A message for one line", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Some orders give a message to one line rather than to the whole contract — for example, “For Carpool: #1” and “For Total Program: #2”. When linking the message, choose the line under ", "type": "text"}, {"text": "Use on", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or use ", "type": "text"}, {"text": "Use on one line only…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from a linked message''s menu.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A message dedicated to a line airs only on that line.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "That line then airs only its own messages. If it has more than one, they rotate among themselves.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Every other line keeps rotating the contract''s other messages, as before.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If a revision replaces the line, the message''s card shows ", "type": "text"}, {"text": "Line replaced — set it again", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; choose the new line.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Placing a credit", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Manually, from a schedule line''s ", "type": "text"}, {"text": "Place a credit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " link: pick an open break (grouped by period), confirm or change the suggested message (already the next one in rotation), and select ", "type": "text"}, {"text": "Place credit", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Only messages that may air on that line are offered.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Or let auto-fill do it: ", "type": "text"}, {"text": "Auto-fill this line", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from a line''s own menu, ", "type": "text"}, {"text": "Auto-fill this contract", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for every line on one contract, or ", "type": "text"}, {"text": "Auto-fill everything", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for every active contract — the same placement path either way, just run in a loop.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A same-underwriter or same-industry adjacency warning is advisory on the manual placement form — it''s shown, never blocked.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Auto-fill generates the rundowns it needs as it goes, so a fresh contract can be filled for its whole campaign in one click even before a rundown for those dates exists yet.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.contract,underwriting.copy}', NULL, 30, 'release', 'Contextual screen link in existing instructions', false, false, 4, '2026-11-05 23:48:36.644012+00', '2026-11-05 23:48:39.951425+00', NULL),
	('a1318d88-698d-42e0-b368-df5ba1a1d951', 'log-daily-rundown-and-console', 'guide', 'Running the daily rundown and host console', 'Generate a rundown, fill its breaks, and run it live — one screen for building and broadcasting.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "rundown''s screen", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log"}}]}, {"text": " does double duty: build it ahead of time, then run the same screen live once you start the broadcast.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Generate and fill", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Today screen, select ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " next to a program that doesn''t have a rundown yet for that date.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open it. Hover the thin line between items in a break to fill it — search the eligible content library, add today''s weather, or create a one-off live read right there.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Go live", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Start broadcast", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the sidebar. The current break is highlighted, and the mid-broadcast controls appear on every unconfirmed item across the whole rundown.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "During the broadcast", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On an underwriting credit, confirm it with ", "type": "text"}, {"text": "Yes, aired", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "No — flag it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (choosing a reason). Ordinary content has no aired/missed confirmation — only a credit carries that obligation.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Move any item with its ", "type": "text"}, {"text": "⋮", "type": "text", "marks": [{"type": "bold"}]}, {"text": " menu, or drag it to a different break.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Wrap up", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Once the program''s shift has ended, a Wrap-up panel appears in the sidebar and lists anything unresolved. Before then it is hidden, to leave room. Optionally attest or mark items aired in bulk, then select ", "type": "text"}, {"text": "Submit rundown", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — a checkpoint, not a lock. A correction after submission works exactly the same as before it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Aired, missed, and move actions are queued on your device and sent once you''re back online — a dropped connection doesn''t lose them.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Adding content to a break needs a live connection, since it''s a request to the server rather than a queued action.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The sidebar''s ", "type": "text"}, {"text": "Florida News Exchange", "type": "text", "marks": [{"type": "bold"}]}, {"text": " card lists the three newest stories other Florida stations shared through PRX, each linking to its PRX page in a new tab. ", "type": "text"}, {"text": "All stories", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the full list on the Sources tab.", "type": "text"}]}]}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.rundown}', NULL, 40, 'release', 'Wrap up appears when the program ends; Florida News Exchange card', false, false, 3, '2026-11-05 23:48:36.605771+00', '2026-11-05 23:48:40.118524+00', NULL),
	('493a2ac4-d894-490a-ab9b-58e5bc027f27', 'log-content-library', 'guide', 'Building the content library', 'Find, add, and approve news, promos, and other spots, or import the station''s existing DAD cut library in bulk.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The content library holds everything a rundown can pull from — news, promos, membership messages, PSAs, legal IDs, and more. Anyone with On Air access can add to it, not just the program director.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find an item", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Type in the search box to search titles, DAD cart numbers, and scripts. The list updates as you type; pressing Enter searches straight away.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Clear the box to see the whole library again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use the status chips (All, Approved, Draft, Retired) and the content type chips to narrow the list. Each status chip shows how many items it would show.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The library shows 25 items a page, newest first. The page links under the table move between pages.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add a content item", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the library, select ", "type": "text"}, {"text": "+ New content item", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fill in a title, content type, summary, script, expected duration, and effective dates.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Create content item", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add its components", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the item''s page, expand ", "type": "text"}, {"text": "Add a component", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — choose a type (live intro, recorded audio, live outro, or an optional tag), a sequence, a duration, and a script. Select ", "type": "text"}, {"text": "Add component", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A required component counts toward the item''s total time; an optional one doesn''t.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Approve it", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An item starts as a draft. Set its status to Approved, in the Status panel on its page, before it can be picked for a rundown — only approved items are offered when filling a break.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Import the station''s DAD cut library", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "From the library, open the import screen and upload the Standard Library export from DAD (Library screen → Generate Reports → Standard Library) — optionally with its companion Groups report.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Preview import", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to see the plan: new items, updates to existing ones, and anything it couldn''t place.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Import", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to confirm.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "There''s no audio upload here. The station''s playback system (ENCO/DAD) is where recorded material actually plays from — a content item is metadata and a script, not an audio file.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Re-running the import later updates an already-imported item in place (matched by its DAD cart number) instead of creating a duplicate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Retiring stale content is an ordinary status change, not a delete — nothing in the library is ever removed outright.", "type": "text"}]}]}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.library}', NULL, 10, 'release', 'Station name removed so the guide reads for any station', false, false, 6, '2026-11-05 23:48:36.605771+00', '2026-11-05 23:48:43.198941+00', NULL),
	('b8c1f09e-4659-4f0a-aa4a-73d42a71c973', 'underwriting-set-up-a-contract', 'guide', 'Setting up a contract', 'Walk a signed order through five steps, from the sponsor and total down to activation.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A contract''s setup is five steps end to end, taking a signed order from a blank form to something that can actually be scheduled.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Order", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select the underwriter, enter the order number, the sponsorship total, the campaign''s run dates, a sponsorship category, and an account rep, with optional notes. Leave the order number blank if the order doesn''t print one; the contract then shows “No order number”.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Continue to schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — or, instead of typing everything by hand, upload the signed agreement under “Or start from the signed agreement” and select ", "type": "text"}, {"text": "Create from the agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to have it read from the document. What you''ve already typed always wins over its reading.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Schedule", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Add each line from the order — pool or program, days, dates, spot count, and the rest — through the schedule line editor, one at a time. A time window that ends at 12:00 AM runs until midnight. Select ", "type": "text"}, {"text": "Continue to copy", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Copy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Link or create the underwriting messages this contract will run, on the Copy step — the same panel the contract''s own Copy tab uses later. Select ", "type": "text"}, {"text": "Continue to traffic policy", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Traffic policy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Set the total spots on the order, the preemption/makegood policy, whether an affidavit is required, whether makegoods need agency approval, and separation. Select ", "type": "text"}, {"text": "Save policy", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Continue to review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review and activate", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The contract page shows a “Ready to activate?” checklist against the order, agreement, schedule, copy, and policy, each with a fix-it link if something''s missing. Select ", "type": "text"}, {"text": "Activate contract", "type": "text", "marks": [{"type": "bold"}]}, {"text": " once it''s clear.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How an order''s wording becomes lines", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An instruction that offers a choice stays one line in a pool that covers every choice: “Drive Time” runs in the Drive Time pool (AM or PM Drive), and “either Saturday or Sunday Weekend Edition” in the Weekend Edition pool.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An order that splits its count gets one line per part: “3 per week: 1 Living on Earth, 1 AM/PM Drive, 1 Science Friday” is three lines.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "“Rotating” between two dayparts alternates week by week: two every-other-week lines, the second starting a week after the first.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An instruction that names no pool or program runs anywhere, in Total Program Rotation, narrowed by its days and times.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A product like the Learning Minute is a kind of credit, not a pool: its line keeps the order''s day and exact time.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Nothing schedules until activation — a draft contract can be edited freely, and can be deleted outright if it turns out not to be needed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "“Create from the agreement” reads a scanned or photographed signed order with one model call; it never invents a sponsor, program, pool, or order number. Anything that isn''t a schedule of broadcast credits, such as app or website ads, is listed on the schedule step for you to handle.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.contracts,underwriting.contract}', NULL, 20, 'release', 'Optional order numbers, midnight windows, and how an order''s wording becomes lines', false, false, 4, '2026-11-05 23:48:36.644012+00', '2026-11-05 23:48:37.426941+00', NULL),
	('c429d78e-e9fc-4ea3-98a7-d20f20de727a', 'log-station-ids', 'guide', 'Station IDs', 'Pinning the hourly legal ID on a clock, so every hour has one.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The station identifies itself every hour, as close to the top of the hour as it can, at a natural break. The legal ID is pinned on each ", "type": "text"}, {"text": "clock''s page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": ", the same way as any other pinned content, and goes into every rundown made from that clock.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Pin the station ID", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the program, then ", "type": "text"}, {"text": "Open clock", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select the slot that takes the legal ID, usually the last break before the top of the hour.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Pin content", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and choose the station ID. Leave the hour on ", "type": "text"}, {"text": "Every hour", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and no days checked, then select ", "type": "text"}, {"text": "Pin content", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If an hour on the clock in effect has no legal ID, a warning at the top of the clock''s page says which.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If no slot takes a legal ID yet, the warning says so. The program director marks the slot eligible for a legal ID first.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A new clock version starts without pins, so pin the ID again on the new version.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A pinned ID goes into rundowns made from then on. Rundowns already made keep what they have.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The program director or traffic can pin and remove the ID.", "type": "text"}]}]}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.clock}', NULL, 44, 'release', 'Contextual screen link in existing instructions', false, false, 3, '2026-11-05 23:48:38.18531+00', '2026-11-05 23:48:39.951425+00', NULL),
	('851343c0-e37b-4848-8c1d-eaa7d603a32b', 'log-import-a-program-log', 'guide', 'Import a program log', 'Build a day''s rundowns from the traffic system''s program log.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "program log", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/import"}}]}, {"text": " is the day''s schedule as the traffic system exports it, as a PDF. Importing it builds that day''s rundowns with each break and its credits already in place.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Start from Today", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Today tab, choose the day, then select ", "type": "text"}, {"text": "Import program log", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". If some programs have no rundown yet, the notice above the table links there too.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose the PDF and select ", "type": "text"}, {"text": "Preview import", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Reading the log can take a minute, and nothing is written yet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Review the plan. If the log is dated a different day than the one you started from, a notice says so: rundowns are created for the log''s date.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Check the rows that could not be placed, any new underwriters or copy, and any library scripts that will change. Then select ", "type": "text"}, {"text": "Import", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "You land on Today for the log''s date, where the new rundowns are listed.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "If a rundown already exists", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A program that already has a rundown for that date is skipped and named in the result. The import stays on its own page in that case so the reasons are easy to read, with a link back to Today.", "type": "text"}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.import}', NULL, 25, 'release', 'Contextual screen link in existing instructions', false, false, 2, '2026-11-05 23:48:36.971306+00', '2026-11-05 23:48:39.951425+00', NULL),
	('5c2b8a95-9fae-413e-828f-f5548a017036', 'underwriting-migrate-legacy-agreements', 'guide', 'Migrate legacy agreements', 'Load a manifest of existing agreements, match each to its signed document, import them as draft contracts, and review the results.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Administrators use this screen to bring agreements from the station''s legacy records into Traffic. Open it from the ", "type": "text"}, {"text": "Contracts list", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": ": ", "type": "text"}, {"text": "Migrate legacy records", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It lists every batch with how far along it is and what it needs next.", "type": "text"}, {"text": " Agreements are the first of its two tabs; active copy from RadioTraffic comes in on the second, Copy.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Start a batch", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "New batch", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", name the batch, and choose where the facts come from: ", "type": "text"}, {"text": "A spreadsheet of agreements", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (recommended) or ", "type": "text"}, {"text": "Documents only", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For a spreadsheet, choose the manifest CSV or paste its rows. Every row is checked before anything is saved. A row that can''t be read, or whose sponsor isn''t on file, is listed first. When a close name is on file, select ", "type": "text"}, {"text": "Use it", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; otherwise add the underwriter under Underwriters and load the manifest again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Load and continue", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Rows that still need a fix are left out.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The manifest needs the underwriter and the document''s file name in each row; the order number, run dates, sponsorship total, contract type, Drive file id, documentation status, and notes are optional. ", "type": "text"}, {"text": "Download a template", "type": "text", "marks": [{"type": "bold"}]}, {"text": " gives the column names.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Choose the documents", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Choose the folder of signed agreements. Each entry is matched to its file by name. Anything that didn''t match cleanly is listed under ", "type": "text"}, {"text": "Needs attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with what to do: use a close match, choose the file, pick which entry a shared file belongs to, or choose a copy under 10 MB. Files the manifest doesn''t name can be imported too, with every fact read from the document.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Import", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Import", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Three agreements are read at a time, each the same way ", "type": "text"}, {"text": "Create from the agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " reads a single order, and each takes a minute or two. Keep the page open until the run finishes, or select ", "type": "text"}, {"text": "Stop after the ones reading", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". If the reading service asks the portal to slow down, the run pauses and carries on by itself.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The manifest''s facts win over what the document says; the schedule comes from the document. Each entry becomes a draft contract, which schedules nothing until someone activates it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The batch page opens on ", "type": "text"}, {"text": "Needs a look", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": drafts where the document disagrees with the manifest, or where an instruction couldn''t be saved as a schedule line. Open a row to see each disagreement side by side, and select ", "type": "text"}, {"text": "Enter on the schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for the lines to enter by hand. ", "type": "text"}, {"text": "Ready to activate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " means nothing was flagged; the draft still needs a look before it''s activated. A failed entry shows why; fix the cause and select ", "type": "text"}, {"text": "Run again", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Running it again", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Importing again never creates a second contract for an entry that already has one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Loading a corrected manifest under the same batch name updates entries that haven''t been imported. Keep each row''s key the same.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To redo an imported entry, delete its draft contract; the entry can then be imported again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A document that has already been imported, under any entry, is not imported again.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.migration}', NULL, 90, 'release', 'Contextual screen links preserved in the existing guide', false, false, 6, '2026-11-05 23:48:37.229738+00', '2026-11-05 23:48:39.862284+00', NULL),
	('dede3696-65a8-4c61-a984-f8eb0df23ffc', 'underwriting-exceptions-and-makegoods', 'guide', 'Exceptions and makegoods', 'When a credit misses, decide what happens, schedule the makegood, and let it close itself.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "An ", "type": "text"}, {"text": "exception", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/exceptions"}}]}, {"text": " appears the moment a host records an underwriting credit as missed or moved. There''s nothing to check for: if a credit didn''t air as scheduled, it''s on this list.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The list", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Each row is one missed credit, with its makegood beside it. The filters follow the steps of resolving a miss, and the list opens on the first one with anything in it:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Need a decision", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": no makegood yet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Waiting on the agency", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the order says the agency approves makegoods, and it hasn''t answered.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Makegood awaiting a break", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": a makegood exists; auto-fill will place it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Makegood scheduled", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": its break is chosen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Resolved", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "All", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Working an exception", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If the order needs the agency''s approval, record its answer under ", "type": "text"}, {"text": "Agency''s answer", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Nothing schedules a makegood until then.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Under ", "type": "text"}, {"text": "Makegood", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", select ", "type": "text"}, {"text": "Create a makegood", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". By default auto-fill places it, ahead of regular credits. To choose the break yourself, select ", "type": "text"}, {"text": "Pick a break now", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Under ", "type": "text"}, {"text": "Resolve", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose what happens: make it good, accept the alternate airing, waive, or close with no action. Rarer decisions are under ", "type": "text"}, {"text": "More decisions", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An exception closes itself when its last makegood airs. There''s no separate step to close it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A makegood counts toward the period the original credit missed, so it never counts as an extra unit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Waiving a credit needs an underwriting manager.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A resolved exception can be reopened from its own page.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.exceptions}', NULL, 40, 'release', 'Contextual screen links preserved in the existing guide', false, false, 2, '2026-11-05 23:48:37.648014+00', '2026-11-05 23:48:39.862284+00', NULL),
	('d88ff25e-ed3c-4c2a-8250-71a72f97bf81', 'underwriting-migrate-legacy-copy', 'guide', 'Migrate legacy copy', 'Bring active copy in from a RadioTraffic export, answer what it can''t decide on its own, and import.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Administrators use this screen once, to bring the station''s active underwriting copy in from RadioTraffic. Open it from the ", "type": "text"}, {"text": "Contracts list", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": " (", "type": "text"}, {"text": "Migrate legacy records", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then the ", "type": "text"}, {"text": "Copy", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab) or from the Copy library (", "type": "text"}, {"text": "Import from RadioTraffic", "type": "text", "marks": [{"type": "bold"}]}, {"text": ").", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Choose the export", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In RadioTraffic''s “Active Copy by Underwriter” workbook, use File › Save As › CSV, then choose that file. Title lines above the header row are fine. Columns are found by name: Underwriter, Copy Name, Cart, Length, Start Date, End Date and Script. Nothing is written until you import.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Most rows need nothing from you. The screen leads with the few questions it can''t answer on its own, each with a short set of choices:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "New underwriter", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": a name that isn''t on file. Add it, choose the underwriter it really is, or leave its rows out.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Which contract", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": more than one agreement covers the copy''s dates, or the copy is for a product (a Learning Minute) no agreement is for. The answer covers all of that underwriter''s copy, so a rotation is never split between contracts.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Which flight", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": event copy whose name fits more than one flight.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Changed wording", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the portal has copy with the same name and cart but different words. Where the difference is a few characters, the portal''s copy is usually the damaged one and using RadioTraffic''s wording is recommended; where the portal filled in a spot number RadioTraffic leaves blank, keeping the portal''s is. A genuinely new message is added as its own copy. The portal''s copy is only changed when you choose it.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "A recommended answer is already chosen and shown folded, with Change beside it. Rows waiting on an unanswered question stay out of the import; everything else can come in now.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How rows are matched", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An underwriter is matched by name, ignoring punctuation, apostrophes, “&” and plurals. A few names RadioTraffic spells differently, such as the FPM accounts, are matched from a fixed list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Copy already in the portal is recognised by its script, however it got there, and reused. Its dates are set to RadioTraffic''s; a missing cart is added. Nothing else about it changes.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "New copy comes in approved, with RadioTraffic''s dates. A script that asks the host to play a recorded spot is stored as recorded, at the export''s length; anything read aloud is a live read, planned at its read time. The cart number is kept as RadioTraffic''s reference.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Copy is linked to a contract only when exactly one current agreement fits its dates. App and digital agreements are never used for broadcast copy. Event copy is scoped to the flight it names. Linked copy joins that contract''s rotation; copy with no agreement stays with its underwriter and can be linked later from the contract''s Copy tab.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Placeholders (“copy holder”) and rows that aren''t underwriting copy, such as the EAS test, are left out. WUWF Day Sponsor copy comes in under its own underwriter with no contract.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Running it again", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It is safe to run the same export again, or a newer one. Copy already here is recognised and skipped, links that exist are left alone, and a message that failed the first time is picked up. Each import is recorded in the audit log.", "type": "text"}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.migration-copy}', NULL, 91, 'release', 'Contextual screen links preserved in the existing guide', false, false, 2, '2026-11-05 23:48:37.464194+00', '2026-11-05 23:48:39.862284+00', NULL),
	('b9152f83-3780-468c-b97f-d03636c2805a', 'underwriting-contract-page', 'guide', 'The contract page', 'Schedule, Copy, and Agreement: what airs, what''s read, and what was agreed.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "contract''s page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": " has three tabs.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Schedule", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each line of the order, with its progress. Switch to ", "type": "text"}, {"text": "By date", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to see every placement in air order, filtered to upcoming, aired, or not aired.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "When the order changes, select ", "type": "text"}, {"text": "Revise the schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A draft revision shows as a banner; ", "type": "text"}, {"text": "Review and activate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows exactly what it would clear before you confirm.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Flights, for orders grouped by event, are at the bottom of the tab.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Copy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The messages this contract runs, and how they rotate.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Agreement", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The signed agreement.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The traffic policy, shown as read. Select ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The contract''s affidavits.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Its revision history.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.contract}', NULL, 25, 'release', 'Contextual screen links preserved in the existing guide', false, false, 2, '2026-11-05 23:48:37.648014+00', '2026-11-05 23:48:39.862284+00', NULL),
	('05a46041-4eda-40a8-8176-26e1c77d2cd0', 'underwriting-dashboard', 'guide', 'The dashboard', 'What needs attention today, grouped by job: missed credits, scheduling, and affidavits.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The dashboard opens on what needs attention, in three groups. Every number links to the list it counts, filtered the same way.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Missed credits", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Need a decision", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": an exception with no makegood yet, or one the agency declined.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Waiting on the agency", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the order''s makegoods need the agency''s approval, and no answer is recorded yet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Makegoods awaiting a break", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the next auto-fill places these first.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Scheduling", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Units not yet scheduled", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": open periods on active contracts that auto-fill hasn''t reached yet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Capacity conflicts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": lines that can''t be placed in the next 14 days, listed below with what''s blocking each one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To record in DAD", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": messages under a new DAD cut that production hasn''t marked recorded yet.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Affidavits", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": contracts with aired credits not yet covered by an affidavit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Awaiting your signature", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": generated affidavits ready to sign. Only underwriting managers see this one.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Auto-fill everything", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the right-hand column to fill every active contract''s open periods, makegoods first.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If you can open On Air, ", "type": "text"}, {"text": "Log of record", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the right-hand column shows whether the DAD log is released for today and the next two days.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Finding your way", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Traffic has five tabs, one for each kind of job:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dashboard", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is this page.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Contracts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is every agreement, and where schedules, copy and placements are worked.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Needs attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds Exceptions and Affidavits. The number beside the tab counts exceptions waiting on a decision, plus affidavits waiting for a signature if you are an underwriting manager, and disappears when there are none. Choose Exceptions or Affidavits in the grey row beneath the tabs.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Library", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds Underwriters and Copy.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sits at the right edge: inventory pools, industries and the migration of legacy records.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The grey row beneath a tab lists that tab''s pages. The page you are on has a grey background.", "type": "text"}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.dashboard}', NULL, 10, 'release', 'Added how the five tabs are organised', false, false, 6, '2026-11-05 23:48:37.648014+00', '2026-11-05 23:48:40.080207+00', NULL);
INSERT INTO public.rc_articles (id, slug, kind, title, summary, body, area, owner_role, tool_id, screen_keys, released_on, sort_order, source, version_note, needs_review, edited_since_release, version, created_at, updated_at, updated_by) VALUES
	('36f137cd-09ae-4085-9b57-c79d48ab87aa', 'underwriting-copy-in-dad', 'guide', 'Copy in DAD', 'Each message''s DAD cut: the number to record it under, or the existing DAD spot it plays.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Every ", "type": "text"}, {"text": "message", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/copy"}}]}, {"text": " on file has a DAD cut: the number DAD plays it from. A recorded spot plays its recording. A live read is read by the host when someone is on air, and DAD plays its recorded version in hours with no host.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "New recording", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A new message gets the next free cut when you save it, in the form ", "type": "text"}, {"text": "00548A", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Record the message into DAD under that number.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Messages that were on file before cuts existed kept their old number where only one current message used it, so Loyalty Credit Union''s copy 1 is ", "type": "text"}, {"text": "00013A", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To use another number, choose ", "type": "text"}, {"text": "Use a different cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the copy''s edit page. A cut belongs to one message, so a number already in use is refused.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Recorded in DAD", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A new cut isn''t in DAD until someone records the message under it. The copy page shows ", "type": "text"}, {"text": "To record", "type": "text", "marks": [{"type": "bold"}]}, {"text": " until production marks it with ", "type": "text"}, {"text": "Mark recorded", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "To record", "type": "text", "marks": [{"type": "bold"}]}, {"text": " filter in the copy library, and the dashboard''s ", "type": "text"}, {"text": "To record in DAD", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tile, list every message that can still air and isn''t recorded. Production can mark each one from that list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Changing a message''s cut, or the wording of a message under a new cut, clears the mark, since the recording no longer matches.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A message that plays an existing DAD spot is already recorded.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The DAD log can''t be released while a credit in automated hours isn''t recorded.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Existing DAD spot", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Some copy asks the host to play a spot that''s already in DAD, such as a Learning Minute in the PPA group. Choose ", "type": "text"}, {"text": "Existing DAD spot", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and search DAD''s library by cut number or title.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Copy like this starts without a cut. It shows ", "type": "text"}, {"text": "Pick a DAD spot", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the copy library, and the ", "type": "text"}, {"text": "Needs a DAD cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " filter lists every message still waiting.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The copy page''s ", "type": "text"}, {"text": "Copy", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button puts the cut on the clipboard for pasting into DAD.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the rundown, a recorded spot shows the cut the host fires. A live read shows no cut.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.copy}', NULL, 35, 'release', 'Contextual screen link in existing instructions', false, false, 3, '2026-11-05 23:48:37.768979+00', '2026-11-05 23:48:39.951425+00', NULL),
	('28d2b516-e45e-4948-9ce0-5bec78d7b0c2', 'log-npr-and-weather', 'guide', 'Sources: NPR, weather and Florida News Exchange', 'Check the outside feeds On Air reads: a program''s NPR stories, the current forecast, and stories shared by other Florida stations.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/sources"}}]}, {"text": " tab holds the outside feeds On Air reads. It opens on one card per source, showing whether its saved data is current, when it was last updated, and what it holds. Select a card''s ", "type": "text"}, {"text": "Open", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button to go to that source''s page, and ", "type": "text"}, {"text": "← Sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to come back.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What the cards say", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Up to date", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the saved data is inside its normal refresh window.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Stale", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the saved data is older than that, or the last refresh failed. What was saved is still shown.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Not fetched yet", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": nothing has been read from this source so far.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Not configured", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the portal has no access set up for this source yet.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "NPR", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the NPR page, choose a program and a show date, then select ", "type": "text"}, {"text": "Switch", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The table lists each story''s estimated air time (marked with “~”, since NPR doesn''t supply exact times), title, teaser, and length.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Refresh", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to pull the latest episode data.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The NPR card reports the most recently read episode. NPR is read one program and date at a time, so it is refreshed from the NPR page rather than the card.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Weather", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The weather page shows the current forecast as a row of days, with the text for today and tonight under it. Select a day to read its forecast. Select ", "type": "text"}, {"text": "Refresh", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the page or on the weather card to force an update.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Weather alerts", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "When the National Weather Service has a warning, watch or statement active for the studio''s area, a row appears under the forecast. It names the most severe alert and how many more there are. Select the row to see them all, select an alert to read it, and select ", "type": "text"}, {"text": "Full NWS text", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for everything the Weather Service said.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Warnings come first, then watches, then statements.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The same row appears above ", "type": "text"}, {"text": "Full forecast", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in a rundown''s Weather panel and on a weather item''s card.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Alerts are checked every 15 minutes. If a check fails, the row shows the last alerts it had, with the time it last checked. If alerts have never been checked, the page says so instead of showing nothing.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Florida News Exchange", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This page lists the stories other Florida stations shared through PRX in the last 24 hours, newest first. A wrap and its cut are listed together. Each version has a player (its menu has a download option), the feed description, and a link to its page on PRX.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The feed description is often only a summary. The full script can be on the story''s PRX page: select ", "type": "text"}, {"text": "Open on PRX", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A hold note from the feed, such as Hold until 10/8, appears beside the story. It is there for you to follow; the portal does not enforce it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Add to library", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to open the new content item form with the title, the type News, and a summary already filled in. The summary holds the description, any hold note and the PRX link. Paste the script, save, then add its components (live intro, recorded audio, outro) on the item''s page, as for any library item.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Audio is not copied into the portal. Load it into DAD to air it. The links in the feed expire after an hour, so if a player will not play, reload the page.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sources refresh themselves when you open them and their data is past its window. Refresh is a manual option, not something you need to do routinely.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A fetch failure shows as a plain message, with whatever was last read still on screen. No page goes blank because of a temporary outage.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "NPR''s estimated times need a rundown to already exist for that program and date. Without one, the table has nothing to anchor its estimates to.", "type": "text"}]}]}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.sources}', NULL, 50, 'release', 'Station name removed so the guide reads for any station', false, false, 7, '2026-11-05 23:48:36.605771+00', '2026-11-05 23:48:43.198941+00', NULL),
	('2330ed51-67a6-4097-b54c-0a7c00ddf9d8', 'log-read-a-clock', 'guide', 'Read a clock', 'The timeline and ring diagrams, hours of a longer shift, floating breaks, versions, and pinned content.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Open a clock from the program that airs on it: on the program''s page, select ", "type": "text"}, {"text": "Open clock", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The link at the top left of the clock''s page goes back to that program.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Timeline and Ring", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The diagram shows one hour of the clock. Switch between ", "type": "text"}, {"text": "Timeline", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Ring", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the top right of the diagram; both behave the same way.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The network''s structure comes first: segments, newscasts (dark), and promos and credits. Local opportunities are marked in blue: a dashed outline for optional, solid for required.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hover over or tab to a slot to read its name, times, and length. Select a slot to fix it in the side panel and the slot list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Slots list lists every slot. Hovering over a row highlights that slot in the diagram; selecting a row shows it in the side panel.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Shifts longer than an hour", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "When a program airs for more than an hour, the clock repeats every hour. Use the arrows beside ", "type": "text"}, {"text": "Hour 1 of 2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to step through the hours. The network structure is the same in each hour, but pinned content can differ, and a small number on a local slot shows how many items are pinned for the hour you''re looking at.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Floating breaks", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A break whose position isn''t fixed appears as a shaded window. A dashed edge can move and a solid edge is fixed; the darker area is always part of the break. Select it to see when it can start and end and how long it can run.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Versions", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Choose a version from the ", "type": "text"}, {"text": "Version", "type": "text", "marks": [{"type": "bold"}]}, {"text": " menu. A version can''t be edited once it exists — a correction is a new version, started with ", "type": "text"}, {"text": "+ New version", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Changing what the station can fill (program director)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select a slot, then use the buttons in its panel: ", "type": "text"}, {"text": "Edit eligibility", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a local slot, or ", "type": "text"}, {"text": "Mark eligible for local content", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a network-only one. ", "type": "text"}, {"text": "Remove", "type": "text", "marks": [{"type": "bold"}]}, {"text": " takes a slot out of local eligibility.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Pinning content (program director or traffic)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A pin puts the same content item into a slot in every rundown made from this clock: the hourly station ID (see ", "type": "text"}, {"text": "Station IDs", "type": "text", "marks": [{"type": "bold"}]}, {"text": "), or a feature like BirdNote. Select a local slot, then ", "type": "text"}, {"text": "Pin content", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Choose the item, then the hour and days. ", "type": "text"}, {"text": "Every hour", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with no days checked covers the whole shift, every day. ", "type": "text"}, {"text": "Remove", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under a pinned item takes the pin off.", "type": "text"}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.clock}', NULL, 10, 'release', 'Station name removed so the guide reads for any station', false, false, 7, '2026-11-05 23:48:36.124228+00', '2026-11-05 23:48:43.198941+00', NULL),
	('08e43f22-c4be-4db0-945b-f76ebcc560da', 'log-automated-hours', 'guide', 'Automation', 'When no one is in the studio: weekly automated hours and one-time changes, and what they mean for credits.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Every hour is hosted unless it''s listed on ", "type": "text"}, {"text": "this page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/automated-hours"}}]}, {"text": ". In automated hours no one is in the studio, so DAD plays that hour''s underwriting credits. Open it from ", "type": "text"}, {"text": "Schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Automation", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Weekly hours", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use ", "type": "text"}, {"text": "+ Weekly hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for the routine ones, such as overnights from 8:00 PM to 5:00 AM. Pick the days, the times, and the date they start.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An end time at or before the start runs past midnight. The early-morning part belongs to the day the hours started, so Saturday 8:00 PM – 5:00 AM covers early Sunday.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Weekly hours can cover a whole program or just some of its hours. The ", "type": "text"}, {"text": "Programs in these hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": " column shows what''s on the air then.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "One-time changes", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use ", "type": "text"}, {"text": "+ One-time change", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for a holiday, a host out, or a special. Choose ", "type": "text"}, {"text": "Automated", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to automate hours that are normally hosted, or ", "type": "text"}, {"text": "Live", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to host hours that are normally automated.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A one-time change wins over the weekly hours. One-time changes can''t overlap each other.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Midnight to midnight covers whole days: Thanksgiving is Thursday 12:00 AM until Friday 12:00 AM.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Week and month", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The week view draws each day''s automated hours over the programs on the air, with the hours closed to underwriting shown faintly behind them. Grey is weekly, dashed amber is automated once, and dashed blue is live once.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The month view shows each day''s automated hours. Pick a day to see its week.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A credit in automated hours needs copy with a DAD cut, since DAD plays it. A live read qualifies through its recorded version. Auto-fill leaves those breaks to copy that has one, and placing cut-less copy there is refused.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only the program director can change automated hours. Nothing is deleted: removing hours or a change takes it off the schedule.", "type": "text"}]}]}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.automated-hours}', NULL, 45, 'release', 'Contextual screen link in existing instructions', false, false, 5, '2026-11-05 23:48:37.87493+00', '2026-11-05 23:48:39.951425+00', NULL),
	('190e6cee-2d44-49ae-bc4b-2a39062598fd', 'bookings-rate-model', 'guide', 'The rate model', 'The rate card, the Inputs checklist, labor classes and pools, service packages, and adopting a version.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Rates", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab holds the production rate model: what each class of labor costs an hour, what a studio half-day, an event webcast, a field day or an editing hour costs WUWF, and the rates on the card a partner sees. Everything on the card is computed from the figures; nothing is typed in by hand.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Finding your way", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Rate card", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is where Rates opens: the rates a partner sees, computed from the figures.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Inputs", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a checklist of the four pages that feed the card — Assumptions, Labor, Resource pools and Service packages — with how many of each are validated. Select a row to open its page; ", "type": "text"}, {"text": "← Inputs", "type": "text", "marks": [{"type": "bold"}]}, {"text": " returns to the list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the change log. ", "type": "text"}, {"text": "Assets", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the equipment inventory.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Classes and pools", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Manage labor classes", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the Labor page, and ", "type": "text"}, {"text": "Manage resource pools", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the Resource pools page, list the two things the model is built from. A ", "type": "text"}, {"text": "labor class", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a kind of production staff — the production lead, student and OPS crew, later a second producer or an engineer — paid by salary or by the hour, and either charged in a strategic price (students) or baseline-funded (professionals).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "pool", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is something that can be booked — studio, field package, live package, edit suite, webcast operations — with its unit and how it is costed: a share of the shared production pool, or its own budget lines. Finance or the Director of Operations adds a class or a pool here; nothing is deleted, only retired.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A new class needs its pay figures on each draft version (the ", "type": "text"}, {"text": "Labor", "type": "text", "marks": [{"type": "bold"}]}, {"text": " page), and a new pool its figures on each draft version (the ", "type": "text"}, {"text": "Resource pools", "type": "text", "marks": [{"type": "bold"}]}, {"text": " page) and a resource on the term plan.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Versions", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The version picker at the top switches between versions. One version is ", "type": "text"}, {"text": "in use", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for estimates at a time. A version that has not been adopted is labelled provisional, and so is every figure from it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An adopted version never changes. To correct it, Finance selects ", "type": "text"}, {"text": "New version", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", which copies the chosen version''s figures and packages into a draft.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Assumptions, labor and resource pools", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Assumptions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds the budget lines — the shared production pool''s, and the webcasting pool''s own — and the two working inputs the math reads directly: the external margin and the university assessment.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Labor", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds each class''s pay figures on this version: salary and paid hours or hourly wage, the fringe or payroll load, and the external planning rate. The loaded hourly cost is recomputed from them.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Resource pools", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds each pool''s share of the shared pool (or its own lines) and its available units a year. Cost per unit is the pool''s annual cost divided by its units.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Every row names who must validate it and what that takes. Finance selects ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change a figure on a draft, and ", "type": "text"}, {"text": "Validated", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Accept as is", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to resolve it. ", "type": "text"}, {"text": "What moves the price most", "type": "text", "marks": [{"type": "bold"}]}, {"text": " re-runs the model with one figure moved.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Service packages and the rate card", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "service package", "type": "text", "marks": [{"type": "bold"}]}, {"text": " states its hours per labor class and its units per pool, plus the external market floor. Strategic cost is resource units plus the hours of every class charged in a strategic price; incremental cost adds the other classes'' hours at their loaded rate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Every rate rounds up to the next $25. The external rate is the higher of the incremental cost grossed up for the margin and the assessment, and the package''s market floor. The card lists one labor line per class.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Record for estimates", "type": "text", "marks": [{"type": "bold"}]}, {"text": " saves the card as computed, so an estimate priced later keeps the rate it was priced at. ", "type": "text"}, {"text": "Print", "type": "text", "marks": [{"type": "bold"}]}, {"text": " prints the card alone.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Adopting a version", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Finance resolves every assumption, labor figure and pool, then selects ", "type": "text"}, {"text": "Submit for validation", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A version with anything still pending cannot be submitted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Executive Director selects ", "type": "text"}, {"text": "Adopt", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", recording the Budget/Controller''s destination index for recoveries. The previous adopted version is superseded, and the new one is in use.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists who changed what on each version.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.rates}', NULL, 10, 'release', 'Assets is a page in the Rates row', false, false, 5, '2026-11-05 23:48:38.49237+00', '2026-11-05 23:48:40.080207+00', NULL),
	('0d57bc6b-2958-4c50-92b1-933944359497', 'bookings-calendar', 'guide', 'The calendar and the term plan', 'The term plan''s two envelopes, each pool''s units and windows, blackouts, holds, bookings and reserved blocks, and the booking rule.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Calendar", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/calendar"}}]}, {"text": " tab shows one term of production work: what WUWF has kept for itself, what partners have booked, and how much of the term''s capacity is left. Everything on it is measured in professional hours; a project day is eight.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The term plan", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Director of Operations creates a term plan from ", "type": "text"}, {"text": "Term plan", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the term''s dates, the airtime minutes a week the station contributes, and, for each labor class, the hours it has available for production work, an optional reserve share of them, its headcount and its hours a day. Terms can be active together as long as their dates do not overlap, and a date books against the term it falls in. A closed term is final: its figures cannot change, nothing new books into it, and a correction is a new term plan.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each pool (studio, field, live, edit) has its units for the term and the windows a booking may take, such as a studio morning or afternoon. Select ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a pool''s row to change them.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The two envelopes", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Production capacity", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows the hours available, the reserve left for strategic work, what is spoken for (bookings and holds) and open capacity. Open capacity is the hours available minus the reserve, minus holds, minus the other bookings. A class with no reserve share, such as the student crew, has no reserve: every booking of it draws open capacity. Open the month table to see how it is spread across the term.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Airtime envelope", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is read from On Air''s clocks: the avails marked as admitting a university announcement, the minutes the station already pins there, the contributed envelope from the term plan, and what is left for Traffic to sell. Airtime is placed in Traffic or On Air, never here.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Blackouts, holds, bookings and reserved blocks", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "blackout", "type": "text", "marks": [{"type": "bold"}]}, {"text": " closes dates to partner work on some or every pool, with a reason; one that spans two terms is kept once for each. A ", "type": "text"}, {"text": "hold", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is WUWF''s own use of one window, core work or maintenance, and takes the lead''s hours for that day. The director adds both with ", "type": "text"}, {"text": "+ Blackout", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "+ Hold", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "booking", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a partner''s hold on one window. The production lead or the director adds one with ", "type": "text"}, {"text": "+ Booking", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A tentative booking holds the window for 14 days and counts as taken; confirm it or release it from the list under the calendar.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Find a slot", "type": "text", "marks": [{"type": "bold"}]}, {"text": " runs the booking rule for a window without booking it, and names the nearest open windows when the one asked for is not available.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "reserved block", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a window an approved agreement holds for its partner, shown with a dotted frame until the partner''s request takes it. Other partners cannot book it until its release deadline; the director keeps or releases blocks from the agreement''s page under Partners.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The booking rule", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Every booking is checked in this order: the date is not blacked out or held for WUWF; the window is not reserved for another partner under an agreement; the window is free, with tentative bookings and reserved blocks counted as taken; the lead''s day has room for the hours; and the pricing has capacity. A strategic booking draws the reserve; an incremental or external one draws open capacity. A booking that would take more than half of a month''s remaining open hours warns but is not refused. Only the Executive Director can record an exception, and each one is written to the audit log.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.calendar}', NULL, 30, 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', false, false, 5, '2026-11-05 23:48:38.588293+00', '2026-11-05 23:48:39.815325+00', NULL),
	('2ef34a4b-8969-4827-95df-732bc23ad88a', 'bookings-requests', 'guide', 'Requests and estimates', 'A request through five stages: how it is priced, the estimate, planning and holding dates, airtime commitments, agreements, and closing a request.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Requests", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " tab lists every request for university and outside production work. A request moves through five stages — Request, Estimate, Booked, Delivered, Settled — and can be deferred, declined or withdrawn at any point before delivery. Production staff enter a request with ", "type": "text"}, {"text": "+ New request", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", naming the partner on file or a new one, what is asked for (production, airtime or both), the event dates and the contact.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How a request is priced", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Nobody picks a price. The treatment is derived from facts on the request and the estimate says why: a partner outside the university is priced ", "type": "text"}, {"text": "external", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; work recorded as strategic or applied-learning is priced ", "type": "text"}, {"text": "strategic", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when the term''s reserve covers its professional hours; everything else is ", "type": "text"}, {"text": "incremental", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Record the strategic judgment on the request''s scope (Edit in the Scope panel). ", "type": "text"}, {"text": "Change how it is priced", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lets production staff set a treatment by hand with a reason; pricing a request strategic against its derived treatment draws the reserve and is the Executive Director''s call. Every change is recorded.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Rates come from the rate card recorded for estimates on the Rates tab, and the estimate keeps the version it was first priced on. While no version is adopted every figure is provisional.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The estimate", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add a line", "type": "text", "marks": [{"type": "bold"}]}, {"text": " adds a service package (a studio half-day, a basic webcast, a field day), labor hours beyond a package, or a direct expense at cost. A package line carries the package''s hours per labor class, which is what the dates draw on.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Plan a date", "type": "text", "marks": [{"type": "bold"}]}, {"text": " adds each window the work needs — pool, date, window and the hours it takes from each class. A planned date takes nothing yet; the page runs the booking rule for every planned date and reads the result as one line, with ", "type": "text"}, {"text": "show the check", "type": "text", "marks": [{"type": "bold"}]}, {"text": " listing any date that would be refused and the nearest open windows.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Send the estimate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds every planned date tentatively for 14 days. The holds are placed all or none: a date the rule refuses stops the send and names the reason. Tentative holds count as taken for every other request.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "When the partner approves, ", "type": "text"}, {"text": "Partner approved — book it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " confirms the holds and the request is Booked. An estimate that lapses can be sent again, which re-checks its dates. ", "type": "text"}, {"text": "Mark delivered", "type": "text", "marks": [{"type": "bold"}]}, {"text": " once the work is done.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Airtime", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A request for airtime records a commitment — airings a week, length, dates, and whether it is contributed from the term''s envelope or paid. The page compares contributed commitments across requests with the envelope. The avails themselves are placed in Traffic (a message, as copy on a bonus or paid line) or On Air (a recurring feature, pinned on the clock), never here; once placed, paste the contract''s or the pin''s id so the request can show what was actually scheduled.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Under an agreement", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A partner with an approved agreement can have a request put under it from the ", "type": "text"}, {"text": "Agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel on the request''s page. The request is then priced against the agreement''s reserve share — strategic while the share has hours left, incremental beyond it — and the estimate says so.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use a reserved block", "type": "text", "marks": [{"type": "bold"}]}, {"text": " turns one of the agreement''s reserved windows into a date on the request, planned, held or confirmed to match where the estimate stands. Releasing that date hands the block back to the partner.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A package Finance has scoped to the agreement appears in the package list only for requests under it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Closing a request", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Close the request", "type": "text", "marks": [{"type": "bold"}]}, {"text": " defers, declines or withdraws it with a reason. Every hold is released and the stage it reached is kept. Declining an outside partner''s request for capacity can record the estimate''s margin as foregone for the term report. A closed request can be reopened; its dates must be planned again.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.requests,bookings.project}', NULL, 20, 'release', 'Clarified that requests include external partners as well as university units', false, false, 4, '2026-11-05 23:48:38.909524+00', '2026-11-05 23:48:39.862284+00', NULL),
	('c4235d24-a58d-4771-9581-f7c0d3cc5523', 'bookings-intake', 'guide', 'The public request form', 'How a unit or an outside organization asks for production work or airtime from outside the portal, where its request lands, and how the form is opened, worded and embedded.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A university unit or an outside organization asks WUWF for production work or airtime at ", "type": "text"}, {"text": "tools.wuwf.org/book", "type": "text", "marks": [{"type": "code"}, {"type": "link", "attrs": {"href": "https://tools.wuwf.org/book"}}]}, {"text": ", or through the same form embedded in a Grove page. No sign-in is needed and no rate appears on the form. Each submission lands on the Requests tab at the Request stage, marked as received from the public form, with the submitter''s unit named as the partner (an existing partner by the same name is reused) and the submitter as the contact.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What the form asks", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Who is asking: a name, an email, a phone, the college, department, office or organization, and whether it is part of UWF.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "What is needed: production, airtime or both; a short title; for production, which of the offered services (recorded on the request as ", "type": "text"}, {"text": "Services asked for", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — production staff add the real estimate lines); a description.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "When and where: the event or recording dates, when the finished work is needed, and a location. The form books nothing; dates are checked and held when the estimate is sent.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For airtime: airings a week, the length of each, and the first and last airing. When all three are given the request carries an airtime commitment, contributed by default, for staff to review against the term''s envelope.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Settings", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "From Requests, ", "type": "text"}, {"text": "Public form", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the form''s settings. The Director of Operations or the Executive Director decides whether the form is taking requests, edits the introduction, the confirmation shown after a request is sent and the copy shown while the form is closed, and lists the services the form offers, one a line. Everyone with access can read the settings and copy the public link or the Grove embed code; the preview beneath them shows the form as it is served.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A visitor may send at most three requests a day from one email address, and a form that was filled in faster than a person could is refused.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.intake}', NULL, 25, 'release', 'Contextual screen link in existing instructions', false, false, 2, '2026-11-05 23:48:38.993197+00', '2026-11-05 23:48:39.951425+00', NULL),
	('a7d7395f-1583-4008-b9df-b514bbbb4f65', 'bookings-partners', 'guide', 'Partners and agreements', 'Partners on file, drafting and approving an agreement, what an agreement draws from the term, and reserving, keeping and releasing blocks.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Partners", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/partners"}}]}, {"text": " tab lists every UWF unit and outside organization WUWF produces for, with its contact, its agreements and its open requests. Production staff, the Director of Operations or the Executive Director add a partner with ", "type": "text"}, {"text": "+ New partner", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; a request can also name a new partner, and the public form finds or creates one by name.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Agreements", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An agreement is a standing arrangement with one partner: its dates, a ", "type": "text"}, {"text": "reserve share", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in professional hours that its work may draw before being priced incremental, the student hours the partner funds, an airtime allowance in minutes a week, the booking and release deadlines for its reserved blocks, and the framework''s notes on direct costs, blackouts, capital and work beyond the envelope.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Draft one from the partner''s page with ", "type": "text"}, {"text": "+ Agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A draft reserves nothing and prices nothing. Its page shows ", "type": "text"}, {"text": "what this agreement would draw", "type": "text", "marks": [{"type": "bold"}]}, {"text": " against the active term: the share of the reserve, what would be left for everyone else, the airtime against the envelope, and the windows its blocks would take.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Executive Director approves it with ", "type": "text"}, {"text": "Approve the agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". From then on its terms change only with the Executive Director; the notes stay editable. ", "type": "text"}, {"text": "End the agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " stops its blocks reserving windows and keeps the pricing already recorded on open requests.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once active, the page shows consumption bars — the reserve share, funded student hours and airtime drawn by requests under it — and the requests themselves. Attach the signed agreement in the aside; everyone with access can download it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Reserved blocks", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The director reserves a window on a pool for the partner with ", "type": "text"}, {"text": "Reserve a block", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", one date or the same weekday every week to a date. Each block names its booking deadline (when the partner is expected to have a request on it) and its release deadline (when, with no request, it opens to everyone).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A block past its release deadline reads as released on its own; nothing has to be done. ", "type": "text"}, {"text": "Keep", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds it past that deadline, ", "type": "text"}, {"text": "Release", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens it early, and ", "type": "text"}, {"text": "Remove", "type": "text", "marks": [{"type": "bold"}]}, {"text": " deletes one that was reserved by mistake. A booked block is freed by releasing the request''s date.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the calendar a reserved block shows with a dotted frame until it is taken; other partners cannot book that window until its release deadline.", "type": "text"}]}]}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.partners,bookings.partner,bookings.agreement}', NULL, 27, 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', false, false, 2, '2026-11-05 23:48:39.083433+00', '2026-11-05 23:48:39.815325+00', NULL),
	('cfab6585-7f2c-4e7f-91cb-898345c0b021', 'bookings-new-request', 'guide', 'Entering a request and its estimate', 'One form creates the request, prices it and plans its dates; what the summary line says, what to do when a date does not work, and the warning badges.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A new request is also its estimate. Open ", "type": "text"}, {"text": "Requests", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " and choose ", "type": "text"}, {"text": "+ New request", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", pick who it is for, tick the service they need and give the event date. One click on ", "type": "text"}, {"text": "Create and price the estimate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts the request, prices it and plans the dates.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What you see", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "One line at the top of the request says what it is, how much work it takes, what the partner pays, whether the calendar has room, what WUWF contributes and when the estimate expires.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The rate is named in plain words: ", "type": "text"}, {"text": "University rate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (the partner pays the full cost), ", "type": "text"}, {"text": "University rate (WUWF contributing)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (the partner pays for students and equipment and WUWF contributes the staff time) or ", "type": "text"}, {"text": "Outside rate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Show calculation", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the estimate lines, how the rate was worked out and the version of the rates it came from. Most requests never need it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The dates", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The service books itself: the date you give is checked against the calendar and the dates are planned automatically. Tentative holds are placed when you send the estimate, as before.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If the date can''t work — the studio is booked, WUWF has something on, the day is full — the request shows ", "type": "text"}, {"text": "The dates need attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the reason and the nearest dates that do work. Choose one to move the event.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Adjust scope", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the way to plan dates by hand. Once you add or remove a date yourself the system stops changing them.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Strategic work", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For a UWF unit the form asks one question: is this strategic or applied-learning work? If yes, and WUWF has time set aside for it, WUWF contributes the staff time. If the time has run out the request is priced at the university rate and flagged, and it stays recorded as strategic work. You can leave it unanswered and answer from the request later.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Warning badges", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A request that is out of the ordinary carries a warning badge in the list and on its page — a rate set by hand, a booking exception, contribution time used up, or dates that need attention. An ordinary request carries none.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.requests,bookings.project}', NULL, 19, 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', false, false, 2, '2026-11-05 23:48:39.159767+00', '2026-11-05 23:48:39.815325+00', NULL),
	('31505a5e-0ba7-4416-a364-bcb3ec5082d2', 'bookings-adjust-scope', 'guide', 'Adjusting what a package includes', 'Change the hours, equipment or crew on one request without changing the package, and record the hours actually used.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A package is the usual recipe for a kind of work. When one ", "type": "text"}, {"text": "request", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " needs something different, use ", "type": "text"}, {"text": "Adjust scope", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on that line: change the hours, equipment or crew and say why. The package and the rate model are not changed, the request keeps a reference to the standard recipe and shows the difference, and the request carries a Scope adjusted badge.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An adjusted line is priced from its own cost. The package''s market floor and ceiling are scaled by the same change in cost, which is a judgment Finance should confirm. Reset the line to go back to the standard recipe.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hours used", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "After the work is delivered, confirm the hours and equipment actually used. They feed the assumed-versus-observed view in the Term report and never change a price.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.project}', NULL, 22, 'release', 'Contextual screen link in existing instructions', false, false, 2, '2026-11-05 23:48:39.340918+00', '2026-11-05 23:48:39.951425+00', NULL),
	('2d242660-9e07-4b75-bf46-19df9022989b', 'bookings-workflow-overview', 'guide', 'Bookings: from request to settlement', 'How this tool works, with contextual links to its detailed guidance.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Bookings helps WUWF evaluate a production request before accepting it: what the work requires, whether the station has capacity, and what the partner should pay. It then records delivery and actual cost. The ", "type": "text"}, {"text": "Requests screen", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " is the starting point for an individual job.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Cost and capacity are separate decisions", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "rate card", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/rates/card"}}]}, {"text": " prices a defined scope of work using labor, equipment and other costs. University strategic or applied-learning work can receive a contribution of professional staff time where an eligible reserve is available; other university work and outside work receive their applicable rates. Being eligible for a contributed rate does not guarantee an available production window.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Calendar", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/calendar"}}]}, {"text": " accounts for labor, bookable resource pools, WUWF holds, reserved blocks and term capacity. Core obligations already excluded from available hours must not be counted again as holds. The airtime envelope shown in Bookings is a planning measure; actual announcements are placed in On Air or Traffic.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "From commitment to actuals", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A request combines an estimate, feasibility checks and planned dates. A tentative hold is not final approval. Where a partner has an agreement, review it under ", "type": "text"}, {"text": "Partners", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/partners"}}]}, {"text": " and confirm whether the requested work and any reserved blocks fall within its terms. After delivery, production confirms resources used; Finance posts the settlement. Actual effort affects WUWF''s measured cost, but does not automatically change the amount quoted to the partner.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Use the ", "type": "text"}, {"text": "Term report", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/report"}}]}, {"text": " to compare estimated work with settled results and inform future rate and capacity decisions. For specific buttons, stages and permissions, follow the detailed guides attached to each screen.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.requests,bookings.calendar,bookings.project}', NULL, 5, 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', false, false, 4, '2026-11-05 23:48:39.657062+00', '2026-11-05 23:48:40.000183+00', NULL),
	('11c15dd3-b605-4109-baef-9bd6aaf12c53', 'traffic-workflow-overview', 'guide', 'Traffic: from signed order to fulfillment', 'How this tool works, with contextual links to its detailed guidance.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Traffic turns a signed underwriting order into an accountable broadcast obligation. Start with ", "type": "text"}, {"text": "Contracts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": ": identify the sponsor, dates, flights, placement quantities and any restrictions before activating an order.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "An eligible slot is not an obligation fulfilled", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A contract may require a specified number of credits per week, on exact dates or within particular programs or inventory pools. Eligibility describes where a credit could air; demand describes what the signed order requires. Reconcile both when setting up the schedule. The ", "type": "text"}, {"text": "Traffic dashboard", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting"}}]}, {"text": " surfaces work needing attention.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A credit also needs approved, eligible copy. The ", "type": "text"}, {"text": "Copy library", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/copy"}}]}, {"text": " manages scripts and DAD cut references. Approval allows copy to be scheduled; a correct, recorded DAD cut is additionally necessary for unattended playback. Rotation weights determine how approved messages are distributed, but must respect line-specific copy restrictions.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Scheduled is not the same as aired", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Check fulfillment against broadcast evidence, not just the number of placed credits. Handle misses and preemptions under ", "type": "text"}, {"text": "Exceptions", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/exceptions"}}]}, {"text": ", observing any agency-approval requirement for makegoods. Prepare ", "type": "text"}, {"text": "Affidavits", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/affidavits"}}]}, {"text": " from reconciled activity. For automation exports, use On Air''s ", "type": "text"}, {"text": "DAD log", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/dad-log"}}]}, {"text": "; releasing a file does not itself confirm import or playout.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Payment processing is separate from scheduling. For an approved card charge, use the station procedure ", "type": "text"}, {"text": "Process an underwriter card payment", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/procedures/process-an-underwriter-card-payment"}}]}, {"text": ".", "type": "text"}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.contracts,underwriting.copy,underwriting.exceptions}', NULL, 5, 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', false, false, 4, '2026-11-05 23:48:39.657062+00', '2026-11-05 23:48:40.000183+00', NULL),
	('2f49cb16-4c40-49e6-ae7d-f8346d4e3923', 'bookings-term-report', 'guide', 'The term report', 'What the term''s work cost WUWF, what partners paid and what WUWF contributed, by partner and by rate, the $500 webcast against modeled cost, and package assumptions against what was observed.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Term report", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/report"}}]}, {"text": " totals what the term''s work cost WUWF, what partners paid and what WUWF contributed. Open it from the link at the foot of the Dashboard. It reads the figures each estimate stored when it was priced, so it follows the rates in use at the time rather than today''s.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Full cost is the modeled labor, equipment and space, and direct expenses. WUWF contributes is the full cost the partner''s payment doesn''t cover, never negative. Partners pay is the total of the estimates'' lines.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The tables split the same figures by rate and by partner, count strategic requests however they were priced, and set the $500 webcast against modeled cost.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Assumed versus observed", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A read-only view compares each package''s hours with the hours confirmed after delivery, resource units planned with units used, and shows the dates refused or released by resource. It informs the next rate model version; it never changes a price.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.report}', NULL, 21, 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', false, false, 3, '2026-11-05 23:48:39.229528+00', '2026-11-05 23:48:39.815325+00', NULL),
	('310b1c15-70f2-40cc-a525-721faf939226', 'bookings-dashboard', 'guide', 'The dashboard', 'The term''s capacity bar, the airtime envelope in one line, what needs your action, this week''s dates, and the stage tiles.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Dashboard", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings"}}]}, {"text": " is where Bookings opens. It shows the active term''s production capacity as one bar — strategic bookings against the reserve, the reserve still to preserve, incremental and external bookings, hours held for WUWF''s own work, and what is open — and the airtime envelope in one line: contributed minutes a week, how much is committed to requests, and what is left.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Needs your action", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists what each open request is waiting on, filtered to your roles: a request without an estimate, an estimate about to expire or expired, a booked event that has passed and needs marking delivered, and a request that needs editorial review. A member with no role sees every item.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "This week", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the partner dates held or confirmed this week, linked to their requests.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The four tiles count open requests by stage and link to the Requests list filtered to each.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Nothing shows until the Director of Operations has activated a term plan on the Calendar tab.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.dashboard}', NULL, 5, 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', false, false, 2, '2026-11-05 23:48:38.909524+00', '2026-11-05 23:48:39.815325+00', NULL),
	('9edfdaf0-a4a3-49fd-a7ef-1058eef1fd1c', 'log-dad-log', 'guide', 'The DAD log', 'The file DAD plays automated hours from: what''s in it, what stops it, and how to release it.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The DAD log is the file DAD merges into a day''s playlist so it plays that day''s credits in automated hours. Open it from ", "type": "text"}, {"text": "Today", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with ", "type": "text"}, {"text": "DAD log", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/log/dad-log"}}]}, {"text": ". Only breaks in automated hours are in the file; hosted hours are left to the host.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Before releasing", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The bar at the top shades the day''s automated hours. Change them on ", "type": "text"}, {"text": "Automated hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", reached from Programs.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Anything DAD can''t play is listed first, with a link to fix it: a message with no DAD cut or not yet recorded in DAD, something only a host can do (a live read written for the rundown, or the weather), copy that isn''t approved or is outside its dates, or a break that runs past its window.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A program that airs in automated hours but has no rundown is listed as worth knowing. Its breaks aren''t in the file until it has one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Table", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows what DAD will play and when. ", "type": "text"}, {"text": "File", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows the exact rows.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Releasing", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Traffic releases the day with ", "type": "text"}, {"text": "Release", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It''s refused while anything can''t play.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Download the release and put it in DAD''s import folder. The file is named for the day, such as 100126tWUWF.log.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If a rundown changes afterwards, the page says the release is out of date. Release again; each release is a new version, and the history keeps every one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each item keeps the same spot number in every version.", "type": "text"}]}]}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.dad-log}', NULL, 46, 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', false, false, 4, '2026-11-05 23:48:37.954068+00', '2026-11-05 23:48:39.815325+00', NULL),
	('d4a3c899-566c-419c-bebc-3588c5bddf53', 'bookings-asset-inventory', 'guide', 'Asset inventory', 'The major production assets by pool, cost, funding source, useful life, restrictions and condition.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Under ", "type": "text"}, {"text": "Rates", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Assets", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/rates/assets"}}]}, {"text": " lists the major studio, field, live-production and post-production assets: acquisition cost and date, funding source, useful life, restrictions, maintenance burden and condition. Finance or the Director of Operations keeps it.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "+ New asset", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to add one, or an asset''s name to edit it. Filter by pool or by funding source with the chips.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Equipment funded by the Foundation, members or a restricted grant is not prepaid institutional capacity. Note the restriction on the asset, such as public-service use only.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The pool costs in the rate model stay the budget-line allocation until this inventory, with UWF Budget/Controller''s cost-recovery treatment for each asset, replaces it in a new rate model version. Nothing here changes a rate on its own.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An asset that leaves service is marked out of service, not deleted.", "type": "text"}]}]}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.assets}', NULL, 20, 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', false, false, 2, '2026-11-05 23:48:38.49237+00', '2026-11-05 23:48:39.815325+00', NULL),
	('df0af22d-82f4-4c5b-bcbd-c10ce2b61f4d', 'log-underwriting-hours', 'guide', 'Underwriting hours', 'Which hours are closed to underwriting auto-fill: weekly closed windows and one-time changes.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auto-fill may schedule an underwriting credit in any hour unless it''s closed on this page. Open it from ", "type": "text"}, {"text": "Schedule", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": ", then ", "type": "text"}, {"text": "Underwriting", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Traffic staff can still place a credit by hand in a closed hour, and hosts can still move one; the rule reaches automation only.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Closed every week", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use ", "type": "text"}, {"text": "+ Weekly hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for the routine ones, such as 5:00 AM to 5:00 PM every day. Pick the days, the times, and the date they start.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An end time at or before the start runs past midnight. The early-morning part belongs to the day the hours started.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Programs in these hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": " column shows what''s on the air while credits are closed.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "One-time changes", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use ", "type": "text"}, {"text": "+ One-time change", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for a pledge drive or a special. Choose ", "type": "text"}, {"text": "Closed", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to close hours that are normally open, or ", "type": "text"}, {"text": "Open", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to open hours that are normally closed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A one-time change wins over the weekly hours. One-time changes can''t overlap each other.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Midnight to midnight covers whole days: a pledge week is Monday 12:00 AM until the next Monday 12:00 AM.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Week and month", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The week view draws each day''s closed hours over the programs on the air, with the automated hours shown faintly behind them. Hatched red is closed every week, dashed hatched is closed once, and dashed green is open once.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The month view shows each day''s closed hours. Pick a day to see its week.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Programs week view shades the same hours behind the programs.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Auto-fill never places a credit in a closed hour, never moves one there, and never generates a rundown for a day whose eligible breaks are all closed. Traffic''s dashboard names a line whose upcoming period falls entirely in closed hours.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A credit already placed stays where it is when the hours change.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only the program director can change these hours. Nothing is deleted: removing hours or a change takes it off the schedule.", "type": "text"}]}]}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.underwriting-hours}', NULL, 46, 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', false, false, 2, '2026-11-05 23:48:38.360936+00', '2026-11-05 23:48:39.815325+00', NULL),
	('98b0468f-16ac-44e4-acd9-883a8bbc7eca', 'underwriting-setup', 'guide', 'Setup', 'Inventory pools, industries, and the one-time imports from RadioTraffic.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Setup", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/setup"}}]}, {"text": " holds the lists the rest of the tool depends on. Each card says whether it needs attention.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Inventory pools", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": what an order''s “AM Drive” or “Carpool” means in On Air programs and time windows. A pool with no mapping can''t be scheduled.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Industries", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the categories auto-fill uses to keep competing underwriters out of the same break.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Import agreements", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Import copy", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the one-time moves from RadioTraffic. Only administrators see these.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.setup}', NULL, 60, 'release', 'Contextual screen links preserved in the existing guide', false, false, 3, '2026-11-05 23:48:37.648014+00', '2026-11-05 23:48:39.862284+00', NULL),
	('9b858f88-2a9a-4606-ae21-dce27544baea', 'underwriting-find-contracts', 'guide', 'Find and filter contracts', 'Search contracts and narrow the list by status.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Contracts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": " page lists every underwriting contract, with search and filters in one row above it.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Search by underwriter name or order number.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use the chips to show all contracts, active ones, drafts, or the ones that need attention — a draft, or a contract with an open exception.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "+ New contract", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to start the setup steps for a new order.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.contracts}', NULL, 10, 'release', 'Contextual screen links preserved in the existing guide', false, false, 2, '2026-11-05 23:48:36.124228+00', '2026-11-05 23:48:39.862284+00', NULL);
INSERT INTO public.rc_articles (id, slug, kind, title, summary, body, area, owner_role, tool_id, screen_keys, released_on, sort_order, source, version_note, needs_review, edited_since_release, version, created_at, updated_at, updated_by) VALUES
	('ce2f9d0a-3165-4778-b835-e23160cdf3c7', 'underwriting-affidavits', 'guide', 'Affidavits', 'Generate each month''s affidavits, then sign them in order.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Affidavits", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/affidavits"}}]}, {"text": " are one list per month, with a row for every contract that aired credits that month. A row''s button shows where it stands: ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Sign", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Signed", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with its PDF.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Each month", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open ", "type": "text"}, {"text": "Affidavits", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It opens on last month.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on one row, or ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with a count at the top to do every row still waiting. A row that fails says why, and the rest still generate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Whoever signs selects ", "type": "text"}, {"text": "Sign", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with a count at the top, then ", "type": "text"}, {"text": "Sign and open next", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on each one. Previous and Skip move through the month without signing.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Signing", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Your title on the signature line comes from your profile. Changing it while signing applies to that affidavit only. An administrator sets titles under Admin › Users.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Signing stores the PDF, and it can''t be changed afterwards. A correction is a new affidavit; the list shows the earlier version beside it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only underwriting managers can sign. Everyone else sees “Waiting for signature” and can preview the draft.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use the arrows beside the month to see earlier months. A note at the top names any earlier month that still has affidavits to generate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For an unusual period, use ", "type": "text"}, {"text": "Generate one by hand", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the bottom of the list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An affidavit lists only credits that aired.", "type": "text"}]}]}]}]}', NULL, NULL, '90f557ed-b526-402b-8a58-b86f585ec57d', '{underwriting.affidavits}', NULL, 50, 'release', 'Contextual screen links preserved in the existing guide', false, false, 2, '2026-11-05 23:48:37.648014+00', '2026-11-05 23:48:39.862284+00', NULL),
	('d600ea92-8b1d-4ddd-9515-184acce74f7e', 'editorial-submit-a-pitch', 'guide', 'Submit a pitch', 'Put a story idea in the backlog and follow how it''s decided.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Every story idea starts as a pitch in the backlog. An editor picks pitches from the backlog for a weekly planning meeting, where reviewers score them and the editor records a decision.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Submit one", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Backlog tab, select ", "type": "text"}, {"text": "New pitch", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Give it a title — one line that says what the story is — and fill in the fields below it. Fields marked with an asterisk are required.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose a ", "type": "text"}, {"text": "Primary coverage pillar", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". If you choose one of the station''s pillars, say how the story contributes to sustained coverage of it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Submit pitch", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". You land on the pitch''s own page.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find a pitch in the backlog", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The band at the top of the Backlog says where this week''s meeting stands and what you can do next: start or continue scoring, or, for an editor, build the slate, close scoring or conclude. It is not shown between meetings.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Type in ", "type": "text"}, {"text": "Search pitches", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to find a pitch by its title or any of its answers. ", "type": "text"}, {"text": "Filter", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds the status chips — Open, Stale, Assigned and Archived, each with a count — and the Pillar, Format and Urgency lists.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A pitch marked ", "type": "text"}, {"text": "On slate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is on the current meeting; ", "type": "text"}, {"text": "Stale", "type": "text", "marks": [{"type": "bold"}]}, {"text": " means it has gone 90 days without a review or has been deferred three times. Editors can archive stale pitches in bulk from the Stale view.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit it", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "You can keep editing your pitch with ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " until an editor adds it to a meeting''s slate. While that meeting is scoring, edits are locked; they reopen if the pitch comes back to the backlog.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Follow it", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The pitch page opens with the summary, then the other answers. ", "type": "text"}, {"text": "Where it stands", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", on the right, shows the status, which meeting it is on, how many meetings have reviewed it, the last decision and whether edits are open.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Review history", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists each meeting that discussed the pitch with its adjusted score and decision; open ", "type": "text"}, {"text": "Scores, decision and comments", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for the breakdown, reviewers'' comments and the rationale.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Editors use the ⋮ menu on a pitch to add it to the open slate, archive it with an optional reason, or restore an archived pitch to the backlog.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once a pitch is assigned, the page shows who is reporting it. The pipeline ends there; reporting itself is not tracked in this tool.", "type": "text"}]}]}]}]}', NULL, NULL, 'cb8769f3-27c0-44f4-9b32-30682e734e3a', '{editorial.backlog,editorial.pitch}', NULL, 10, 'release', 'The This week band, search and Filter, and the pitch page''s Where it stands and ⋮ menu', false, false, 4, '2026-11-05 23:48:36.556372+00', '2026-11-05 23:48:42.75501+00', NULL),
	('83e38eb4-0ef2-49c2-ab72-ba6ce74e5d13', 'audience-listening-send-to-sourcework', 'guide', 'Sending an answer to Sourcework', 'Hand one audio answer, or a whole query''s queue, to Sourcework for transcription.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "An answer worth transcribing can be handed to Sourcework directly from its ", "type": "text"}, {"text": "submission page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/audience-listening"}}]}, {"text": " — one answer at a time, or, for a query set to automatic transcription, in a batch.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Send one answer", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On a submission''s page, under an answered question, select ", "type": "text"}, {"text": "Send to transcription", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "This creates a Sourcework project from the answer''s audio and starts transcription. You stay on the submission page — it doesn''t navigate you away.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once it succeeds, the answer''s badge updates and an ", "type": "text"}, {"text": "Open in Sourcework", "type": "text", "marks": [{"type": "bold"}]}, {"text": " link appears, showing the project''s current status. Select it when you''re ready to leave for Sourcework.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Automatic queries", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "If the query''s settings have transcription set to automatic, every submitted answer is queued on its own. A banner above the Submissions list shows how many are queued, with a ", "type": "text"}, {"text": "Send queued answers", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button that sends the whole batch in one click — still a manual click, since there''s no background job runner.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sending needs both Audience Listening and Sourcework access. Without the second, the button fails with a message telling you to ask an administrator for it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only what the participant consented to carries over — never their contact details, and their name or city only if they didn''t ask to stay anonymous.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If a send fails, the button becomes ", "type": "text"}, {"text": "Retry transcription", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and the error is shown right there on the page.", "type": "text"}]}]}]}]}', NULL, NULL, 'afcedc31-3687-4acf-b5b8-4a162971f070', '{audience-listening.query}', NULL, 30, 'editor', 'Contextual screen links preserved in the existing guide', false, false, 2, '2026-11-05 23:48:36.445146+00', '2026-11-05 23:48:39.862284+00', NULL),
	('f8a5cab8-aa99-4e53-83fc-1afe798573aa', 'editorial-configure-form-and-rubric', 'guide', 'Configure the pitch form and rubric', 'Editors choose what writers are asked and what reviewers score.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Settings", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial/settings"}}]}, {"text": " is for editors. It has three parts: ", "type": "text"}, {"text": "Submission form", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Pillars", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and ", "type": "text"}, {"text": "Rubric", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Retired entries stay on the pitches and scores that used them, so nothing changed here rewrites history.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Submission form", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "+ Add field", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to add a question to the pitch form. A field''s type is fixed once it exists; its label, help text, options, and whether it''s required can change later.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Reorder fields with the arrows. Retire a field you no longer need; restore it any time.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Pillars", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Pillars are the station''s coverage priorities. Each has a guiding question, shown to writers on the pitch form. Retire a pillar to take it off the form; a retired pillar can be deleted.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Rubric", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Core criteria are weighted and averaged; the active weights should add up to 100. Modifiers are scored separately and never count toward the core average.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each criterion can carry anchored descriptions — what each score means — which reviewers see when they hover a score.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A weight change applies to future scoring only. The scoring scale and the modifier threshold are set at the bottom of the page.", "type": "text"}]}]}]}]}', NULL, NULL, 'cb8769f3-27c0-44f4-9b32-30682e734e3a', '{editorial.settings}', NULL, 30, 'release', 'One rubric: criteria no longer belong to a profile', false, false, 3, '2026-11-05 23:48:36.556372+00', '2026-11-05 23:48:42.708196+00', NULL),
	('7db08922-d6b8-41c2-9660-ea08d69ec5ac', 'audience-listening-review-submissions', 'guide', 'Review submissions and send answers to transcription', 'Read consent, review each answer, and hand answers to Sourcework.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Every response to a ", "type": "text"}, {"text": "query", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/audience-listening"}}]}, {"text": " is a submission, made up of one answer per question it asked.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find a submission", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the query and select its ", "type": "text"}, {"text": "Submissions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab — the count in the tab label tells you how many there are.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select a participant''s name to open their submission.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review one", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The left column shows the participant''s details, their consent and attribution choices, and a note field only your staff can see.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The right column lists every question in order, each with an outcome — answered, incomplete, skipped, or not asked (a question added after this participant responded).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An answered question has an audio player, its duration and file size, and a link to download the original file.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mark reviewed", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Flag", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and ", "type": "text"}, {"text": "Reject", "type": "text", "marks": [{"type": "bold"}]}, {"text": " apply to the whole submission, at the top of the page; the same actions are also available per answer, further down.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "“Incomplete” means the upload started but never finished — the audio may not exist. The screen says so plainly rather than showing a broken player.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If a question''s wording has changed since this answer was recorded, the answer shows the wording as it was asked, alongside how it reads today.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each answer has its own note field, separate from the submission-level one.", "type": "text"}]}]}]}]}', NULL, NULL, 'afcedc31-3687-4acf-b5b8-4a162971f070', '{audience-listening.query}', NULL, 20, 'release', 'Contextual screen link in existing instructions', false, false, 3, '2026-11-05 23:48:36.445146+00', '2026-11-05 23:48:39.951425+00', NULL),
	('2b4086e5-4953-4a48-a7e5-1422512e2eb6', 'bookings-settlement', 'guide', 'Settling a delivered request', 'Finance records what a delivered request actually cost and what was recharged or invoiced, and posts it under a journal entry number.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Once a ", "type": "text"}, {"text": "request", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " is delivered and production has confirmed the hours and equipment used, Finance settles it. The ", "type": "text"}, {"text": "Settlement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel on the request drafts itself: the amount is the approved estimate''s, with each direct expense replaced by what it actually cost, and the cost to WUWF is the confirmed hours and equipment at the rate card the request was priced on. The hours never change what the partner is charged; they change what the work cost WUWF.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A university unit is recharged to its funding index. An outside partner is invoiced, with the assessment and margin shown on their own lines.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Type the actual cost of any direct expense, or leave it blank to settle it as estimated. Update the draft to recalculate from the hours confirmed now.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Post the entry in the university''s own system, then enter its journal entry number here and post the settlement. Posting settles the request, and a posted settlement is final.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "WUWF contributes the cost the partner''s payment does not cover, never less than zero. The Term report totals settled requests so actual cost can be read against the estimates.", "type": "text"}]}]}', NULL, NULL, '6f1f53ed-1018-4dc7-851c-013ee96986c3', '{bookings.project}', NULL, 23, 'release', 'Contextual screen link in existing instructions', false, false, 2, '2026-11-05 23:48:39.42463+00', '2026-11-05 23:48:39.951425+00', NULL),
	('8f7b79d0-d1af-4182-8585-29db621ed754', 'on-air-workflow-overview', 'guide', 'On Air: producing, hosting and automation', 'How this tool works, with contextual links to its detailed guidance.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "On Air connects the station''s program schedule and clocks with daily rundowns, locally produced content and automation exports. A host begins on ", "type": "text"}, {"text": "Today", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log"}}]}, {"text": "; a producer also maintains reusable scripts and metadata in the ", "type": "text"}, {"text": "Content library", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/library"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "One schedule, different responsibilities", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The program clock defines the available breaks and fixed elements. ", "type": "text"}, {"text": "Programs", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": " determines what airs when; ", "type": "text"}, {"text": "Sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/sources"}}]}, {"text": " shows imported NPR and weather information that should be checked for freshness before use. Producers review a rundown''s timing and required content; hosts execute it and report deviations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Operations defines unattended periods under ", "type": "text"}, {"text": "Automation", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/automated-hours"}}]}, {"text": " and controls which periods can accept underwriting under ", "type": "text"}, {"text": "Underwriting hours", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/underwriting-hours"}}]}, {"text": ". Those settings are related but not interchangeable: an unattended hour is not necessarily open to credits.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Export, import and broadcast are distinct", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Traffic reviews and releases the ", "type": "text"}, {"text": "DAD log", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/dad-log"}}]}, {"text": " for unattended hours after resolving missing or unrecorded cuts, ineligible copy and timing blockers. The export must then be imported into DAD, and actual playout checked through the station''s operational process. A change after release may require a new version.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For equipment or transmission failure, do not improvise a recovery procedure from the scheduling tool. Use ", "type": "text"}, {"text": "Restart broadcast systems after a total power failure", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/procedures/restart-after-a-total-power-failure"}}]}, {"text": " or the applicable Operations and Technology SOP.", "type": "text"}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.today,log.library,log.dad-log}', NULL, 5, 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', false, false, 4, '2026-11-05 23:48:39.657062+00', '2026-11-05 23:48:40.000183+00', NULL),
	('af63e5a9-2f22-46d6-b9d5-39d39a786282', 'audience-listening-workflow-overview', 'guide', 'Audience Listening: from questions to reporting', 'How this tool works, with contextual links to its detailed guidance.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Audience Listening collects people''s experiences and questions to inform reporting. Start in ", "type": "text"}, {"text": "Queries", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/audience-listening"}}]}, {"text": " with a specific editorial uncertainty, and ask open-ended questions that do not assume an answer.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Participation and permission are not interchangeable", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Before publication, review the query''s participant-information settings, consent language and attribution choices. Permission to contact someone is not the same as permission to name them; requests for anonymity must be handled according to the submitted record. Preview the participant experience before opening responses.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Treat responses as reporting leads", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Listen to submissions, consider whether a response merits follow-up, and send relevant audio into Sourcework using the supported handoff. Preserve the original question and consent context when further reporting begins.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An open-response listening query is not a representative poll. Recurring accounts can identify reporting questions, but response counts alone do not establish how common an experience is in the broader population. Corroborate consequential claims before publication.", "type": "text"}]}]}', NULL, NULL, 'afcedc31-3687-4acf-b5b8-4a162971f070', '{audience-listening.queries,audience-listening.query}', NULL, 5, 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', false, false, 4, '2026-11-05 23:48:39.657062+00', '2026-11-05 23:48:40.000183+00', NULL),
	('758d8487-bc47-4c93-b81c-8eb526381d5e', 'roadmap-workflow-overview', 'guide', 'Roadmap: requests and decisions', 'How this tool works, with contextual links to its detailed guidance.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Roadmap board", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/roadmap"}}]}, {"text": " gathers product problems and proposed improvements. A useful request identifies who is affected, what happens today, why it matters, and what a successful change would make possible. Start from ", "type": "text"}, {"text": "New request", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/roadmap/new"}}]}, {"text": " when an existing item does not already capture the need.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "A request is not a delivery commitment", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Curators clarify and group requests, consider priority and feasibility, and move them through the board''s documented statuses. Comments should add evidence, reproduce a problem or describe a distinct use case rather than simply restate support.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "When a change is delivered, connect its release note and updated tool guide to the original request. Users should rely on the current board status and release documentation—not infer a ship date from an idea appearing on the roadmap.", "type": "text"}]}]}', NULL, NULL, '5dc6dd04-1994-4398-bd91-e7e1703f4fd1', '{roadmap.board,roadmap.post}', NULL, 5, 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', false, false, 4, '2026-11-05 23:48:39.657062+00', '2026-11-05 23:48:40.000183+00', NULL),
	('815ae5eb-5e2c-4b7d-9952-68249640e7fd', 'editorial-planning-workflow-overview', 'guide', 'Editorial Planning: pitch to assignment', 'Prepare pitches, score and document decisions.', '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Submit a useful pitch", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A pitch should make a potential story legible to a colleague without requiring a separate conversation. State what is happening; whom it affects; why it matters now; what remains unknown; what evidence or sources might answer the question; and what reporting effort is likely required. Choose the coverage pillar that best describes the underlying public question, not merely the institution involved.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Example:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Rather than \"A university hosts a military program,\" frame the public question: whether a university''s expansion of military-to-civilian training is changing access to civilian employment and for whom. The institutional activity is a lead to investigate, not necessarily the story''s conclusion.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The existing workflow permits a ", "type": "text"}, {"text": "submitted pitch", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial"}}]}, {"text": " to be edited until it enters ", "type": "text"}, {"text": "meeting scoring", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial/meetings"}}]}, {"text": "; use review history to understand whether it was assigned, deferred or archived.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Run a planning meeting", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Editors create the meeting and add eligible pitches to the slate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Reviewers score independently against the published anchored criteria and record substantive concerns. An institutional alignment modifier must not substitute for the story''s civic value, evidence or feasibility.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "After scoring closes, consider the ranked agenda, disagreements and written comments. Scores inform editorial judgment; they do not make the assignment decision themselves.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Record the disposition and assignment clearly. A deferred pitch should have an understandable next step where possible; an assigned pitch should identify the responsible reporter.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Conclude the meeting only after decisions are recorded. The concluded meeting is a permanent historical record.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "After assignment", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The pipeline ends at the assignment. The pitch page records who is reporting the story and keeps every round''s scores, comments and decision as the newsroom''s record; the reporting itself is not tracked here.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Administration", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Configuration guides should explain the difference between weighted core criteria and separate modifiers, how archived rubric elements preserve historical scores, and when changing criteria is justified. Any numerical example must match the live rubric.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Direct portal screen links", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open these routes in the portal. Individual records must be opened from their list; no record ID is assumed.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Pitch backlog", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial"}}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Meetings", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial/meetings"}}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Settings", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial/settings"}}]}]}]}]}]}', NULL, NULL, 'cb8769f3-27c0-44f4-9b32-30682e734e3a', '{editorial.backlog,editorial.meeting,editorial.pitch}', NULL, 5, 'release', 'Station name removed so the guide reads for any station', false, false, 7, '2026-11-05 23:48:39.657062+00', '2026-11-05 23:48:43.198941+00', NULL),
	('d359da41-2d8d-4ac8-9280-b9d9a0e8d4da', 'log-one-time-clock-change', 'guide', 'Changing a program''s clock for a few days', 'Give a program a different clock on certain dates, such as FPREN storm coverage, and switch rundowns that were already built.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Use a one-time change when a program needs a different clock for a set of dates, for example FPREN Phase I storm coverage. The normal weekly schedule stays as it is, and the one-time change replaces it on the dates you choose.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add the change", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the program from ", "type": "text"}, {"text": "Programs", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": ", then select ", "type": "text"}, {"text": "+ Add a time", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Set the entry type to ", "type": "text"}, {"text": "One-time change", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose the clock, and give the start and end dates, the air time and the length. A one-time change covers every day between its dates.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Save. On those dates, Today, the week view and any new rundown use this clock instead of the normal one.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Switch rundowns that already exist", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Traffic can build rundowns weeks ahead, so some of those dates may already have a rundown on the old clock. When that is so, the program page shows a notice that lists the dates, with a ", "type": "text"}, {"text": "Switch", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Switching keeps each old rundown as a record and builds a new one on the clock now in force. The old rundown is marked as replaced and can''t be started, edited or submitted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only a rundown that hasn''t started and has nothing recorded on it is switched. One that is on air, or has recorded outcomes, is left as it is.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Rundowns built from an imported program log are switched the same way as the others. Where the rundown came from doesn''t matter, only whether it has started or has anything recorded on it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What happens to underwriting", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Any underwriting credit already placed on a replaced rundown is recorded as missed, with the reason Special coverage. Each one appears in Traffic''s exception list, where staff decide on a makegood or a waiver. Nothing is placed again automatically, and nothing is counted as aired. Credits that came from an imported log have no Traffic placement behind them, so they can''t raise an exception. The notice after switching tells you how many there were. They stay on the old rundown, and you add them to the new one if they still apply.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "DAD", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "If a date already has a released DAD log, the notice after switching names the date. The DAD log screen also marks that release as out of date. Traffic needs to release a new version, because DAD plays what was released.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Going back", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "To end a change early, shorten its end date or remove the entry, then select ", "type": "text"}, {"text": "Switch", "type": "text", "marks": [{"type": "bold"}]}, {"text": " again on the program page. Exceptions that were already raised stay open for Traffic to resolve.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On Today, a program with a one-time change shows one row, labelled One-time change, not two.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Holiday is no longer an entry type. A holiday that needs a different clock is a one-time change; one that is only automated is set under Automation.", "type": "text"}]}]}]}]}', NULL, NULL, 'ff2e6b11-9c01-41fc-9d20-d5827dfdda89', '{log.program,log.program.schedule}', NULL, 60, 'release', 'Imported rundowns can be switched; notices for unplaced credits and released DAD logs', false, false, 2, '2026-11-05 23:48:40.30012+00', '2026-11-05 23:48:40.336319+00', NULL),
	('d48232a1-bf86-4f3c-9e03-cf88578c8009', 'sourcework-starting-a-project', 'guide', 'Starting a project and adding sources', 'Name a project, then add recordings and PDFs now or later.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A project is the workspace for one story. It starts with a name; sources, which are recordings and PDFs, are added to it now or later.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Create a project", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Projects tab of the ", "type": "text"}, {"text": "Sourcework home page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework"}}]}, {"text": ", select ", "type": "text"}, {"text": "+ New project", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Type a title and, if you like, notes: what the project is about and who set it up.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add sources now if you have them. Drag recordings or PDFs onto the box, or select ", "type": "text"}, {"text": "Choose files", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Several at once is fine; each becomes its own source, titled from its file name. Rename any title before you upload.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Create project", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or ", "type": "text"}, {"text": "Create project and upload", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the number of files.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "While files upload", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Files upload three at a time. One bar shows overall progress, with a line for each file in progress. A file that fails stays at the top with the reason and a ", "type": "text"}, {"text": "Retry", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and the rest carry on. An upload is not resumable, so a retry starts that file over.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Stop", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lets the files already uploading finish and leaves the rest waiting; ", "type": "text"}, {"text": "Resume", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts them again. Keep the page open until it finishes. When every file is uploaded you land on the project. If some failed, the project is still created, and you can open it and add the rest later.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "After the upload", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Processing continues in the background. The project''s source list shows each source''s status and a progress bar, and the page updates on its own when it is done.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Audio and video get a transcript. A PDF''s text is extracted automatically: a plain read of the file first, falling back to OCR only when that is not enough.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If processing fails, the source says why under its title. Open it for ", "type": "text"}, {"text": "Retry", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; the file itself is already safely uploaded.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The Sourcework home", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Pick up where you left off", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", at the top, shows up to three projects: ones with a source that failed or findings waiting for review first, then the most recently active.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Projects", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab lists the most recently active projects first, 25 to a page. The filters show how many projects each holds: ", "type": "text"}, {"text": "All", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Started by me", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Needs attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (a source failed, or findings are waiting for review) and ", "type": "text"}, {"text": "No sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Each row shows a bar of the five steps done (Sources, Analyze, Review, Synthesis, Piece) with the step it is on, its sources, its excerpts, who started it, its last activity and its status. Select anywhere on a row to open the project.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab holds every source and every excerpt, whichever project they are in. See ", "type": "text"}, {"text": "Browse the Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-browse-source-library"}}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Deleting a project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Only the person who started a project can delete it: open the project and choose ", "type": "text"}, {"text": "Delete project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from the ⋮ menu beside its title. It asks once more and names what will happen: sources that only this project uses are removed with their transcripts and excerpts, and sources that another project also uses stay in the Notebook. A long list shows five names and a count.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A project does not need a source. One without any shows ", "type": "text"}, {"text": "No sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the list, and opens with an ", "type": "text"}, {"text": "Add the first source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Anything outside the accepted audio, video and PDF types is refused before the upload starts, with a message naming what is accepted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The file goes straight from your browser to storage. A long recording can take a few minutes to upload.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once a source is uploaded, it can be used in more than one project with no re-upload. See ", "type": "text"}, {"text": "Add another source to a project", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-reference-another-source"}}]}, {"text": ".", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.projects}', NULL, 5, 'release', 'Projects and Notebook tabs, the Pick up strip, progress in the list, Delete project in the ⋮ menu', false, false, 5, '2026-11-05 23:48:36.404985+00', '2026-11-05 23:48:42.540935+00', NULL),
	('9ca1ed5a-cb45-4867-a41b-723d23df58f8', 'sourcework-transcript-and-excerpts', 'guide', 'Working with the transcript and creating excerpts', 'Find your way in a transcript, name speakers, and save a stretch of it as an excerpt.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A recording opens as its own screen: the player, the transcript and, beside it, a panel of this source''s excerpts. Excerpts are short clips saved for reuse. On a phone the same screen is three tabs, ", "type": "text"}, {"text": "Transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Speakers", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", with the player docked at the bottom.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find your way", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Find in this transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " looks for a word or phrase from two characters on. Matching words are highlighted. Select the arrows, or press Enter, to step through the matches.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each line begins with the time it starts. A long answer is cut into lines of about half a minute, at the end of a sentence, so there is always a time to point someone to — “what she said at 14:20.” Transcripts made earlier have been cut the same way. Select a word to play from it; on a word that is part of an excerpt, that also opens the excerpt. Selecting a stretch of text, to make an excerpt, still works as before.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The marks under the progress bar show where your excerpts are; select one to open it. With many excerpts the marks merge into a shaded strip, and darker means more excerpts there. Select a stretch of the strip to zoom the progress bar in until the excerpts separate into their own marks, and select ", "type": "text"}, {"text": "Show the whole recording", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to zoom back out.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The player steps back and forward five seconds, changes speed, and follows the transcript as it plays; ", "type": "text"}, {"text": "Jump to playhead", "type": "text", "marks": [{"type": "bold"}]}, {"text": " scrolls back to the line being played. Space plays and pauses, and the ", "type": "text"}, {"text": "?", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button lists the other keyboard shortcuts.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Speakers", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button names the speakers, with the first few names after it. It opens a list ordered by who spoke most. Type a name to rename a speaker, select ", "type": "text"}, {"text": "Hear an example", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or tick ", "type": "text"}, {"text": "Interviewer", "type": "text", "marks": [{"type": "bold"}]}, {"text": " beside the person asking the questions, so Analyze leaves their words out. ", "type": "text"}, {"text": "Add", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the bottom adds a speaker the transcript missed. From seven speakers a find box and an ", "type": "text"}, {"text": "Unnamed only", "type": "text", "marks": [{"type": "bold"}]}, {"text": " switch appear.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If the transcript split one person into two voices, select ", "type": "text"}, {"text": "Merge…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the extra speaker and choose who it really was. All of its lines move to that speaker.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a line", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select the ⋮ at the end of any line for ", "type": "text"}, {"text": "Edit text", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Make an excerpt from this line", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Change speaker…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Merge with the next line", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Double-clicking the text, or pressing E on the current line, also starts an edit, and while editing you can split the line at the cursor. Choosing ", "type": "text"}, {"text": "＋ New speaker…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when changing a line''s speaker names someone new. ", "type": "text"}, {"text": "Copy transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Download .txt", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", above the transcript, take the whole text with you, with the time at the start of each line.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a source''s details", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select the ⋮ beside the source''s title and choose ", "type": "text"}, {"text": "Edit details", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A card opens with the title and, for a recording, the date it was recorded. Select ", "type": "text"}, {"text": "Save", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to keep the change; the source''s search entries update with it. A PDF has a title only. The same menu has ", "type": "text"}, {"text": "Rebuild search index", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", for a source transcribed before search existed or after a round of corrections, and the two ways out: ", "type": "text"}, {"text": "Remove from this project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Delete source…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", each saying what it does before you confirm.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Create an excerpt", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Drag to select the stretch of text you want. On a phone, touch and hold a word, then drag.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "New excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": " bar opens at the bottom of the transcript with a title already filled in, and the time range beside it. The title starts as the first words you selected and, a moment later, is replaced by a short description of what the speaker says, if you haven''t started typing. When you save, the excerpt is named in full: the project, then who is speaking, then your title, such as Hurricane Isaias_Chip Simmons_Second fatality from generator fumes. That is also the name of the file you download.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Change the title if you like, then press Enter or select ", "type": "text"}, {"text": "Save excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". ", "type": "text"}, {"text": "Preview", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays the exact range; Esc cancels.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Working with excerpts", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The panel lists this source''s excerpts. ", "type": "text"}, {"text": "In order", "type": "text", "marks": [{"type": "bold"}]}, {"text": " follows the recording and ", "type": "text"}, {"text": "Newest", "type": "text", "marks": [{"type": "bold"}]}, {"text": " puts the latest first. From nine excerpts a filter box appears, and twenty show at a time with ", "type": "text"}, {"text": "Show more", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The round ", "type": "text"}, {"text": "play button", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a card plays that excerpt. While it plays the button turns into a pause button, so you can stop it from the card without going to the player. Playing another excerpt switches to that one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows the clip''s words. Tap a word to move the start or end there, or nudge them with the −250, −50, +50 and +250 buttons. ", "type": "text"}, {"text": "Play as cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays the result, and ", "type": "text"}, {"text": "Done trimming", "type": "text", "marks": [{"type": "bold"}]}, {"text": " closes it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Export WAV", "type": "text", "marks": [{"type": "bold"}]}, {"text": " renders the clip to its own audio file; ", "type": "text"}, {"text": "Download", "type": "text", "marks": [{"type": "bold"}]}, {"text": " appears when it is ready, and the button then reads ", "type": "text"}, {"text": "Re-export", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". ", "type": "text"}, {"text": "Show in transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " scrolls to the clip''s words.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Level", "type": "text", "marks": [{"type": "bold"}]}, {"text": " line on a card shows the volume change applied to that excerpt, such as +4.2 dB. Every excerpt is measured when you create or trim it, then played and exported at a fixed level of -18 LUFS, the level the team preps actualities at in Audition, followed by a hard limiter that holds peaks at -6 dBFS. One actuality no longer comes in much hotter or quieter than the last. The level is one volume setting for the whole excerpt, so a speaker who drops to a whisper stays that far below their own normal voice; only the peaks are limited. Select ", "type": "text"}, {"text": "Original level", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to play and export an excerpt as recorded, for example when the quiet is the point, and ", "type": "text"}, {"text": "Even out", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to go back. A card that says ", "type": "text"}, {"text": "measuring…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is still being measured and updates by itself in a few seconds. If it says the excerpt couldn''t be measured, it plays and exports as recorded.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Export excerpts (zip)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", in the Excerpts section of the project''s Notebook, exports every excerpt in the project at once.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select a card''s title to rename it. ", "type": "text"}, {"text": "Delete", "type": "text", "marks": [{"type": "bold"}]}, {"text": " asks you to confirm.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "When the source is in a project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Opened from a project, the panel has a switch between ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the findings and clips Analyze proposed for this source, underlined in the transcript where they are. See ", "type": "text"}, {"text": "Analyzing a source", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-research"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A PDF source works the same way, but you select a stretch of the extracted text instead of a time range. Its screen has ", "type": "text"}, {"text": "Document", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Text", "type": "text", "marks": [{"type": "bold"}]}, {"text": " views and a search box for the document.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trimming a clip after it has been exported makes that export stale. Re-export before you rely on the download.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Line menus and the speaker list work on a tablet or phone too: nothing waits on hovering. Tapping an excerpt''s words on a phone opens it in a sheet; see ", "type": "text"}, {"text": "Play, trim and manage an excerpt on a phone", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-excerpt-sheet-on-a-phone"}}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Level is never applied to the recording itself, only to playback and to exports. Very quiet field tape can need a boost of 35 to 45 dB. Past 20 dB the card notes that the boost raises the background noise along with the voice. If a clip is stereo with the voice in one channel only, the voice is played and exported on both sides. Re-export after changing an excerpt''s level, since an earlier export keeps the level it was made at.", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.source}', NULL, 15, 'release', 'Transcript lines are about half a minute long, each with its time, and a word plays from itself', false, false, 12, '2026-11-05 23:48:36.404985+00', '2026-11-05 23:48:42.831951+00', NULL),
	('4a3381bb-1762-4cb1-a518-02508148687c', 'sourcework-piece-formats', 'guide', 'Maintaining piece formats', 'For editors: the length, actualities, description and style a piece format asks for. Edit, try a draft on a project, publish and roll back.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A piece format is the shape and wording an outline, and writing the outline out, follow: its length, how many actualities it usually uses, a free-text description and style, and whether an anchor leads in. These are guardrails: the model decides the beats and chooses the actualities freely from the material, so every story can take its own shape. Editors maintain formats; you need the Editor role on Sourcework, which an administrator grants on the user''s access screen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a format", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", at the right of the Sourcework tabs, then ", "type": "text"}, {"text": "Piece formats", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Pick a format on the left (on a phone, from the list at the top). Your changes save themselves as a draft only you can see, and ", "type": "text"}, {"text": "Rename", "type": "text", "marks": [{"type": "bold"}]}, {"text": " changes its name everywhere.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Length", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Plus or minus", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the length the piece should run and the range that counts as on target, such as 0:53 within 0:08, which is 0:45 to 1:01.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Usual actualities", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the fewest and most clips the piece usually uses. It is a guide, not a quota: an outline may use fewer, and only going over the most is flagged in a trial.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Description and style", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": what the piece does and how it sounds, such as who reads it and what a listener should come away with. Write placeholders the reporter fills in, such as [REPORTER NAME], in square brackets. Don''t lay out its blocks or their order: the model decides how many beats the story needs and where the actualities go. Tick ", "type": "text"}, {"text": "An anchor may read a lead-in first", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for formats where the anchor can introduce a reporter''s recorded piece. It is always optional, since a piece the anchor reads itself has none, and it isn''t counted in the length.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The model writes beats, and narration when an outline is written out; actualities are always the project''s own excerpts. A format can''t change that, and it can''t make the model type out a quote.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Try a draft", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Try this draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " outlines a piece from one project''s accepted findings and excerpts with your draft and with the live version, and shows the two side by side with how many beats and actualities each used and how much clip time. Add a direction if you want to test one. Nothing is added to the project, and results are kept for 14 days under ", "type": "text"}, {"text": "Recent trials", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", visible only to you.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Publish and roll back", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Publish", "type": "text", "marks": [{"type": "bold"}]}, {"text": " asks for a one-line note about what changed, then makes the draft the live version. Reporters'' next outlines follow it; pieces already outlined keep the version they followed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists every version with its note and how many pieces it made. ", "type": "text"}, {"text": "Edit from this version", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts a draft from it, and ", "type": "text"}, {"text": "Make live again", "type": "text", "marks": [{"type": "bold"}]}, {"text": " moves an earlier version back into use. Nothing is deleted. ", "type": "text"}, {"text": "Discard draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " goes back to the live version.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "+ New format", "type": "text", "marks": [{"type": "bold"}]}, {"text": " adds a format. It isn''t offered to reporters until you publish it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The formats to start with", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Five formats come built in, each a description and a set of guardrails: Reader / Voicer (about 0:30 to 0:45, no actualities), Cut and Copy (0:45, one actuality), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). Anything else, such as a two-way or an interview, is a format you can add. Change the built-in ones like any other format.", "type": "text"}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.formats}', NULL, 21, 'release', 'Reached from the Setup tab', false, false, 5, '2026-11-05 23:48:41.125004+00', '2026-11-05 23:48:42.540935+00', NULL),
	('b1df2fcc-78bb-4240-b5bc-5613359dd8ae', 'sourcework-project-overview', 'guide', 'A project at a glance', 'See where a project stands, do the next step yourself or with AI, and find any source.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A project opens on where it stands and what to do next. You can do every step yourself, ask AI to do any step, or hand it the rest.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The steps and the next step", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The row of steps runs Sources, Analyze, Review, Synthesis, Piece. A finished step is a link back to its tab. Under it, one panel names the next step and gives you one button for it: ", "type": "text"}, {"text": "Add the first source", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when sources are ready, ", "type": "text"}, {"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the count waiting, ", "type": "text"}, {"text": "Open Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when nothing has been accepted yet, then ", "type": "text"}, {"text": "Open Synthesis", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Start a piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The steps only report and suggest; you can use any tab at any time. Once the project has a piece, the strip and the panel are gone and the Pieces tab carries on. On a phone the row of steps is left out, since the tabs and the Review badge say the same, and the panel is one line with its button and the hand-over link side by side.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The title and background", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The project''s title and background sit at the top; the background is shown on every excerpt and search result from the project, so say what it was about. ", "type": "text"}, {"text": "Add background", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Edit details", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under the title opens them for editing, as does ", "type": "text"}, {"text": "Edit title and background", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the ⋮ menu beside the title, which is the way in on a phone. The same menu holds ", "type": "text"}, {"text": "Delete project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", with a list of what goes and what stays.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tabs", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds what you browse, in three sections. ", "type": "text"}, {"text": "Sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the project''s sources, ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the findings you have accepted or rejected (filtered Accepted, Rejected or Both, each linking to its source), and ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the excerpts made from them, with ", "type": "text"}, {"text": "Export excerpts (zip)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is where you decide on the findings and clips Analyze suggested, from every source at once. The number beside it is how many are waiting.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Synthesis", "type": "text", "marks": [{"type": "bold"}]}, {"text": " appears once a finding has been accepted. ", "type": "text"}, {"text": "Pieces", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", which holds the research questions and the pages the model consulted, complete the row.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Run the remaining steps with AI", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The link under the button opens a dialog that runs the steps still to do, one after another, and hands control back where you choose: after Analyze, after Synthesis, after Outline, or after a first draft. It starts on Analyze, so the Review tab stays yours. Going past Analyze accepts every suggested finding and clip without your review, and the dialog says so before you start; they can be put back for review afterwards. Keep the page open while it runs. ", "type": "text"}, {"text": "Stop after this step", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ends the run, and what finished is kept.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find a source", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each source has a bar showing how far it has come: processed, analyzed, reviewed. The word under it says which step it is on.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Filter sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " searches titles. ", "type": "text"}, {"text": "Show", "type": "text", "marks": [{"type": "bold"}]}, {"text": " narrows the list to sources ", "type": "text"}, {"text": "Not analyzed", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or that ", "type": "text"}, {"text": "Need attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and ", "type": "text"}, {"text": "Sort", "type": "text", "marks": [{"type": "bold"}]}, {"text": " puts the newest first or sorts by title. The list shows 25 at a time.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select a row to open the source. A source that failed to process says why under its title. The ⋮ menu at the end of the row opens the source or removes it from this project.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and, except when it is the panel''s own button, ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sit with the filters above the source list.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hints that go away", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Short how-to notes on some screens, such as how to select words into an excerpt, show a ", "type": "text"}, {"text": "Got it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button. Select it and that note stays hidden in this browser.", "type": "text"}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.project}', NULL, 12, 'release', 'The strip is left out on a phone and once a piece exists; the tabs and the header as they are now', false, false, 5, '2026-11-05 23:48:42.178814+00', '2026-11-05 23:48:42.540935+00', NULL),
	('c18c50ff-c90a-4cea-9b67-70632e202912', 'sourcework-piece-trim-and-pauses', 'guide', 'Trim a clip and shorten its pauses', 'Set where a clip starts and ends in a piece, and cut its long pauses down.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Trim sets where a clip starts and ends in a piece. Pauses shortens the long gaps inside it. Both change only this piece unless you choose otherwise.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Trim a clip", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On an excerpt block, open the ", "type": "text"}, {"text": "⋮", "type": "text", "marks": [{"type": "bold"}]}, {"text": " menu and choose ", "type": "text"}, {"text": "Trim…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The clip''s words appear with a few words of transcript either side. Tap a word to move the start or end to it, whichever is nearer, or use the −250, −50, +50 and +250 buttons. ", "type": "text"}, {"text": "Play as cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays the clip as it is now.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The excerpt''s own trim buttons on the transcript screen work the same way: choose ", "type": "text"}, {"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on an excerpt card and tap a word to move its start or end.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "By default the trim applies to this piece only. Choose ", "type": "text"}, {"text": "Update the excerpt everywhere", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change the excerpt itself; the panel says how many other pieces use it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Shorten long pauses", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Pick a setting. ", "type": "text"}, {"text": "Long pauses only", "type": "text", "marks": [{"type": "bold"}]}, {"text": " looks for gaps over a second, ", "type": "text"}, {"text": "Standard", "type": "text", "marks": [{"type": "bold"}]}, {"text": " over 0.7 seconds and ", "type": "text"}, {"text": "Tight", "type": "text", "marks": [{"type": "bold"}]}, {"text": " over half a second. Each pause is cut down rather than removed, leaving a short beat so the speaker doesn''t sound clipped.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose ", "type": "text"}, {"text": "Find pauses", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Each one is marked between the words with how much it would save, for example ⏸ 1.4s.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose ", "type": "text"}, {"text": "Play as cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to hear the clip with those pauses skipped.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose ", "type": "text"}, {"text": "Remove these pauses", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to apply them, or ", "type": "text"}, {"text": "Cancel", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to leave the clip as it is.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Shortened pauses show as −1.4s in the words, the block says how many it has, and the piece''s length updates. ", "type": "text"}, {"text": "Put the pauses back", "type": "text", "marks": [{"type": "bold"}]}, {"text": " restores the clip. Pauses are found from the transcript''s word timings, so a line with no timings has nothing to find. Pauses are kept per piece; the same excerpt in another piece is not changed.", "type": "text"}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.piece}', NULL, 19, 'release', 'First version', false, false, 1, '2026-11-05 23:48:41.705394+00', '2026-11-05 23:48:41.705394+00', NULL),
	('6c053a16-e34b-4f5b-85a7-ac45f8765fb7', 'sourcework-excerpt-sheet-on-a-phone', 'guide', 'Play, trim and manage an excerpt on a phone', 'Tap an excerpt in the transcript to play it, trim it, change its level, export it or delete it.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "On a phone, tapping words that are part of a saved excerpt opens a sheet above the player. The transcript stays visible behind it. On a larger screen the same tap selects the excerpt''s card beside the transcript.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What the sheet shows first", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Play excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays just that excerpt, at the level it will be exported. It becomes ", "type": "text"}, {"text": "Pause", "type": "text", "marks": [{"type": "bold"}]}, {"text": " while it plays.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens everything you can do to the excerpt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Show in Excerpts tab", "type": "text", "marks": [{"type": "bold"}]}, {"text": " takes you to the excerpt''s card in the list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ✕ button closes the sheet.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit an excerpt", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Edit shows the same card as the Excerpts tab. Tap the title to rename it. Choose ", "type": "text"}, {"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to show the excerpt''s words and move its start or end by tapping a word. Choose ", "type": "text"}, {"text": "Original level", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Even out", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change its level. ", "type": "text"}, {"text": "Export WAV", "type": "text", "marks": [{"type": "bold"}]}, {"text": " makes the file, and ", "type": "text"}, {"text": "Download", "type": "text", "marks": [{"type": "bold"}]}, {"text": " appears once it exists. Delete asks you to confirm. Play stays at the bottom of the sheet so you can hear each change; choose ", "type": "text"}, {"text": "Done", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to go back.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "When excerpts overlap", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "If the words you tapped are in more than one excerpt, the sheet says so and lets you pick which one to work on. The shortest is shown first.", "type": "text"}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.source}', NULL, 26, 'release', 'First version', false, false, 1, '2026-11-05 23:48:41.743596+00', '2026-11-05 23:48:41.743596+00', NULL),
	('46cde0d0-4229-482b-88a7-3727773bfee1', 'sourcework-synthesis', 'guide', 'Synthesis', 'Read what a project''s accepted findings establish for each research question, hear the evidence, and decide what to do with the patterns that emerge.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Synthesis reads every finding you have accepted in a project and says what they establish about each of your research questions. It is a reading aid: nothing on this tab is evidence, and every statement opens onto the findings behind it. The tab appears once the project has an accepted finding, and its badge counts the findings accepted since the version it shows was saved.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The top of the tab", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The header says which version you are reading, when it was written and how many findings and sources it reads. ", "type": "text"}, {"text": "Synthesize", "type": "text", "marks": [{"type": "bold"}]}, {"text": " writes the first version; afterwards the button reads ", "type": "text"}, {"text": "Update synthesis", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when findings have been accepted since the version shown, or ", "type": "text"}, {"text": "Synthesize again", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The version menu lists every earlier one; reading an old version is read-only. When a version is not the first, a line under the header says what changed since the previous run: new statements, removed ones, and statements whose certainty moved.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Under it, a summary shows the whole answer at once: how many statements are established, contested and uncertain, and how many tensions, open points and patterns there are. A count in red means statements that no longer have an accepted finding behind them. The chips under the summary show only statements of one certainty.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Reading a statement", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each statement carries a certainty. Five dots show how many different sources it rests on, and ", "type": "text"}, {"text": "One source''s account", "type": "text", "marks": [{"type": "bold"}]}, {"text": " marks a statement that rests on a single source.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Evidence", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a statement to open the findings behind it beside the synthesis, or in a sheet on a phone. Play at a time plays that finding in place, and ", "type": "text"}, {"text": "Open in source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " goes to the passage in the full recording or page.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Sections", "type": "text", "marks": [{"type": "bold"}]}, {"text": " list moves between questions, patterns, conflicts and the moments worth hearing.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Patterns, and what is still open", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Patterns across sources are things several people described separately that no question asked about. A pattern marked ", "type": "text"}, {"text": "Passages only", "type": "text", "marks": [{"type": "bold"}]}, {"text": " rests on moments the model found in the recordings, not on an accepted finding, so treat it as less firm. A pattern marked ", "type": "text"}, {"text": "New", "type": "text", "marks": [{"type": "bold"}]}, {"text": " was not in the previous run.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Track as a research question", "type": "text", "marks": [{"type": "bold"}]}, {"text": " adds a question on the Setup tab, so the next Analyze listens for it. The pattern then reads ", "type": "text"}, {"text": "Tracking", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and cannot be added twice.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dismiss", "type": "text", "marks": [{"type": "bold"}]}, {"text": " hides a pattern. Dismissed patterns are listed under the patterns, with ", "type": "text"}, {"text": "Restore", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and a new run does not offer them again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each open point has the same ", "type": "text"}, {"text": "Track as a question", "type": "text", "marks": [{"type": "bold"}]}, {"text": " action.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Choices you make here are saved as a new version marked as edited by a person, and a later run keeps them as they are. Because that is a version too, the badge and the Update synthesis label count findings accepted after it, not after the last model run.", "type": "text"}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.synthesis}', NULL, 20, 'release', 'The badge counts from the version shown, which a tracked or dismissed pattern also saves', false, false, 5, '2026-11-05 23:48:41.899362+00', '2026-11-05 23:48:42.616845+00', NULL),
	('3c10491a-91f2-4a50-87f7-0312b471b133', 'sourcework-workflow-overview', 'guide', 'Sourcework: from recordings to reporting', 'How the tool fits together: projects, sources, excerpts and pieces, and the optional analysis steps.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sourcework takes recordings and documents from upload to a script. For an ordinary assignment you transcribe audio, pick your own actualities and write the piece by hand. The analysis steps, Analyze, Synthesis and Outline, are optional, and each one waits for your decision.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Start with the task you have", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For a complete first assignment, follow ", "type": "text"}, {"text": "From interview recording to radio script", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-interview-to-script"}}]}, {"text": ". It goes from uploading a recording through checking the transcript, saving excerpts and writing a piece, with no research questions and no AI.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To work on one step, see ", "type": "text"}, {"text": "Starting a project and adding sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-starting-a-project"}}]}, {"text": ", ", "type": "text"}, {"text": "Working with the transcript and creating excerpts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-transcript-and-excerpts"}}]}, {"text": " or ", "type": "text"}, {"text": "Building a piece from narration and excerpts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-pieces"}}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What each thing is", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is an original recording or PDF. A ", "type": "text"}, {"text": "transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is derived text, and an ", "type": "text"}, {"text": "excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a stretch of a source saved for reuse: a time range of a recording, or a passage of a PDF. A ", "type": "text"}, {"text": "project", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the work for one story and refers to sources; the same source can be in more than one project without a second upload. A ", "type": "text"}, {"text": "piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a script built from narration and excerpts.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find and reuse what you already have", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework?tab=notebook"}}]}, {"text": " on the Sourcework home lists every source and every excerpt, whichever project they are in, and its search box finds spoken words, passages and excerpts across all of them. See ", "type": "text"}, {"text": "Browse the Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-browse-source-library"}}]}, {"text": " and ", "type": "text"}, {"text": "Searching across projects and sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-search"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The optional steps, in order", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A project''s own Notebook tab shows where it stands and names the next step. ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": " reads a source and proposes findings and a few clips, which you decide on from the project''s ", "type": "text"}, {"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab. ", "type": "text"}, {"text": "Synthesis", "type": "text", "marks": [{"type": "bold"}]}, {"text": " reads the accepted findings and says what they establish for each research question. ", "type": "text"}, {"text": "Outline with AI", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plans a piece as beats, and ", "type": "text"}, {"text": "Write from outline", "type": "text", "marks": [{"type": "bold"}]}, {"text": " turns the beats into narration. See ", "type": "text"}, {"text": "Analyzing a source", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-research"}}]}, {"text": ", ", "type": "text"}, {"text": "Synthesis", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-synthesis"}}]}, {"text": ", ", "type": "text"}, {"text": "Outline a piece", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-outline"}}]}, {"text": " and ", "type": "text"}, {"text": "A project at a glance", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-project-overview"}}]}, {"text": ". Each of these steps sends the project''s material to an outside service; building by hand sends nothing.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Check the underlying material", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Before anything airs, verify quotations, speaker identities, names, numbers and the context of each excerpt against the original recording. Neither the transcript nor a finding replaces editorial judgment. Apply the station''s editorial and confidentiality requirements when handling sources.", "type": "text"}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.projects,sourcework.project,sourcework.sources}', NULL, 1, 'release', 'Station name removed so the guide reads for any station', false, false, 6, '2026-11-05 23:48:39.657062+00', '2026-11-05 23:48:43.198941+00', NULL),
	('975b9e41-b70b-43c3-a05c-77541834297a', 'sourcework-research', 'guide', 'Analyzing a source', 'Analyze a source for the findings that add to what the project knows and a few clips worth hearing, then decide on them on the Review tab or beside the transcript.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Analyze reads one source and tells you what in it matters: the few findings that add to what the project already knows, and a few passages that might work as audio. Everything it suggests waits for your decision, and nothing is quoted or used until you accept it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Analyze a source", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the project''s ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, choose ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the next-step panel''s button when sources are ready, or the one beside ", "type": "text"}, {"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " above the source list. Each source is read on its own, up to three at a time, and a panel under the tabs shows progress. You can leave the page while it runs, as long as the browser tab stays open. A source that is still transcribing can be analyzed once it finishes, and ", "type": "text"}, {"text": "Not analyzed", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under Show lists the ones still to do.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "From a source, choose ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Analyze again", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under the Data points panel.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A research question is not required. With one, the model looks for what bears on it; without one, it looks for what a reporter would need to know, check or cite. Questions on the Setup tab sharpen the result, and fewer, more specific questions work better than a list of topics.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What you get", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Findings", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": a short paraphrase with the passages it rests on, who said it, and one line on why it matters. The model is shown what the project has already accepted, so it adds to, sharpens or contradicts it instead of repeating it. Often it will find little in a source that repeats the others, and that is the intended result.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Clips to review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": a few passages that might work on the air. Play one, trim it, then accept it into an ordinary excerpt or reject it. Often there are none. See ", "type": "text"}, {"text": "Clips to review", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-suggested-quotes"}}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Pages consulted", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the model can search the web when it needs context to read a source, such as an unfamiliar place, term or claim. The pages it relied on are listed on the Setup tab and under ", "type": "text"}, {"text": "Pages the model looked up", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the Review tab, and a search never uses an interviewee''s name. They inform the model''s reading and never count as evidence.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Set up the project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open a project and select ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", at the right of the tabs. Where the project stands is the row of steps on the Notebook tab, above the sources, not repeated here.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add the questions you are trying to answer. The ⋮ beside a question moves it up or down, or archives it. Archived questions keep their findings and can be restored.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dismiss a page that is wrong or irrelevant and the model stops being shown it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Say who the interviewer is", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On a source, open the speakers menu and tick ", "type": "text"}, {"text": "Interviewer", "type": "text", "marks": [{"type": "bold"}]}, {"text": " beside the person asking the questions. What an interviewer says is not treated as a finding or a clip.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Decide on the project''s Review tab", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", the tab with the count of findings and clips waiting, lists everything Analyze left waiting from every source, grouped by source. Play a finding''s passage or a clip in place, or ", "type": "text"}, {"text": "Open in source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to read it beside the transcript. On a finding, ", "type": "text"}, {"text": "Accept", "type": "text", "marks": [{"type": "bold"}]}, {"text": " keeps it, ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " rewords the claim and accepts it, and ", "type": "text"}, {"text": "Reject", "type": "text", "marks": [{"type": "bold"}]}, {"text": " hides it; on a clip, Play, ", "type": "text"}, {"text": "Accept", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Reject", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". ", "type": "text"}, {"text": "Accept all", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for findings and for clips accepts everything waiting at once, after a confirmation. Nothing is deleted by deciding: an accepted finding offers ", "type": "text"}, {"text": "Undo", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and a rejected one ", "type": "text"}, {"text": "Put back for review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review findings in the source", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open a source from its project and switch the panel beside the transcript from Excerpts to ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Each finding is underlined in lime where it is in the transcript. A dashed card and dashed underline are suggestions you have not reviewed yet. The chips show ", "type": "text"}, {"text": "To review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "All", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Rejected", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and the same Accept, Edit, Reject and Play buttons are on each card. Analyze again later: accepted and rejected findings and clips are kept, and only suggestions you have not reviewed are replaced.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A finding is a paraphrase. To use the speaker''s own words, accept a clip or make an excerpt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The findings you have decided on are listed under ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the project''s Notebook, filtered Accepted, Rejected or Both, each linking to its source.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Interview audio and text are sent to an outside service to be read, as they are for transcription.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Everything here works on a phone: the Excerpts tab holds the switch, and the player stays docked at the bottom.", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.setup,sourcework.source,sourcework.project}', NULL, 19, 'release', 'Analyze from the Notebook tab, and the project''s Review tab', false, false, 4, '2026-11-05 23:48:40.791866+00', '2026-11-05 23:48:42.540935+00', NULL);
INSERT INTO public.rc_articles (id, slug, kind, title, summary, body, area, owner_role, tool_id, screen_keys, released_on, sort_order, source, version_note, needs_review, edited_since_release, version, created_at, updated_at, updated_by) VALUES
	('74d6c342-6c61-43de-aee3-e371f6e072ba', 'sourcework-search', 'guide', 'Searching across projects and sources', 'Find a transcript, excerpt or interview by what was said.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The search box on the ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework?tab=notebook"}}]}, {"text": " tab of the Sourcework home page searches every project, source, transcript, document and excerpt you can open. Type what you are looking for and press Enter.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The Notebook tab", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Notebook holds everything you can reuse, in two sections: ", "type": "text"}, {"text": "Sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (every recording and document, whichever project it is in) and ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (every saved clip and passage). One search box sits under them. In Sources the same box also narrows the list by title as you type, so you can find a source by name; press Enter to search every transcript and excerpt instead. Projects stay on their own tab, where ", "type": "text"}, {"text": "+ New project", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts one.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How results work", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Results are grouped by project, so several hits from one interview read as one project. The first three show, and ", "type": "text"}, {"text": "Show more", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the rest. The words you searched for are highlighted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The chips above the results narrow them by kind: ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "In transcripts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "In documents", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Projects", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", each with its count.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Clear search", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to return to the Notebook.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Searching inside a project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a project''s ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", the Excerpts section has a search box that covers only that project. To find a word inside one transcript, use ", "type": "text"}, {"text": "Find in this transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " above it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The line under the search box says what kind of search is running. Administrators also see whether topic search, which finds a passage by what it is about and not only its exact words, is switched on.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Topic search depends on an optional service. When it is off, keyword search still finds everything; it just will not catch a paraphrase.", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.projects,sourcework.project,sourcework.source,sourcework.sources}', NULL, 25, 'release', 'One search box in the Notebook, which also narrows Sources by title', false, false, 6, '2026-11-05 23:48:36.404985+00', '2026-11-05 23:48:42.502699+00', NULL),
	('68b622a9-b552-4c10-9e07-91ba851dc058', 'sourcework-interview-to-script', 'guide', 'From interview recording to radio script', 'Transcribe a recording, pick the actualities yourself and write the piece by hand, with no AI step.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sourcework can take a recorded interview all the way to a usable script without any of the analysis steps. This walkthrough covers transcription, excerpts you pick yourself, and the piece editor. Research questions, Analyze, Synthesis and Outline are optional.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "1. Add the recording", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open ", "type": "text"}, {"text": "Sourcework", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework"}}]}, {"text": " and select ", "type": "text"}, {"text": "+ New project", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the Projects tab. Name the project, then drop the recording onto the box or select ", "type": "text"}, {"text": "Choose files", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or add it later. For a recording that is already in the ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework?tab=notebook"}}]}, {"text": ", open the project and use ", "type": "text"}, {"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Find existing", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", instead of uploading another copy. See ", "type": "text"}, {"text": "Starting a project and adding sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-starting-a-project"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "2. Check the transcript", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select the source in the project''s list to open it. When transcription finishes, listen while following the words, which move with the audio. Check names, figures, who is speaking and any wording you might quote against the recording, and name the speakers from the ", "type": "text"}, {"text": "Speakers", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button. ", "type": "text"}, {"text": "Find in this transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " locates a phrase so you can listen around it. See ", "type": "text"}, {"text": "Working with the transcript and creating excerpts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-transcript-and-excerpts"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "3. Pick the excerpts yourself", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Find a passage that gives the story something: a concrete detail, a telling phrase, a firsthand account. A clip should make sense on its own and have clean entry and exit points. Select its words in the transcript, keep or change the suggested title, and save it as an excerpt. Play it from its card, and use ", "type": "text"}, {"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to move its start or end to a word. Repeat for other passages. Nothing has to be analyzed first.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "4. Build the script by hand", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the project, open ", "type": "text"}, {"text": "Pieces", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and select ", "type": "text"}, {"text": "+ New piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Write narration in a block, and use the ", "type": "text"}, {"text": "+", "type": "text", "marks": [{"type": "bold"}]}, {"text": " rows between blocks to add the project''s excerpts in order. Reorder, swap or remove blocks as you revise; ", "type": "text"}, {"text": "Trim…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on an excerpt block refines the cut in this piece without changing the saved excerpt. Pick a ", "type": "text"}, {"text": "Format", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under the length if you want a target, and read the length as an estimate: narration is timed at 160 words a minute, so read it aloud. See ", "type": "text"}, {"text": "Building a piece from narration and excerpts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-pieces"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "5. Prepare for production", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Listen to each finished cut against the original audio, and verify attribution, wording, context and sequence. ", "type": "text"}, {"text": "Copy as text", "type": "text", "marks": [{"type": "bold"}]}, {"text": " copies the script, and ", "type": "text"}, {"text": "Export excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " downloads the project''s clips as one zip, each at an even level. The piece saves a version as you work; ", "type": "text"}, {"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " restores an earlier one.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Optional next steps", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "From here you can ", "type": "text"}, {"text": "search across projects and sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-search"}}]}, {"text": ", have a source ", "type": "text"}, {"text": "analyzed", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-research"}}]}, {"text": " for findings and clips to review, or let AI ", "type": "text"}, {"text": "outline a piece", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-outline"}}]}, {"text": " from the findings you have accepted. They are additional ways of working, not prerequisites for a script.", "type": "text"}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.projects,sourcework.project,sourcework.pieces,sourcework.piece}', NULL, 3, 'release', 'Brought into the repository and updated: Notebook, Find existing, the format under the length', false, false, 1, '2026-11-05 23:48:42.540935+00', '2026-11-05 23:48:42.540935+00', NULL),
	('bf81b991-4ed9-4463-a805-98d6a84df1b1', 'sourcework-reference-another-source', 'guide', 'Add another source to a project', 'Upload more recordings or PDFs to a project, reuse one already in Sourcework, and move between a project''s sources.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A project can draw on more than one recording or document. When the same interview matters to more than one story, add it to each project instead of uploading it again. Every project then shares one original and one transcript.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add a source", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the project. On its ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, ", "type": "text"}, {"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sits with the filters above the source list. A project with no sources shows ", "type": "text"}, {"text": "Add the first source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " instead.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On ", "type": "text"}, {"text": "Find existing", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", search for the source by title and select ", "type": "text"}, {"text": "Reference", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It is added right away, with no confirmation step.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On ", "type": "text"}, {"text": "Upload new", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", drag in recordings or PDFs that are not in Sourcework yet, or select ", "type": "text"}, {"text": "Choose files", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". They upload the same way as from a new project.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Move between sources", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The project screen lists its sources, and each one opens as its own screen with the player, transcript and excerpts. The back link at the top of a source returns to the project, which is the way to its other sources. The link carries the project, so ", "type": "text"}, {"text": "Remove from this project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the source''s ⋮ menu knows which project to take it out of. A source opened from the home Notebook instead gains a ", "type": "text"}, {"text": "Projects", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab listing every project that uses it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The project''s Notebook also has an ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " section with every excerpt from every one of its sources, behind a search box that covers only this project, and a ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": " section with the findings decided on across them.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Take a source out of a project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Remove from this project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", in the ⋮ at the end of a source''s row or in the source''s own menu, detaches it. The recording, its transcript and its excerpts stay in the Notebook and in any other project that uses it. ", "type": "text"}, {"text": "Delete source…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", on the source''s own screen only, deletes it everywhere, with its transcript and every excerpt made from it, and asks you to confirm.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An excerpt belongs to the source it was made from, so it shows in every project that uses that source.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Retrying a failed transcription retries that source alone.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "PDF documents are added the same way as audio. They open in the document viewer instead of the player.", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.project}', NULL, 10, 'release', 'The source switcher is gone: each source is its own screen, reached from the project''s list', false, false, 6, '2026-11-05 23:48:36.124228+00', '2026-11-05 23:48:42.540935+00', NULL),
	('fe78fd65-3b6d-4836-9358-678c36977395', 'sourcework-pieces', 'guide', 'Building a piece from narration and excerpts', 'Write a wrap, voicer or feature block by block, or outline it from your findings, then edit by hand or with the assistant. Every version is kept.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A piece is a reader, voicer, wrap, spot or feature you build from your own narration and the project''s excerpts. It starts blank. You can write it block by block, or let AI outline it from your accepted findings, write the outline out as narration, and then edit it by hand or with the assistant.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Start a piece", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open a project, select ", "type": "text"}, {"text": "Pieces", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "+ New piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The editor opens at once on an empty piece with its title ready to type, and a ", "type": "text"}, {"text": "Start your piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel offers ", "type": "text"}, {"text": "+ Narration", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "+ Excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Outline with AI", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The Pieces list shows each piece''s length, how it was made and when it last changed, with a search box once there are pieces.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A format sets the piece''s target length and gives you a guide to write by. Choose one, or change it, any time from ", "type": "text"}, {"text": "Format", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under the length at the top of the piece, and ", "type": "text"}, {"text": "Show guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows its description. The guide is a reminder of what the format usually asks for; it doesn''t stop you doing something else. Choosing a format doesn''t change what you''ve written.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The formats are Reader / Voicer (about 0:30 to 0:45, no recorded excerpts), Cut and Copy (0:45, one excerpt), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). The excerpt counts are a usual range, not a requirement: a strong piece can use fewer.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Outline and write it out (optional)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On an empty piece, choose ", "type": "text"}, {"text": "Outline with AI", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It plans the story as beats, with your excerpts placed where they belong, from the findings you have accepted. A piece with beats shows ", "type": "text"}, {"text": "Write from outline", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", which turns each beat into narration in place. Both are versions you can undo, and nothing is written until you ask. ", "type": "text"}, {"text": "Outline a piece", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-outline"}}]}, {"text": " has the details.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add narration and excerpts", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Narration", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Write in a narration block. Press Enter at the end of a block to add another below it, and Shift+Enter for a new line. Backspace in an empty block removes it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Between every block, and before the first and after the last, there is a + row. Select it and choose ", "type": "text"}, {"text": "Excerpt from this project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to search the project''s audio excerpts by title, words, speaker or source. Arrow keys move through the results and Enter adds one. The same row adds a narration block or an outline beat.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An excerpt''s words always come from the transcript for the clip you hear. They cannot be retyped in the piece.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a block", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select the ⋮ beside a block for ", "type": "text"}, {"text": "Move up", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Move down", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Mark as anchor intro", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (on narration), ", "type": "text"}, {"text": "Swap excerpt…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Trim…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and removal. On a desktop you can also drag the ⋮⋮ handle to reorder.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An ", "type": "text"}, {"text": "anchor intro", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the lead-in the anchor reads before a reporter''s recorded piece. It is shown as its own block and isn''t counted in the piece''s length, so a 0:53 wrap stays 0:53 whatever the intro adds. Reader, voicer and cut and copy copy is part of the piece and is timed with it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Trim a clip in place", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Choose ", "type": "text"}, {"text": "Trim…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on an excerpt block. The clip''s words appear in their transcript context. Tap a word to move the nearer end of the clip there, or nudge the start and end with the −250, −50, +50 and +250 buttons. ", "type": "text"}, {"text": "Play as cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays what you have. The same panel shortens long pauses; see ", "type": "text"}, {"text": "Trim a clip and shorten its pauses", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-piece-trim-and-pauses"}}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "By default a trim belongs to this piece only and the excerpt itself is unchanged. Choose ", "type": "text"}, {"text": "Update the excerpt everywhere", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change the excerpt itself; the panel says how many other pieces use it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Length", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The length at the top adds up narration, estimated at 160 words a minute, and the clips'' own running time, without any anchor intro. Choosing a format sets a target; select ", "type": "text"}, {"text": "Change target", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to use a different one. The piece shows how far under or over it is.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Ask the assistant", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open the assistant from ", "type": "text"}, {"text": "Assistant", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the top of the piece (on a phone, the bar at the bottom). It knows which piece you have open and says so at the top: “Working in: …”. Ask it to tighten a passage, move a quote, trim a clip, add a line, or outline the piece again. Anything you have typed is saved before your message goes.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "It changes only what you ask, and says what it changed. Its reply lists the tools it used.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "It places and swaps excerpts by id. It can''t change what a speaker said, and the lengths it reports come from the same arithmetic as the screen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each block it changed is marked ", "type": "text"}, {"text": "Edited by the assistant", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Added by the assistant", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". ", "type": "text"}, {"text": "Undo", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the mark puts that block back. The marks stay until you next edit the piece yourself.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "From a + row, ", "type": "text"}, {"text": "Ask the assistant to write it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the assistant with a request for narration at that spot, for you to finish and send.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Saving and history", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A piece saves itself a moment after you stop typing. Every save is a version, including each change the assistant makes and every outline or write-out.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the versions with who saved each one, and whether it was you, an outline or a write-out, or the assistant. Restore saves an earlier version again as the newest, so nothing is lost.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If someone else saves the piece while you are editing, you are asked to reload instead of overwriting their work.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Take it with you, or delete it", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Copy as text", "type": "text", "marks": [{"type": "bold"}]}, {"text": " copies the narration and the quoted words, with each clip''s length and the total running time. ", "type": "text"}, {"text": "Export excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " downloads every excerpt in the project as one zip. ", "type": "text"}, {"text": "Delete piece…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", in the ⋮ at the top of the piece, removes the piece and its history after a confirmation; the project''s excerpts are not affected.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only audio and video excerpts can go in a piece. Document excerpts have no sound.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If an excerpt is deleted after it was used, its block says so and can be swapped or removed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Everything on a piece works on a phone: menus and the + picker open as sheets, and Move up and Move down replace dragging.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Outlining, writing out and the assistant send the piece''s material (accepted findings and the excerpts'' words) to an outside service, as analysis does. Building a piece by hand doesn''t.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Pieces list says how each piece was made: Written by hand, or the format it was written from, then edited.", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.pieces,sourcework.piece}', NULL, 18, 'release', 'The Start your piece panel, search in the Pieces list, and Delete piece', false, false, 8, '2026-11-05 23:48:40.672639+00', '2026-11-05 23:48:42.540935+00', NULL),
	('efb5f849-e15a-43f7-b1f1-ecb08dc9212c', 'sourcework-suggested-quotes', 'guide', 'Clips to review', 'Play, trim, accept or reject the clips Analyze proposed from a source.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A clip is a literal cut of a recording that Analyze thought might work on air, as against a finding, which is a paraphrase. Nothing becomes an excerpt until you accept it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Where clips are", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Analyzing a source proposes up to five clips. They appear on the project''s ", "type": "text"}, {"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, grouped with that source''s findings, and on the source''s own page under ", "type": "text"}, {"text": "Clips to review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", above the findings in the Data points panel. The section is absent when none is waiting; often there are none.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Decide on each clip", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each card shows who says it, the words, its length and why it works.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Play", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays the clip as it will cut, from the original audio. Check the words as you listen: the transcript is itself a machine reading of the audio.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Accept", "type": "text", "marks": [{"type": "bold"}]}, {"text": " saves the clip as an ordinary excerpt on its source. It then appears in the source''s excerpts, in the project''s Excerpts section and in the piece editor''s excerpt picker.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the start and end with the −250, −50, +50 and +250 buttons; ", "type": "text"}, {"text": "Back to the suggested cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " undoes them. Play again to hear the new cut, then Accept. The words are read again from the transcript for the range you accept.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Reject", "type": "text", "marks": [{"type": "bold"}]}, {"text": " hides the clip. It is kept, so the same stretch is not suggested again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Review tab, ", "type": "text"}, {"text": "Accept all N clips", "type": "text", "marks": [{"type": "bold"}]}, {"text": " accepts every waiting clip at the range proposed, after a confirmation.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Clips are only ever taken from the speaker''s own words, one speaker at a time, at sentence edges, between 1.5 and 60 seconds.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Everything here works on a phone: cards stack, and the buttons are larger.", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.project,sourcework.source}', NULL, 23, 'release', 'Rewritten for Analyze''s clips; themes and tiers are gone', false, false, 1, '2026-11-05 23:48:42.540935+00', '2026-11-05 23:48:42.540935+00', NULL),
	('3d67c4db-6fd6-45ed-a81f-1e6849124247', 'sourcework-research-prompts', 'guide', 'Maintaining the prompts', 'For editors: the Analyze, Synthesis, Outline and Writing guides the model works from. Edit, publish and roll back.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Editors maintain the wording the model works from. You need the Editor role on Sourcework, which an administrator grants on the user''s access screen; with it, a ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab appears at the right of the Sourcework tabs, with ", "type": "text"}, {"text": "Prompts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Piece formats", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a prompt", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Prompts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Choose a guide on the left (on a phone, from the list at the top): the ", "type": "text"}, {"text": "Analyze guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " decides what makes a finding worth keeping and a clip worth offering; the ", "type": "text"}, {"text": "Synthesis guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " how the accepted findings are weighed against the research questions; the ", "type": "text"}, {"text": "Outline guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " what makes a good outline and which clips earn a place in it; and the ", "type": "text"}, {"text": "Writing guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " the house style of the narration Write from outline produces, such as the tense of attribution. Edit the text and it saves itself as a draft only you can see. The shape of the answer is fixed by the code, and ", "type": "text"}, {"text": "What the model is given and returns", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows both. ", "type": "text"}, {"text": "Discard draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " goes back to the live text.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Publish and roll back", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Publish", "type": "text", "marks": [{"type": "bold"}]}, {"text": " asks for a one-line note about what changed, then makes the draft the live version for every project''s next run.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists earlier versions with their notes and, for the Analyze guide, the share of its findings people accepted. ", "type": "text"}, {"text": "Edit from this version", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts a draft from it, and ", "type": "text"}, {"text": "Make live again", "type": "text", "marks": [{"type": "bold"}]}, {"text": " moves an earlier version back into use. Nothing is deleted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Until something is published, a prompt runs on its built-in text.", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.editors}', NULL, 20, 'release', 'Reached from the Setup tab; the Writing guide', false, false, 5, '2026-11-05 23:48:40.791866+00', '2026-11-05 23:48:42.540935+00', NULL),
	('303db882-a2f3-47ad-9a3a-cbac5ef0e4c0', 'sourcework-accept-in-bulk', 'guide', 'Accepting suggestions in bulk', 'Accept every finding or clip waiting in a project, or in one source, at once instead of one by one.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "When Analyze suggests a lot of findings, you do not have to decide on each one separately. Each accept-all button asks you to confirm first, because you are deciding on many things without reading each.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "On the project''s Review tab", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The panel at the top says how many findings and clips, from how many sources, are waiting. ", "type": "text"}, {"text": "Accept all", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the count accepts every waiting finding in the project. ", "type": "text"}, {"text": "Accept all", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the count of clips makes every waiting clip into an excerpt at the range Analyze proposed; each can still be trimmed or deleted in its source afterwards, and a clip that couldn''t be accepted stays waiting, which the message says.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "In one source", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On a source''s Data points panel, with the ", "type": "text"}, {"text": "To review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " filter showing and more than one finding waiting, ", "type": "text"}, {"text": "Accept all", "type": "text", "marks": [{"type": "bold"}]}, {"text": " accepts the findings waiting in that source only. Findings you have already decided on are left as they are.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Taking a decision back", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nothing is deleted by accepting. A finding can be rejected or put back for review afterwards, and an accepted clip is an ordinary excerpt you can delete.", "type": "text"}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.project,sourcework.source}', NULL, 24, 'release', 'The Review tab''s two accept-all buttons', false, false, 4, '2026-11-05 23:48:41.490889+00', '2026-11-05 23:48:42.540935+00', NULL),
	('887b4b28-d9cb-47a5-a459-be469dbe1681', 'sourcework-outline', 'guide', 'Outline a piece', 'Plan a piece as beats before any narration is written, then write the outline out in place.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "An outline plans a piece before any narration is written. It is a list of beats, each saying what that part of the story has to do, with your excerpts placed where they belong. You edit the outline, then write it out. Nothing is written for you until you ask.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Outline an empty piece", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open a new piece and choose ", "type": "text"}, {"text": "Outline with AI", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the ", "type": "text"}, {"text": "Start your piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel. The card says which format it is writing to; change it with ", "type": "text"}, {"text": "Format", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the top of the piece, where the format''s guide is. Add a direction if you have one, and choose ", "type": "text"}, {"text": "Outline the piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It can take a few minutes, because the model may check the transcripts.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "It works from the findings you have accepted, the project''s synthesis if there is one, and the project''s excerpts, up to the 150 newest. The first beat is the angle: the point of the piece in a sentence.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If the project has no accepted excerpts yet, the panel says so and links to the Review tab, since an outline can only place excerpts you have accepted and this one would be beats with no tape. The message also says how many suggestions are still waiting for review. Once the project has an excerpt, no warning is shown, even with suggestions waiting.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The result is an ordinary version. Use History to go back, and edit it like any other piece.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Read a beat", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A beat takes no time, so the length at the top counts only narration and excerpts.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "What carries it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the findings the beat rests on, with a link to listen where each was said. A finding you have since rejected is counted as no longer accepted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mark to check", "type": "text", "marks": [{"type": "bold"}]}, {"text": " flags a beat whose figure, name or attribution rests on one source or isn''t settled. When the outline is written out, that sentence gets a bracketed check note instead of being stated as fact.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tape", "type": "text", "marks": [{"type": "bold"}]}, {"text": " links to a stretch of a recording the outline thought worth your attention that is not an excerpt yet. Open it, and make an excerpt if you want it in the piece.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Change the outline", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Edit a beat''s text directly. Use the + between blocks to add a narration block, an outline beat or an excerpt, and the ⋮ menu to move or remove one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The assistant can add and change beats too. Every change it makes is a version you can undo.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Write from outline", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A piece with beats shows ", "type": "text"}, {"text": "Write from outline", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It writes each beat out as narration, in the same place, following the Writing guide editors maintain.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Your excerpts, their trims, and anything you already wrote stay exactly as they are. The model cannot reorder the piece, add a clip or drop one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A beat the model leaves unwritten stays in the outline, and the page says how many. Undo returns you to the outline.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An outline and a draft are suggestions. Check every name, figure and attribution before you air anything.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A project with more than 150 excerpts has its oldest ones left out of the outline; an excerpt the outline did not place can still be added by hand.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Interview text and your findings are sent to an outside service, as for transcription.", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.piece}', NULL, 22, 'release', 'When the readiness warning shows, and the 150-excerpt limit', false, false, 3, '2026-11-05 23:48:41.938588+00', '2026-11-05 23:48:42.616845+00', NULL),
	('82b6e8dd-0fd7-438a-a656-99320afb3e45', 'sourcework-browse-source-library', 'guide', 'Browse the Notebook', 'Every recording, document and excerpt in Sourcework, whichever project it came from.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab on the Sourcework home lists everything you can reuse, independent of the projects that use it, in two sections.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Sources", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Every recording and document, as cards showing its kind, date, length or page count, and how many projects use it. The chips narrow the cards to ", "type": "text"}, {"text": "Audio", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "PDF", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and typing in the search box narrows them by title as you type; Enter searches every transcript and excerpt instead, see ", "type": "text"}, {"text": "Searching across projects and sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-search"}}]}, {"text": ". Select a card to open the source on its own: the same player, transcript and excerpts a project shows, or the page viewer and text for a PDF, plus a ", "type": "text"}, {"text": "Projects", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab listing every project that uses it, with a filter once there are eight.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Excerpts", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Every saved clip and passage. The title opens the source at that excerpt, and the project name opens the project it belongs to.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A source is the original recording or document. It is never edited; a project is the work that refers to it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To use a source in another story, add it from that project with ", "type": "text"}, {"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Find existing", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A source opened from the Notebook can be deleted from its ⋮ menu, everywhere at once; one opened from a project can also be removed from just that project.", "type": "text"}]}]}]}]}', NULL, NULL, '503e8057-ca63-47a3-ad8b-4f73983b8ef9', '{sourcework.sources,sourcework.source}', NULL, 20, 'release', 'The Source Library became the Notebook''s Sources section', false, false, 4, '2026-11-05 23:48:36.124228+00', '2026-11-05 23:48:42.540935+00', NULL);
INSERT INTO public.rc_article_versions (id, article_id, version, title, body, source, note, created_at, created_by) VALUES
	('702e167b-c48b-4d0f-82bf-6f8f6ebb22a1', 'b8c1f09e-4659-4f0a-aa4a-73d42a71c973', 4, 'Setting up a contract', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A contract''s setup is five steps end to end, taking a signed order from a blank form to something that can actually be scheduled.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Order", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select the underwriter, enter the order number, the sponsorship total, the campaign''s run dates, a sponsorship category, and an account rep, with optional notes. Leave the order number blank if the order doesn''t print one; the contract then shows “No order number”.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Continue to schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — or, instead of typing everything by hand, upload the signed agreement under “Or start from the signed agreement” and select ", "type": "text"}, {"text": "Create from the agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to have it read from the document. What you''ve already typed always wins over its reading.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Schedule", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Add each line from the order — pool or program, days, dates, spot count, and the rest — through the schedule line editor, one at a time. A time window that ends at 12:00 AM runs until midnight. Select ", "type": "text"}, {"text": "Continue to copy", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Copy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Link or create the underwriting messages this contract will run, on the Copy step — the same panel the contract''s own Copy tab uses later. Select ", "type": "text"}, {"text": "Continue to traffic policy", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Traffic policy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Set the total spots on the order, the preemption/makegood policy, whether an affidavit is required, whether makegoods need agency approval, and separation. Select ", "type": "text"}, {"text": "Save policy", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Continue to review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review and activate", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The contract page shows a “Ready to activate?” checklist against the order, agreement, schedule, copy, and policy, each with a fix-it link if something''s missing. Select ", "type": "text"}, {"text": "Activate contract", "type": "text", "marks": [{"type": "bold"}]}, {"text": " once it''s clear.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How an order''s wording becomes lines", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An instruction that offers a choice stays one line in a pool that covers every choice: “Drive Time” runs in the Drive Time pool (AM or PM Drive), and “either Saturday or Sunday Weekend Edition” in the Weekend Edition pool.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An order that splits its count gets one line per part: “3 per week: 1 Living on Earth, 1 AM/PM Drive, 1 Science Friday” is three lines.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "“Rotating” between two dayparts alternates week by week: two every-other-week lines, the second starting a week after the first.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An instruction that names no pool or program runs anywhere, in Total Program Rotation, narrowed by its days and times.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A product like the Learning Minute is a kind of credit, not a pool: its line keeps the order''s day and exact time.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Nothing schedules until activation — a draft contract can be edited freely, and can be deleted outright if it turns out not to be needed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "“Create from the agreement” reads a scanned or photographed signed order with one model call; it never invents a sponsor, program, pool, or order number. Anything that isn''t a schedule of broadcast credits, such as app or website ads, is listed on the schedule step for you to handle.", "type": "text"}]}]}]}]}', 'release', 'Optional order numbers, midnight windows, and how an order''s wording becomes lines', '2026-11-05 23:48:37.426941+00', NULL),
	('53dc1ac7-cc79-413a-94c5-04588ca295c3', '887b4b28-d9cb-47a5-a459-be469dbe1681', 3, 'Outline a piece', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "An outline plans a piece before any narration is written. It is a list of beats, each saying what that part of the story has to do, with your excerpts placed where they belong. You edit the outline, then write it out. Nothing is written for you until you ask.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Outline an empty piece", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open a new piece and choose ", "type": "text"}, {"text": "Outline with AI", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the ", "type": "text"}, {"text": "Start your piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel. The card says which format it is writing to; change it with ", "type": "text"}, {"text": "Format", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the top of the piece, where the format''s guide is. Add a direction if you have one, and choose ", "type": "text"}, {"text": "Outline the piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It can take a few minutes, because the model may check the transcripts.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "It works from the findings you have accepted, the project''s synthesis if there is one, and the project''s excerpts, up to the 150 newest. The first beat is the angle: the point of the piece in a sentence.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If the project has no accepted excerpts yet, the panel says so and links to the Review tab, since an outline can only place excerpts you have accepted and this one would be beats with no tape. The message also says how many suggestions are still waiting for review. Once the project has an excerpt, no warning is shown, even with suggestions waiting.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The result is an ordinary version. Use History to go back, and edit it like any other piece.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Read a beat", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A beat takes no time, so the length at the top counts only narration and excerpts.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "What carries it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the findings the beat rests on, with a link to listen where each was said. A finding you have since rejected is counted as no longer accepted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mark to check", "type": "text", "marks": [{"type": "bold"}]}, {"text": " flags a beat whose figure, name or attribution rests on one source or isn''t settled. When the outline is written out, that sentence gets a bracketed check note instead of being stated as fact.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tape", "type": "text", "marks": [{"type": "bold"}]}, {"text": " links to a stretch of a recording the outline thought worth your attention that is not an excerpt yet. Open it, and make an excerpt if you want it in the piece.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Change the outline", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Edit a beat''s text directly. Use the + between blocks to add a narration block, an outline beat or an excerpt, and the ⋮ menu to move or remove one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The assistant can add and change beats too. Every change it makes is a version you can undo.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Write from outline", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A piece with beats shows ", "type": "text"}, {"text": "Write from outline", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It writes each beat out as narration, in the same place, following the Writing guide editors maintain.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Your excerpts, their trims, and anything you already wrote stay exactly as they are. The model cannot reorder the piece, add a clip or drop one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A beat the model leaves unwritten stays in the outline, and the page says how many. Undo returns you to the outline.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An outline and a draft are suggestions. Check every name, figure and attribution before you air anything.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A project with more than 150 excerpts has its oldest ones left out of the outline; an excerpt the outline did not place can still be added by hand.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Interview text and your findings are sent to an outside service, as for transcription.", "type": "text"}]}]}]}]}', 'release', 'When the readiness warning shows, and the 150-excerpt limit', '2026-11-05 23:48:42.616845+00', NULL),
	('d3e906d5-abe8-452e-a2d3-cd04e72c9880', '89f6a164-b011-4cc5-9d3e-13bfe7c4b27a', 1, 'Create and publish a query', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A query is a recorded callout: up to five questions a listener answers out loud, from a standalone page or an embed in a story.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Create it", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "New query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Give it an internal title (the newsroom''s name for it), a public title, and a public introduction saying why you''re asking and what you''ll do with the answers. Select ", "type": "text"}, {"text": "Create query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the ", "type": "text"}, {"text": "Questions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, add each question: the prompt, optional guidance, a maximum length, and whether it''s required.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the ", "type": "text"}, {"text": "Settings", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, choose which details to ask participants for, the consent and attribution questions, and optional opening and closing dates.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Preview", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to walk through it as a participant would. Nothing is submitted.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Publish it", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Open for responses", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Until then the public link doesn''t work, even for someone who has it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the ", "type": "text"}, {"text": "Share", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, copy the public link for newsletters and social posts, or the Grove embed code to paste into a Grove Responsive Embed element unchanged. If you add questions later, copy the embed code again.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once a query has submissions, question wording can still change, but questions can''t be removed or reordered. Each answer keeps the exact question it was asked.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Close query", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to stop new responses. Anyone already recording can still finish and submit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A query can be deleted only before it has any submissions. After that, archive it.", "type": "text"}]}]}]}]}', 'release', 'Written for the Resources backfill', '2026-11-05 23:48:36.556372+00', NULL),
	('49cd23f8-3262-465e-9098-64ce2049826e', '63f0b6a0-82e3-4e29-9e63-d833bcdbca04', 1, 'Work an inquiry through the pipeline', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Faculty inquiries from the public form arrive in the ", "type": "text"}, {"text": "New", "type": "text", "marks": [{"type": "bold"}]}, {"text": " column of the Pipeline. From there they move through Reviewing, Meeting Requested, Scoping, Approved, Active, and Completed.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Move an inquiry", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Drag the card to another column.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Or use the stage menu under the card. It works by keyboard, screen reader, and touch.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the inquiry''s own page, change its ", "type": "text"}, {"text": "Stage", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and select ", "type": "text"}, {"text": "Save", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Work the inquiry", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select the card to open it. The original response is at the top.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Set an ", "type": "text"}, {"text": "Owner", "type": "text", "marks": [{"type": "bold"}]}, {"text": " so the team knows who has it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Record an ", "type": "text"}, {"text": "Assessment", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — overall fit, capacity, and timing — and a ", "type": "text"}, {"text": "Next action", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with a date. The date shows on the card.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add internal notes. Everything is recorded in the inquiry''s ", "type": "text"}, {"text": "Activity", "type": "text", "marks": [{"type": "bold"}]}, {"text": " log.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Close one without completing it", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Under ", "type": "text"}, {"text": "Disposition", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose Deferred, Declined, Withdrawn, or Archived and select ", "type": "text"}, {"text": "Apply", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Every choice except Archived needs a reason. The inquiry leaves the board but keeps the stage it reached; find it on ", "type": "text"}, {"text": "All submissions", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and select ", "type": "text"}, {"text": "Reopen", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to bring it back.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Coordinators can also delete an inquiry permanently from the Danger zone at the bottom of its page.", "type": "text"}]}]}', 'release', 'Written for the Resources backfill', '2026-11-05 23:48:36.556372+00', NULL),
	('843bf223-3ad7-4c07-a678-ebb0d9350e33', '58b99723-7e12-4ed7-9913-37ea8382641f', 1, 'Email a faculty member', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Replies to an inquiry start from a template, filled in with the inquiry''s details.", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "In the ", "type": "text"}, {"text": "Email", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel on the inquiry''s page, choose a ", "type": "text"}, {"text": "Template", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", such as Invite to meet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add a sentence or two specific to this inquiry under ", "type": "text"}, {"text": "Add context", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and check the preview.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Send email to", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and the faculty member''s address. For an invitation to meet, the inquiry moves to Meeting Requested and records that the appointments link was shared, unless you untick those boxes.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Sending it yourself", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Open email draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Copy draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to send from your own mail, then ", "type": "text"}, {"text": "I sent this email", "type": "text", "marks": [{"type": "bold"}]}, {"text": " so the activity log records it. When the portal isn''t set up to send email, this is the only path.", "type": "text"}]}]}', 'release', 'Written for the Resources backfill', '2026-11-05 23:48:36.556372+00', NULL),
	('070ce45c-aeeb-43a9-8be1-eb47fbca0eca', 'd42c0047-1a5b-4ab1-9155-1c13ef073672', 1, 'Share the inquiry form and change its settings', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Settings holds the public inquiry form''s link and embed, and its configuration. Everyone on the tool can read it; only coordinators can change it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Share the form", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Copy the ", "type": "text"}, {"text": "Public link", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or the ", "type": "text"}, {"text": "Grove embed code", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to paste into a Grove Responsive Embed element unchanged.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Change it (coordinators)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Untick ", "type": "text"}, {"text": "Accepting submissions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to close the form. Turn on only the partnership types you''re ready to take.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Edit the introductory and confirmation copy, and the Google Appointments URL used by Invite to meet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Edit each email template''s subject and body. Tokens such as {{faculty_name}} are filled in when a template is used.", "type": "text"}]}]}]}]}', 'release', 'Written for the Resources backfill', '2026-11-05 23:48:36.556372+00', NULL),
	('51f57d7f-946d-47a7-a8df-4540d6b9daf3', 'a1318d88-698d-42e0-b368-df5ba1a1d951', 3, 'Running the daily rundown and host console', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "rundown''s screen", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log"}}]}, {"text": " does double duty: build it ahead of time, then run the same screen live once you start the broadcast.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Generate and fill", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Today screen, select ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " next to a program that doesn''t have a rundown yet for that date.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open it. Hover the thin line between items in a break to fill it — search the eligible content library, add today''s weather, or create a one-off live read right there.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Go live", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Start broadcast", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the sidebar. The current break is highlighted, and the mid-broadcast controls appear on every unconfirmed item across the whole rundown.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "During the broadcast", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On an underwriting credit, confirm it with ", "type": "text"}, {"text": "Yes, aired", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "No — flag it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (choosing a reason). Ordinary content has no aired/missed confirmation — only a credit carries that obligation.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Move any item with its ", "type": "text"}, {"text": "⋮", "type": "text", "marks": [{"type": "bold"}]}, {"text": " menu, or drag it to a different break.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Wrap up", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Once the program''s shift has ended, a Wrap-up panel appears in the sidebar and lists anything unresolved. Before then it is hidden, to leave room. Optionally attest or mark items aired in bulk, then select ", "type": "text"}, {"text": "Submit rundown", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — a checkpoint, not a lock. A correction after submission works exactly the same as before it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Aired, missed, and move actions are queued on your device and sent once you''re back online — a dropped connection doesn''t lose them.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Adding content to a break needs a live connection, since it''s a request to the server rather than a queued action.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The sidebar''s ", "type": "text"}, {"text": "Florida News Exchange", "type": "text", "marks": [{"type": "bold"}]}, {"text": " card lists the three newest stories other Florida stations shared through PRX, each linking to its PRX page in a new tab. ", "type": "text"}, {"text": "All stories", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the full list on the Sources tab.", "type": "text"}]}]}]}]}', 'release', 'Wrap up appears when the program ends; Florida News Exchange card', '2026-11-05 23:48:40.118524+00', NULL),
	('fe5be1a1-5d92-4e4b-bb1e-d31322302900', '0d57bc6b-2958-4c50-92b1-933944359497', 5, 'The calendar and the term plan', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Calendar", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/calendar"}}]}, {"text": " tab shows one term of production work: what WUWF has kept for itself, what partners have booked, and how much of the term''s capacity is left. Everything on it is measured in professional hours; a project day is eight.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The term plan", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Director of Operations creates a term plan from ", "type": "text"}, {"text": "Term plan", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the term''s dates, the airtime minutes a week the station contributes, and, for each labor class, the hours it has available for production work, an optional reserve share of them, its headcount and its hours a day. Terms can be active together as long as their dates do not overlap, and a date books against the term it falls in. A closed term is final: its figures cannot change, nothing new books into it, and a correction is a new term plan.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each pool (studio, field, live, edit) has its units for the term and the windows a booking may take, such as a studio morning or afternoon. Select ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a pool''s row to change them.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The two envelopes", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Production capacity", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows the hours available, the reserve left for strategic work, what is spoken for (bookings and holds) and open capacity. Open capacity is the hours available minus the reserve, minus holds, minus the other bookings. A class with no reserve share, such as the student crew, has no reserve: every booking of it draws open capacity. Open the month table to see how it is spread across the term.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Airtime envelope", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is read from On Air''s clocks: the avails marked as admitting a university announcement, the minutes the station already pins there, the contributed envelope from the term plan, and what is left for Traffic to sell. Airtime is placed in Traffic or On Air, never here.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Blackouts, holds, bookings and reserved blocks", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "blackout", "type": "text", "marks": [{"type": "bold"}]}, {"text": " closes dates to partner work on some or every pool, with a reason; one that spans two terms is kept once for each. A ", "type": "text"}, {"text": "hold", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is WUWF''s own use of one window, core work or maintenance, and takes the lead''s hours for that day. The director adds both with ", "type": "text"}, {"text": "+ Blackout", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "+ Hold", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "booking", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a partner''s hold on one window. The production lead or the director adds one with ", "type": "text"}, {"text": "+ Booking", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A tentative booking holds the window for 14 days and counts as taken; confirm it or release it from the list under the calendar.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Find a slot", "type": "text", "marks": [{"type": "bold"}]}, {"text": " runs the booking rule for a window without booking it, and names the nearest open windows when the one asked for is not available.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "reserved block", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a window an approved agreement holds for its partner, shown with a dotted frame until the partner''s request takes it. Other partners cannot book it until its release deadline; the director keeps or releases blocks from the agreement''s page under Partners.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The booking rule", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Every booking is checked in this order: the date is not blacked out or held for WUWF; the window is not reserved for another partner under an agreement; the window is free, with tentative bookings and reserved blocks counted as taken; the lead''s day has room for the hours; and the pricing has capacity. A strategic booking draws the reserve; an incremental or external one draws open capacity. A booking that would take more than half of a month''s remaining open hours warns but is not refused. Only the Executive Director can record an exception, and each one is written to the audit log.", "type": "text"}]}]}', 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', '2026-11-05 23:48:39.815325+00', NULL),
	('4d72487c-f81a-4f90-b547-c24cb06febc3', '2f49cb16-4c40-49e6-ae7d-f8346d4e3923', 3, 'The term report', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Term report", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/report"}}]}, {"text": " totals what the term''s work cost WUWF, what partners paid and what WUWF contributed. Open it from the link at the foot of the Dashboard. It reads the figures each estimate stored when it was priced, so it follows the rates in use at the time rather than today''s.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Full cost is the modeled labor, equipment and space, and direct expenses. WUWF contributes is the full cost the partner''s payment doesn''t cover, never negative. Partners pay is the total of the estimates'' lines.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The tables split the same figures by rate and by partner, count strategic requests however they were priced, and set the $500 webcast against modeled cost.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Assumed versus observed", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A read-only view compares each package''s hours with the hours confirmed after delivery, resource units planned with units used, and shows the dates refused or released by resource. It informs the next rate model version; it never changes a price.", "type": "text"}]}]}', 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', '2026-11-05 23:48:39.815325+00', NULL),
	('c8f2646a-337e-4e3d-a6f2-240c3d182e1f', '30e775ce-9c91-4ceb-a45b-77f137872dd8', 6, 'Schedule a program', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Schedule", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": " tab is where the schedule and every clock are reached from. Its row of pages is ", "type": "text"}, {"text": "Programs", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (what airs when), ", "type": "text"}, {"text": "Automation", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (when no one is in the studio), and ", "type": "text"}, {"text": "Underwriting", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (hours closed to underwriting credits). Scheduling and changing a clock are the program director''s tasks.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "See the schedule", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Week", "type": "text", "marks": [{"type": "bold"}]}, {"text": " view shows the week as a grid, one column per day, with each program at its air time and the clock it runs on. Behind the programs, grey shading is the automated hours and red hatching is the hours closed to underwriting, each edited on its own page. Programs still on the shared placeholder clock are shaded amber. Select a block to see its details, then ", "type": "text"}, {"text": "Edit schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Open program", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Use Prev, Next, and Today to change the week. The ", "type": "text"}, {"text": "List", "type": "text", "marks": [{"type": "bold"}]}, {"text": " view shows the same programs as a table.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find what needs attention", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the list, ", "type": "text"}, {"text": "Needs a clock", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows the programs still on the placeholder clock, and ", "type": "text"}, {"text": "Not scheduled", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows programs with no current schedule. Clocks no program uses are listed under ", "type": "text"}, {"text": "Unused clocks", "type": "text", "marks": [{"type": "bold"}]}, {"text": " below the list.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Change when a program airs", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the program. Under ", "type": "text"}, {"text": "When it airs", "type": "text", "marks": [{"type": "bold"}]}, {"text": " each schedule shows its days and time; select ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The clock it runs on is changed in the same editor.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose the days, the start time, and the length. The quick buttons set weekdays, the weekend, or every day.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Set when the schedule starts and, if it stops, when it ends. Pick the clock it runs on.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Check the preview on the right. It shows the times, the next airing, and whether another program airs at the same time on those days. An overlap is a warning; it doesn''t stop you saving.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Save schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Rundowns that were already generated keep the clock they were built from; a new clock applies to rundowns generated from then on.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add a schedule", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "+ Add a time", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a program''s page, choose its days, time, and clock, and save. If the clock doesn''t exist yet, select ", "type": "text"}, {"text": "Create a clock for this program", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a program''s details", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Details", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel on a program''s page holds its name, kind, description, and NPR connection. The program director selects ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the panel to change them in place, then ", "type": "text"}, {"text": "Save changes", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Collection ID", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is NPR''s ID for the program. With it set, On Air reads that day''s NPR stories for the program''s rundowns. Leave it blank to stop reading NPR for the program.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Feed''s first hour (Eastern)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " only matters for NPR''s multi-hour shows, whose hours alternate on the feed. It lines up NPR''s hours with ours so estimated story times are right. Leave it on ", "type": "text"}, {"text": "Same as our schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": " unless NPR''s first hour differs.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Changing the collection ID clears the program''s saved NPR stories from today on, so the next look fetches the new ones. Earlier dates keep what they had.", "type": "text"}]}]}]}]}', 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', '2026-11-05 23:48:39.815325+00', NULL),
	('bee7adbd-ac1a-482a-afdc-c8958eb59816', '310b1c15-70f2-40cc-a525-721faf939226', 2, 'The dashboard', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Dashboard", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings"}}]}, {"text": " is where Bookings opens. It shows the active term''s production capacity as one bar — strategic bookings against the reserve, the reserve still to preserve, incremental and external bookings, hours held for WUWF''s own work, and what is open — and the airtime envelope in one line: contributed minutes a week, how much is committed to requests, and what is left.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Needs your action", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists what each open request is waiting on, filtered to your roles: a request without an estimate, an estimate about to expire or expired, a booked event that has passed and needs marking delivered, and a request that needs editorial review. A member with no role sees every item.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "This week", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the partner dates held or confirmed this week, linked to their requests.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The four tiles count open requests by stage and link to the Requests list filtered to each.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Nothing shows until the Director of Operations has activated a term plan on the Calendar tab.", "type": "text"}]}]}', 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', '2026-11-05 23:48:39.815325+00', NULL),
	('cfe6ce65-84cd-4c26-bcb8-6e6c5b6f7f7a', '9edfdaf0-a4a3-49fd-a7ef-1058eef1fd1c', 4, 'The DAD log', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The DAD log is the file DAD merges into a day''s playlist so it plays that day''s credits in automated hours. Open it from ", "type": "text"}, {"text": "Today", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with ", "type": "text"}, {"text": "DAD log", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/log/dad-log"}}]}, {"text": ". Only breaks in automated hours are in the file; hosted hours are left to the host.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Before releasing", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The bar at the top shades the day''s automated hours. Change them on ", "type": "text"}, {"text": "Automated hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", reached from Programs.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Anything DAD can''t play is listed first, with a link to fix it: a message with no DAD cut or not yet recorded in DAD, something only a host can do (a live read written for the rundown, or the weather), copy that isn''t approved or is outside its dates, or a break that runs past its window.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A program that airs in automated hours but has no rundown is listed as worth knowing. Its breaks aren''t in the file until it has one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Table", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows what DAD will play and when. ", "type": "text"}, {"text": "File", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows the exact rows.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Releasing", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Traffic releases the day with ", "type": "text"}, {"text": "Release", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It''s refused while anything can''t play.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Download the release and put it in DAD''s import folder. The file is named for the day, such as 100126tWUWF.log.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If a rundown changes afterwards, the page says the release is out of date. Release again; each release is a new version, and the history keeps every one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each item keeps the same spot number in every version.", "type": "text"}]}]}]}]}', 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', '2026-11-05 23:48:39.815325+00', NULL),
	('924ced56-65a1-4ab2-a652-65a0b24c63e5', 'a7d7395f-1583-4008-b9df-b514bbbb4f65', 2, 'Partners and agreements', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Partners", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/partners"}}]}, {"text": " tab lists every UWF unit and outside organization WUWF produces for, with its contact, its agreements and its open requests. Production staff, the Director of Operations or the Executive Director add a partner with ", "type": "text"}, {"text": "+ New partner", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; a request can also name a new partner, and the public form finds or creates one by name.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Agreements", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An agreement is a standing arrangement with one partner: its dates, a ", "type": "text"}, {"text": "reserve share", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in professional hours that its work may draw before being priced incremental, the student hours the partner funds, an airtime allowance in minutes a week, the booking and release deadlines for its reserved blocks, and the framework''s notes on direct costs, blackouts, capital and work beyond the envelope.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Draft one from the partner''s page with ", "type": "text"}, {"text": "+ Agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A draft reserves nothing and prices nothing. Its page shows ", "type": "text"}, {"text": "what this agreement would draw", "type": "text", "marks": [{"type": "bold"}]}, {"text": " against the active term: the share of the reserve, what would be left for everyone else, the airtime against the envelope, and the windows its blocks would take.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Executive Director approves it with ", "type": "text"}, {"text": "Approve the agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". From then on its terms change only with the Executive Director; the notes stay editable. ", "type": "text"}, {"text": "End the agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " stops its blocks reserving windows and keeps the pricing already recorded on open requests.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once active, the page shows consumption bars — the reserve share, funded student hours and airtime drawn by requests under it — and the requests themselves. Attach the signed agreement in the aside; everyone with access can download it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Reserved blocks", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The director reserves a window on a pool for the partner with ", "type": "text"}, {"text": "Reserve a block", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", one date or the same weekday every week to a date. Each block names its booking deadline (when the partner is expected to have a request on it) and its release deadline (when, with no request, it opens to everyone).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A block past its release deadline reads as released on its own; nothing has to be done. ", "type": "text"}, {"text": "Keep", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds it past that deadline, ", "type": "text"}, {"text": "Release", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens it early, and ", "type": "text"}, {"text": "Remove", "type": "text", "marks": [{"type": "bold"}]}, {"text": " deletes one that was reserved by mistake. A booked block is freed by releasing the request''s date.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the calendar a reserved block shows with a dotted frame until it is taken; other partners cannot book that window until its release deadline.", "type": "text"}]}]}]}]}', 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', '2026-11-05 23:48:39.815325+00', NULL),
	('d34c03a1-8cba-44d4-9c57-a0c20af40da8', 'cfab6585-7f2c-4e7f-91cb-898345c0b021', 2, 'Entering a request and its estimate', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A new request is also its estimate. Open ", "type": "text"}, {"text": "Requests", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " and choose ", "type": "text"}, {"text": "+ New request", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", pick who it is for, tick the service they need and give the event date. One click on ", "type": "text"}, {"text": "Create and price the estimate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts the request, prices it and plans the dates.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What you see", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "One line at the top of the request says what it is, how much work it takes, what the partner pays, whether the calendar has room, what WUWF contributes and when the estimate expires.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The rate is named in plain words: ", "type": "text"}, {"text": "University rate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (the partner pays the full cost), ", "type": "text"}, {"text": "University rate (WUWF contributing)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (the partner pays for students and equipment and WUWF contributes the staff time) or ", "type": "text"}, {"text": "Outside rate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Show calculation", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the estimate lines, how the rate was worked out and the version of the rates it came from. Most requests never need it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The dates", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The service books itself: the date you give is checked against the calendar and the dates are planned automatically. Tentative holds are placed when you send the estimate, as before.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If the date can''t work — the studio is booked, WUWF has something on, the day is full — the request shows ", "type": "text"}, {"text": "The dates need attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the reason and the nearest dates that do work. Choose one to move the event.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Adjust scope", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the way to plan dates by hand. Once you add or remove a date yourself the system stops changing them.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Strategic work", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For a UWF unit the form asks one question: is this strategic or applied-learning work? If yes, and WUWF has time set aside for it, WUWF contributes the staff time. If the time has run out the request is priced at the university rate and flagged, and it stays recorded as strategic work. You can leave it unanswered and answer from the request later.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Warning badges", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A request that is out of the ordinary carries a warning badge in the list and on its page — a rate set by hand, a booking exception, contribution time used up, or dates that need attention. An ordinary request carries none.", "type": "text"}]}]}', 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', '2026-11-05 23:48:39.815325+00', NULL),
	('9004c057-c69e-4691-964a-b5ba41d416e6', 'd4a3c899-566c-419c-bebc-3588c5bddf53', 2, 'Asset inventory', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Under ", "type": "text"}, {"text": "Rates", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Assets", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/rates/assets"}}]}, {"text": " lists the major studio, field, live-production and post-production assets: acquisition cost and date, funding source, useful life, restrictions, maintenance burden and condition. Finance or the Director of Operations keeps it.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "+ New asset", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to add one, or an asset''s name to edit it. Filter by pool or by funding source with the chips.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Equipment funded by the Foundation, members or a restricted grant is not prepaid institutional capacity. Note the restriction on the asset, such as public-service use only.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The pool costs in the rate model stay the budget-line allocation until this inventory, with UWF Budget/Controller''s cost-recovery treatment for each asset, replaces it in a new rate model version. Nothing here changes a rate on its own.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An asset that leaves service is marked out of service, not deleted.", "type": "text"}]}]}]}]}', 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', '2026-11-05 23:48:39.815325+00', NULL),
	('be148ad7-9828-414b-ab6e-d6132eef976b', 'df0af22d-82f4-4c5b-bcbd-c10ce2b61f4d', 2, 'Underwriting hours', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auto-fill may schedule an underwriting credit in any hour unless it''s closed on this page. Open it from ", "type": "text"}, {"text": "Schedule", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": ", then ", "type": "text"}, {"text": "Underwriting", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Traffic staff can still place a credit by hand in a closed hour, and hosts can still move one; the rule reaches automation only.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Closed every week", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use ", "type": "text"}, {"text": "+ Weekly hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for the routine ones, such as 5:00 AM to 5:00 PM every day. Pick the days, the times, and the date they start.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An end time at or before the start runs past midnight. The early-morning part belongs to the day the hours started.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Programs in these hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": " column shows what''s on the air while credits are closed.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "One-time changes", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use ", "type": "text"}, {"text": "+ One-time change", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for a pledge drive or a special. Choose ", "type": "text"}, {"text": "Closed", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to close hours that are normally open, or ", "type": "text"}, {"text": "Open", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to open hours that are normally closed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A one-time change wins over the weekly hours. One-time changes can''t overlap each other.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Midnight to midnight covers whole days: a pledge week is Monday 12:00 AM until the next Monday 12:00 AM.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Week and month", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The week view draws each day''s closed hours over the programs on the air, with the automated hours shown faintly behind them. Hatched red is closed every week, dashed hatched is closed once, and dashed green is open once.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The month view shows each day''s closed hours. Pick a day to see its week.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Programs week view shades the same hours behind the programs.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Auto-fill never places a credit in a closed hour, never moves one there, and never generates a rundown for a day whose eligible breaks are all closed. Traffic''s dashboard names a line whose upcoming period falls entirely in closed hours.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A credit already placed stays where it is when the hours change.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only the program director can change these hours. Nothing is deleted: removing hours or a change takes it off the schedule.", "type": "text"}]}]}]}]}', 'release', 'Contextual hyperlink on the relevant screen name; instructions preserved', '2026-11-05 23:48:39.815325+00', NULL),
	('ac49363b-4892-4825-a7ff-ca121ef7c58b', '9b858f88-2a9a-4606-ae21-dce27544baea', 2, 'Find and filter contracts', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Contracts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": " page lists every underwriting contract, with search and filters in one row above it.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Search by underwriter name or order number.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use the chips to show all contracts, active ones, drafts, or the ones that need attention — a draft, or a contract with an open exception.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "+ New contract", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to start the setup steps for a new order.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen links preserved in the existing guide', '2026-11-05 23:48:39.862284+00', NULL),
	('e06f9361-bd42-41ab-801e-5c49a388e8a2', 'dede3696-65a8-4c61-a984-f8eb0df23ffc', 2, 'Exceptions and makegoods', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "An ", "type": "text"}, {"text": "exception", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/exceptions"}}]}, {"text": " appears the moment a host records an underwriting credit as missed or moved. There''s nothing to check for: if a credit didn''t air as scheduled, it''s on this list.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The list", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Each row is one missed credit, with its makegood beside it. The filters follow the steps of resolving a miss, and the list opens on the first one with anything in it:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Need a decision", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": no makegood yet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Waiting on the agency", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the order says the agency approves makegoods, and it hasn''t answered.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Makegood awaiting a break", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": a makegood exists; auto-fill will place it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Makegood scheduled", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": its break is chosen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Resolved", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "All", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Working an exception", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If the order needs the agency''s approval, record its answer under ", "type": "text"}, {"text": "Agency''s answer", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Nothing schedules a makegood until then.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Under ", "type": "text"}, {"text": "Makegood", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", select ", "type": "text"}, {"text": "Create a makegood", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". By default auto-fill places it, ahead of regular credits. To choose the break yourself, select ", "type": "text"}, {"text": "Pick a break now", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Under ", "type": "text"}, {"text": "Resolve", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose what happens: make it good, accept the alternate airing, waive, or close with no action. Rarer decisions are under ", "type": "text"}, {"text": "More decisions", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An exception closes itself when its last makegood airs. There''s no separate step to close it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A makegood counts toward the period the original credit missed, so it never counts as an extra unit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Waiving a credit needs an underwriting manager.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A resolved exception can be reopened from its own page.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen links preserved in the existing guide', '2026-11-05 23:48:39.862284+00', NULL),
	('6bb4c8ea-2d43-45b8-b315-11fb0e77472f', 'b9152f83-3780-468c-b97f-d03636c2805a', 2, 'The contract page', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "contract''s page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": " has three tabs.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Schedule", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each line of the order, with its progress. Switch to ", "type": "text"}, {"text": "By date", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to see every placement in air order, filtered to upcoming, aired, or not aired.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "When the order changes, select ", "type": "text"}, {"text": "Revise the schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A draft revision shows as a banner; ", "type": "text"}, {"text": "Review and activate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows exactly what it would clear before you confirm.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Flights, for orders grouped by event, are at the bottom of the tab.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Copy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The messages this contract runs, and how they rotate.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Agreement", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The signed agreement.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The traffic policy, shown as read. Select ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The contract''s affidavits.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Its revision history.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen links preserved in the existing guide', '2026-11-05 23:48:39.862284+00', NULL),
	('9a13b9a5-2e9d-4d04-8ce7-721ceb67deb8', '5c2b8a95-9fae-413e-828f-f5548a017036', 6, 'Migrate legacy agreements', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Administrators use this screen to bring agreements from the station''s legacy records into Traffic. Open it from the ", "type": "text"}, {"text": "Contracts list", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": ": ", "type": "text"}, {"text": "Migrate legacy records", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It lists every batch with how far along it is and what it needs next.", "type": "text"}, {"text": " Agreements are the first of its two tabs; active copy from RadioTraffic comes in on the second, Copy.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Start a batch", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "New batch", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", name the batch, and choose where the facts come from: ", "type": "text"}, {"text": "A spreadsheet of agreements", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (recommended) or ", "type": "text"}, {"text": "Documents only", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For a spreadsheet, choose the manifest CSV or paste its rows. Every row is checked before anything is saved. A row that can''t be read, or whose sponsor isn''t on file, is listed first. When a close name is on file, select ", "type": "text"}, {"text": "Use it", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; otherwise add the underwriter under Underwriters and load the manifest again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Load and continue", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Rows that still need a fix are left out.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The manifest needs the underwriter and the document''s file name in each row; the order number, run dates, sponsorship total, contract type, Drive file id, documentation status, and notes are optional. ", "type": "text"}, {"text": "Download a template", "type": "text", "marks": [{"type": "bold"}]}, {"text": " gives the column names.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Choose the documents", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Choose the folder of signed agreements. Each entry is matched to its file by name. Anything that didn''t match cleanly is listed under ", "type": "text"}, {"text": "Needs attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with what to do: use a close match, choose the file, pick which entry a shared file belongs to, or choose a copy under 10 MB. Files the manifest doesn''t name can be imported too, with every fact read from the document.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Import", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Import", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Three agreements are read at a time, each the same way ", "type": "text"}, {"text": "Create from the agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " reads a single order, and each takes a minute or two. Keep the page open until the run finishes, or select ", "type": "text"}, {"text": "Stop after the ones reading", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". If the reading service asks the portal to slow down, the run pauses and carries on by itself.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The manifest''s facts win over what the document says; the schedule comes from the document. Each entry becomes a draft contract, which schedules nothing until someone activates it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The batch page opens on ", "type": "text"}, {"text": "Needs a look", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": drafts where the document disagrees with the manifest, or where an instruction couldn''t be saved as a schedule line. Open a row to see each disagreement side by side, and select ", "type": "text"}, {"text": "Enter on the schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for the lines to enter by hand. ", "type": "text"}, {"text": "Ready to activate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " means nothing was flagged; the draft still needs a look before it''s activated. A failed entry shows why; fix the cause and select ", "type": "text"}, {"text": "Run again", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Running it again", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Importing again never creates a second contract for an entry that already has one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Loading a corrected manifest under the same batch name updates entries that haven''t been imported. Keep each row''s key the same.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To redo an imported entry, delete its draft contract; the entry can then be imported again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A document that has already been imported, under any entry, is not imported again.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen links preserved in the existing guide', '2026-11-05 23:48:39.862284+00', NULL);
INSERT INTO public.rc_article_versions (id, article_id, version, title, body, source, note, created_at, created_by) VALUES
	('a13cca56-223c-42b5-a4d5-2211463f41df', 'd88ff25e-ed3c-4c2a-8250-71a72f97bf81', 2, 'Migrate legacy copy', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Administrators use this screen once, to bring the station''s active underwriting copy in from RadioTraffic. Open it from the ", "type": "text"}, {"text": "Contracts list", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": " (", "type": "text"}, {"text": "Migrate legacy records", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then the ", "type": "text"}, {"text": "Copy", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab) or from the Copy library (", "type": "text"}, {"text": "Import from RadioTraffic", "type": "text", "marks": [{"type": "bold"}]}, {"text": ").", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Choose the export", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In RadioTraffic''s “Active Copy by Underwriter” workbook, use File › Save As › CSV, then choose that file. Title lines above the header row are fine. Columns are found by name: Underwriter, Copy Name, Cart, Length, Start Date, End Date and Script. Nothing is written until you import.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Most rows need nothing from you. The screen leads with the few questions it can''t answer on its own, each with a short set of choices:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "New underwriter", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": a name that isn''t on file. Add it, choose the underwriter it really is, or leave its rows out.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Which contract", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": more than one agreement covers the copy''s dates, or the copy is for a product (a Learning Minute) no agreement is for. The answer covers all of that underwriter''s copy, so a rotation is never split between contracts.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Which flight", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": event copy whose name fits more than one flight.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Changed wording", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the portal has copy with the same name and cart but different words. Where the difference is a few characters, the portal''s copy is usually the damaged one and using RadioTraffic''s wording is recommended; where the portal filled in a spot number RadioTraffic leaves blank, keeping the portal''s is. A genuinely new message is added as its own copy. The portal''s copy is only changed when you choose it.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "A recommended answer is already chosen and shown folded, with Change beside it. Rows waiting on an unanswered question stay out of the import; everything else can come in now.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How rows are matched", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An underwriter is matched by name, ignoring punctuation, apostrophes, “&” and plurals. A few names RadioTraffic spells differently, such as the FPM accounts, are matched from a fixed list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Copy already in the portal is recognised by its script, however it got there, and reused. Its dates are set to RadioTraffic''s; a missing cart is added. Nothing else about it changes.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "New copy comes in approved, with RadioTraffic''s dates. A script that asks the host to play a recorded spot is stored as recorded, at the export''s length; anything read aloud is a live read, planned at its read time. The cart number is kept as RadioTraffic''s reference.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Copy is linked to a contract only when exactly one current agreement fits its dates. App and digital agreements are never used for broadcast copy. Event copy is scoped to the flight it names. Linked copy joins that contract''s rotation; copy with no agreement stays with its underwriter and can be linked later from the contract''s Copy tab.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Placeholders (“copy holder”) and rows that aren''t underwriting copy, such as the EAS test, are left out. WUWF Day Sponsor copy comes in under its own underwriter with no contract.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Running it again", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "It is safe to run the same export again, or a newer one. Copy already here is recognised and skipped, links that exist are left alone, and a message that failed the first time is picked up. Each import is recorded in the audit log.", "type": "text"}]}]}', 'release', 'Contextual screen links preserved in the existing guide', '2026-11-05 23:48:39.862284+00', NULL),
	('265e4778-68b5-4493-948b-6ef6fdf2614c', 'ce2f9d0a-3165-4778-b835-e23160cdf3c7', 2, 'Affidavits', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Affidavits", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/affidavits"}}]}, {"text": " are one list per month, with a row for every contract that aired credits that month. A row''s button shows where it stands: ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Sign", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Signed", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with its PDF.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Each month", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open ", "type": "text"}, {"text": "Affidavits", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It opens on last month.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on one row, or ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with a count at the top to do every row still waiting. A row that fails says why, and the rest still generate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Whoever signs selects ", "type": "text"}, {"text": "Sign", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with a count at the top, then ", "type": "text"}, {"text": "Sign and open next", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on each one. Previous and Skip move through the month without signing.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Signing", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Your title on the signature line comes from your profile. Changing it while signing applies to that affidavit only. An administrator sets titles under Admin › Users.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Signing stores the PDF, and it can''t be changed afterwards. A correction is a new affidavit; the list shows the earlier version beside it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only underwriting managers can sign. Everyone else sees “Waiting for signature” and can preview the draft.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use the arrows beside the month to see earlier months. A note at the top names any earlier month that still has affidavits to generate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For an unusual period, use ", "type": "text"}, {"text": "Generate one by hand", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the bottom of the list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An affidavit lists only credits that aired.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen links preserved in the existing guide', '2026-11-05 23:48:39.862284+00', NULL),
	('7a503285-3f8a-40aa-b431-39d7570496df', '98b0468f-16ac-44e4-acd9-883a8bbc7eca', 3, 'Setup', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Setup", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/setup"}}]}, {"text": " holds the lists the rest of the tool depends on. Each card says whether it needs attention.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Inventory pools", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": what an order''s “AM Drive” or “Carpool” means in On Air programs and time windows. A pool with no mapping can''t be scheduled.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Industries", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the categories auto-fill uses to keep competing underwriters out of the same break.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Import agreements", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Import copy", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the one-time moves from RadioTraffic. Only administrators see these.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen links preserved in the existing guide', '2026-11-05 23:48:39.862284+00', NULL),
	('68673a29-f983-40f2-9e1e-288e3ee67e79', '851343c0-e37b-4848-8c1d-eaa7d603a32b', 2, 'Import a program log', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "program log", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/import"}}]}, {"text": " is the day''s schedule as the traffic system exports it, as a PDF. Importing it builds that day''s rundowns with each break and its credits already in place.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Start from Today", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Today tab, choose the day, then select ", "type": "text"}, {"text": "Import program log", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". If some programs have no rundown yet, the notice above the table links there too.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose the PDF and select ", "type": "text"}, {"text": "Preview import", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Reading the log can take a minute, and nothing is written yet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Review the plan. If the log is dated a different day than the one you started from, a notice says so: rundowns are created for the log''s date.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Check the rows that could not be placed, any new underwriters or copy, and any library scripts that will change. Then select ", "type": "text"}, {"text": "Import", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "You land on Today for the log''s date, where the new rundowns are listed.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "If a rundown already exists", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A program that already has a rundown for that date is skipped and named in the result. The import stays on its own page in that case so the reasons are easy to read, with a link back to Today.", "type": "text"}]}]}', 'release', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('7cfad888-0147-4d2b-a3b9-9a8c57857947', 'cd2b236c-6dfe-4c02-84fc-684f56e89c1d', 2, 'Curate requests', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Curators decide what happens to each request. A curator is anyone an administrator has given the Curator role on ", "type": "text"}, {"text": "Roadmap", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/roadmap"}}]}, {"text": "; administrators curate too.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Move a request", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the Roadmap. As a curator you see a board with a column for each of the six statuses.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Drag a card to the status it should have. A move the status rules don''t allow is ignored and the card returns to its column.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dropping a card on ", "type": "text"}, {"text": "Declined", "type": "text", "marks": [{"type": "bold"}]}, {"text": " asks for a reason first. The reason is shown on the request.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "You can also change a request''s status from its own page.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Everyone else sees the grouped list of decided requests, not the board.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Status changes are recorded in the audit log.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen links preserved in the existing guide', '2026-11-05 23:48:39.862284+00', NULL),
	('c79b190b-7947-414b-942f-e44e7ade0fe0', '83e38eb4-0ef2-49c2-ab72-ba6ce74e5d13', 2, 'Sending an answer to Sourcework', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "An answer worth transcribing can be handed to Sourcework directly from its ", "type": "text"}, {"text": "submission page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/audience-listening"}}]}, {"text": " — one answer at a time, or, for a query set to automatic transcription, in a batch.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Send one answer", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On a submission''s page, under an answered question, select ", "type": "text"}, {"text": "Send to transcription", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "This creates a Sourcework project from the answer''s audio and starts transcription. You stay on the submission page — it doesn''t navigate you away.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once it succeeds, the answer''s badge updates and an ", "type": "text"}, {"text": "Open in Sourcework", "type": "text", "marks": [{"type": "bold"}]}, {"text": " link appears, showing the project''s current status. Select it when you''re ready to leave for Sourcework.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Automatic queries", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "If the query''s settings have transcription set to automatic, every submitted answer is queued on its own. A banner above the Submissions list shows how many are queued, with a ", "type": "text"}, {"text": "Send queued answers", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button that sends the whole batch in one click — still a manual click, since there''s no background job runner.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sending needs both Audience Listening and Sourcework access. Without the second, the button fails with a message telling you to ask an administrator for it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only what the participant consented to carries over — never their contact details, and their name or city only if they didn''t ask to stay anonymous.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If a send fails, the button becomes ", "type": "text"}, {"text": "Retry transcription", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and the error is shown right there on the page.", "type": "text"}]}]}]}]}', 'editor', 'Contextual screen links preserved in the existing guide', '2026-11-05 23:48:39.862284+00', NULL),
	('3657ebaf-e2d2-4695-ae6c-3ca23c3386cb', '2ef34a4b-8969-4827-95df-732bc23ad88a', 4, 'Requests and estimates', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Requests", "type": "text", "marks": [{"type": "bold"}, {"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " tab lists every request for university and outside production work. A request moves through five stages — Request, Estimate, Booked, Delivered, Settled — and can be deferred, declined or withdrawn at any point before delivery. Production staff enter a request with ", "type": "text"}, {"text": "+ New request", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", naming the partner on file or a new one, what is asked for (production, airtime or both), the event dates and the contact.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How a request is priced", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Nobody picks a price. The treatment is derived from facts on the request and the estimate says why: a partner outside the university is priced ", "type": "text"}, {"text": "external", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; work recorded as strategic or applied-learning is priced ", "type": "text"}, {"text": "strategic", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when the term''s reserve covers its professional hours; everything else is ", "type": "text"}, {"text": "incremental", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Record the strategic judgment on the request''s scope (Edit in the Scope panel). ", "type": "text"}, {"text": "Change how it is priced", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lets production staff set a treatment by hand with a reason; pricing a request strategic against its derived treatment draws the reserve and is the Executive Director''s call. Every change is recorded.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Rates come from the rate card recorded for estimates on the Rates tab, and the estimate keeps the version it was first priced on. While no version is adopted every figure is provisional.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The estimate", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add a line", "type": "text", "marks": [{"type": "bold"}]}, {"text": " adds a service package (a studio half-day, a basic webcast, a field day), labor hours beyond a package, or a direct expense at cost. A package line carries the package''s hours per labor class, which is what the dates draw on.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Plan a date", "type": "text", "marks": [{"type": "bold"}]}, {"text": " adds each window the work needs — pool, date, window and the hours it takes from each class. A planned date takes nothing yet; the page runs the booking rule for every planned date and reads the result as one line, with ", "type": "text"}, {"text": "show the check", "type": "text", "marks": [{"type": "bold"}]}, {"text": " listing any date that would be refused and the nearest open windows.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Send the estimate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds every planned date tentatively for 14 days. The holds are placed all or none: a date the rule refuses stops the send and names the reason. Tentative holds count as taken for every other request.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "When the partner approves, ", "type": "text"}, {"text": "Partner approved — book it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " confirms the holds and the request is Booked. An estimate that lapses can be sent again, which re-checks its dates. ", "type": "text"}, {"text": "Mark delivered", "type": "text", "marks": [{"type": "bold"}]}, {"text": " once the work is done.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Airtime", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A request for airtime records a commitment — airings a week, length, dates, and whether it is contributed from the term''s envelope or paid. The page compares contributed commitments across requests with the envelope. The avails themselves are placed in Traffic (a message, as copy on a bonus or paid line) or On Air (a recurring feature, pinned on the clock), never here; once placed, paste the contract''s or the pin''s id so the request can show what was actually scheduled.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Under an agreement", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A partner with an approved agreement can have a request put under it from the ", "type": "text"}, {"text": "Agreement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel on the request''s page. The request is then priced against the agreement''s reserve share — strategic while the share has hours left, incremental beyond it — and the estimate says so.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use a reserved block", "type": "text", "marks": [{"type": "bold"}]}, {"text": " turns one of the agreement''s reserved windows into a date on the request, planned, held or confirmed to match where the estimate stands. Releasing that date hands the block back to the partner.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A package Finance has scoped to the agreement appears in the package list only for requests under it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Closing a request", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Close the request", "type": "text", "marks": [{"type": "bold"}]}, {"text": " defers, declines or withdraws it with a reason. Every hold is released and the stage it reached is kept. Declining an outside partner''s request for capacity can record the estimate''s margin as foregone for the term report. A closed request can be reopened; its dates must be planned again.", "type": "text"}]}]}', 'release', 'Clarified that requests include external partners as well as university units', '2026-11-05 23:48:39.862284+00', NULL),
	('d5762a06-bc88-4fe3-a383-dd74c37232dd', '377411a5-b19e-445c-81d6-4ac3f11f5a0b', 2, 'Exceptions through affidavits: overview', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "For current actions, use ", "type": "text"}, {"text": "Exceptions and makegoods", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/underwriting/underwriting-exceptions-and-makegoods"}}]}, {"text": " and ", "type": "text"}, {"text": "Affidavits", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/underwriting/underwriting-affidavits"}}]}, {"text": ". The overview below describes how those workflows connect.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "When a credit airs as anything other than scheduled, an exception is raised automatically — nobody has to go looking for it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Exceptions", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The exceptions list filters to all, open, awaiting agency approval, or resolved.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On one, review what happened, record the agency''s answer if the contract requires approval, schedule a makegood if one''s owed, then set a resolution and select ", "type": "text"}, {"text": "Save", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Waiving an exception needs a manager — anyone else''s attempt is refused.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Makegoods", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A makegood awaiting a slot is normally picked up automatically the next time auto-fill runs. To schedule one by hand, pick an open break and a message (default: next in rotation) on the makegoods list, and select ", "type": "text"}, {"text": "Schedule makegood", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Affidavits", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose the contract and a period, and select ", "type": "text"}, {"text": "Generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " again to confirm. The affidavit page previews the document, with a ", "type": "text"}, {"text": "Preview draft PDF", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button before certification.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Certifying is manager-only: fill in a title and select ", "type": "text"}, {"text": "Certify and store PDF", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". This freezes the affidavit as a signed PDF, with its checksum recorded — a correction afterward is always a new affidavit, never an edit to this one.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An affidavit lists only aired credits, in Central time, with no dollar amounts — a rep sends it to the client directly.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Re-generating for the same contract and period is fine; it produces a new, separately versioned affidavit rather than overwriting the previous one.", "type": "text"}]}]}]}]}', 'editor', 'Reclassified combined guide as overview; linked specialized guides and assigned screen contexts', '2026-11-05 23:48:39.917661+00', NULL),
	('b8a2ff10-ecb7-4d3c-9dec-f96691add448', '7db08922-d6b8-41c2-9660-ea08d69ec5ac', 3, 'Review submissions and send answers to transcription', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Every response to a ", "type": "text"}, {"text": "query", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/audience-listening"}}]}, {"text": " is a submission, made up of one answer per question it asked.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find a submission", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the query and select its ", "type": "text"}, {"text": "Submissions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab — the count in the tab label tells you how many there are.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select a participant''s name to open their submission.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review one", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The left column shows the participant''s details, their consent and attribution choices, and a note field only your staff can see.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The right column lists every question in order, each with an outcome — answered, incomplete, skipped, or not asked (a question added after this participant responded).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An answered question has an audio player, its duration and file size, and a link to download the original file.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mark reviewed", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Flag", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and ", "type": "text"}, {"text": "Reject", "type": "text", "marks": [{"type": "bold"}]}, {"text": " apply to the whole submission, at the top of the page; the same actions are also available per answer, further down.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "“Incomplete” means the upload started but never finished — the audio may not exist. The screen says so plainly rather than showing a broken player.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If a question''s wording has changed since this answer was recorded, the answer shows the wording as it was asked, alongside how it reads today.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each answer has its own note field, separate from the submission-level one.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('ee90df43-ec93-47c7-9df0-ba42ca51d480', 'b94314f4-e29d-42ea-a494-82f10d6b6d3c', 5, 'Creating and publishing a query', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "query", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/audience-listening"}}]}, {"text": " is a public listening initiative: up to five ordered questions, published as its own page or embedded in a Grove article, with the answers coming back to you here.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Create a query", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "From the query list, select ", "type": "text"}, {"text": "New query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fill in an internal title (for your own list), a public title (what a listener sees), and a public introduction saying why you''re asking and what you''ll do with the answers. Select ", "type": "text"}, {"text": "Create query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "You land on the new query''s Questions tab.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add questions", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fill in a question''s prompt, and optionally public guidance, internal context (staff-only), a maximum answer length, and whether it''s required.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Add question", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Repeat for up to five questions.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Reorder or duplicate a question with the buttons on its card, or remove one — before anyone has answered.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Configure settings", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Settings tab covers everything about how the query behaves, separate from its questions:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Participant information", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — which details (name, city, email, phone, a free-text note) to ask for, each set to don''t ask, optional, or required. Asked once for the whole submission, never per question.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Consent and attribution", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — three separate questions that stay separate on the record: permission to be contacted, permission to be named, and the option to request anonymity. Permission to be contacted is not permission to be named, and asking for anonymity is neither. The consent terms text itself is required and is recorded with the submission at the moment it''s accepted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Opens and closes dates", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — both optional; leaving them blank means the query opens as soon as you select ", "type": "text"}, {"text": "Open for responses", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and stays open until you close it. Someone already recording when a close date passes may still finish and submit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Transcription", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — manual (send answers after reviewing them) or automatic (every answer is queued the moment it''s submitted, then sent in one click from the Submissions tab).", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Publish it", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the query''s header — visible from any tab — select ", "type": "text"}, {"text": "Open for responses", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Until then, the public link and embed code don''t work, even for someone who already has them.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Go to the Share tab for a ", "type": "text"}, {"text": "Copy link", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button for the standalone public page, and a ", "type": "text"}, {"text": "Copy embed code", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button for a ready-made Grove iframe snippet — paste it into a Grove Responsive Embed element unchanged. If you add or remove questions later, copy the embed code again.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Preview", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (always available, even on a draft) to walk through the query as a participant would — nothing is submitted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once a query has submissions, question wording stays editable, but removing or reordering questions is no longer offered — an answer keeps the exact wording it was asked under.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The header''s action changes with status: open queries offer ", "type": "text"}, {"text": "Close query", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (stops new responses; anyone already recording can still finish); closed ones offer ", "type": "text"}, {"text": "Open for responses", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Archive query", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A query can be deleted only before it has any submissions, from the Settings tab. Once a submission exists, archiving — which keeps every response, answer, and transcription link — is how you finish with it.", "type": "text"}]}]}]}]}', 'editor', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('d1c3af80-fca2-40cc-89c4-a48261033c54', '31505a5e-0ba7-4416-a364-bcb3ec5082d2', 2, 'Adjusting what a package includes', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A package is the usual recipe for a kind of work. When one ", "type": "text"}, {"text": "request", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " needs something different, use ", "type": "text"}, {"text": "Adjust scope", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on that line: change the hours, equipment or crew and say why. The package and the rate model are not changed, the request keeps a reference to the standard recipe and shows the difference, and the request carries a Scope adjusted badge.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An adjusted line is priced from its own cost. The package''s market floor and ceiling are scaled by the same change in cost, which is a judgment Finance should confirm. Reset the line to go back to the standard recipe.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hours used", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "After the work is delivered, confirm the hours and equipment actually used. They feed the assumed-versus-observed view in the Term report and never change a price.", "type": "text"}]}]}', 'release', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('31d71119-448c-46d6-bc8d-1c78c40df685', '2b4086e5-4953-4a48-a7e5-1422512e2eb6', 2, 'Settling a delivered request', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Once a ", "type": "text"}, {"text": "request", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " is delivered and production has confirmed the hours and equipment used, Finance settles it. The ", "type": "text"}, {"text": "Settlement", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel on the request drafts itself: the amount is the approved estimate''s, with each direct expense replaced by what it actually cost, and the cost to WUWF is the confirmed hours and equipment at the rate card the request was priced on. The hours never change what the partner is charged; they change what the work cost WUWF.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A university unit is recharged to its funding index. An outside partner is invoiced, with the assessment and margin shown on their own lines.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Type the actual cost of any direct expense, or leave it blank to settle it as estimated. Update the draft to recalculate from the hours confirmed now.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Post the entry in the university''s own system, then enter its journal entry number here and post the settlement. Posting settles the request, and a posted settlement is final.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "WUWF contributes the cost the partner''s payment does not cover, never less than zero. The Term report totals settled requests so actual cost can be read against the estimates.", "type": "text"}]}]}', 'release', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('90efd98e-f8a9-4a24-a226-c6a99515c2b6', 'c429d78e-e9fc-4ea3-98a7-d20f20de727a', 3, 'Station IDs', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The station identifies itself every hour, as close to the top of the hour as it can, at a natural break. The legal ID is pinned on each ", "type": "text"}, {"text": "clock''s page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": ", the same way as any other pinned content, and goes into every rundown made from that clock.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Pin the station ID", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the program, then ", "type": "text"}, {"text": "Open clock", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select the slot that takes the legal ID, usually the last break before the top of the hour.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Pin content", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and choose the station ID. Leave the hour on ", "type": "text"}, {"text": "Every hour", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and no days checked, then select ", "type": "text"}, {"text": "Pin content", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If an hour on the clock in effect has no legal ID, a warning at the top of the clock''s page says which.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If no slot takes a legal ID yet, the warning says so. The program director marks the slot eligible for a legal ID first.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A new clock version starts without pins, so pin the ID again on the new version.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A pinned ID goes into rundowns made from then on. Rundowns already made keep what they have.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The program director or traffic can pin and remove the ID.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('dc099bcc-0cd8-45e5-8f40-ba95610f70cc', 'c4235d24-a58d-4771-9581-f7c0d3cc5523', 2, 'The public request form', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A university unit or an outside organization asks WUWF for production work or airtime at ", "type": "text"}, {"text": "tools.wuwf.org/book", "type": "text", "marks": [{"type": "code"}, {"type": "link", "attrs": {"href": "https://tools.wuwf.org/book"}}]}, {"text": ", or through the same form embedded in a Grove page. No sign-in is needed and no rate appears on the form. Each submission lands on the Requests tab at the Request stage, marked as received from the public form, with the submitter''s unit named as the partner (an existing partner by the same name is reused) and the submitter as the contact.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What the form asks", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Who is asking: a name, an email, a phone, the college, department, office or organization, and whether it is part of UWF.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "What is needed: production, airtime or both; a short title; for production, which of the offered services (recorded on the request as ", "type": "text"}, {"text": "Services asked for", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — production staff add the real estimate lines); a description.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "When and where: the event or recording dates, when the finished work is needed, and a location. The form books nothing; dates are checked and held when the estimate is sent.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For airtime: airings a week, the length of each, and the first and last airing. When all three are given the request carries an airtime commitment, contributed by default, for staff to review against the term''s envelope.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Settings", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "From Requests, ", "type": "text"}, {"text": "Public form", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the form''s settings. The Director of Operations or the Executive Director decides whether the form is taking requests, edits the introduction, the confirmation shown after a request is sent and the copy shown while the form is closed, and lists the services the form offers, one a line. Everyone with access can read the settings and copy the public link or the Grove embed code; the preview beneath them shows the form as it is served.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A visitor may send at most three requests a day from one email address, and a form that was filled in faster than a person could is refused.", "type": "text"}]}]}', 'release', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('feff0027-f6eb-4008-80c7-8aeb07bbb6c5', '08e43f22-c4be-4db0-945b-f76ebcc560da', 5, 'Automation', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Every hour is hosted unless it''s listed on ", "type": "text"}, {"text": "this page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/automated-hours"}}]}, {"text": ". In automated hours no one is in the studio, so DAD plays that hour''s underwriting credits. Open it from ", "type": "text"}, {"text": "Schedule", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Automation", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Weekly hours", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use ", "type": "text"}, {"text": "+ Weekly hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for the routine ones, such as overnights from 8:00 PM to 5:00 AM. Pick the days, the times, and the date they start.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An end time at or before the start runs past midnight. The early-morning part belongs to the day the hours started, so Saturday 8:00 PM – 5:00 AM covers early Sunday.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Weekly hours can cover a whole program or just some of its hours. The ", "type": "text"}, {"text": "Programs in these hours", "type": "text", "marks": [{"type": "bold"}]}, {"text": " column shows what''s on the air then.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "One-time changes", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use ", "type": "text"}, {"text": "+ One-time change", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for a holiday, a host out, or a special. Choose ", "type": "text"}, {"text": "Automated", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to automate hours that are normally hosted, or ", "type": "text"}, {"text": "Live", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to host hours that are normally automated.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A one-time change wins over the weekly hours. One-time changes can''t overlap each other.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Midnight to midnight covers whole days: Thanksgiving is Thursday 12:00 AM until Friday 12:00 AM.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Week and month", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The week view draws each day''s automated hours over the programs on the air, with the hours closed to underwriting shown faintly behind them. Grey is weekly, dashed amber is automated once, and dashed blue is live once.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The month view shows each day''s automated hours. Pick a day to see its week.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A credit in automated hours needs copy with a DAD cut, since DAD plays it. A live read qualifies through its recorded version. Auto-fill leaves those breaks to copy that has one, and placing cut-less copy there is refused.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only the program director can change automated hours. Nothing is deleted: removing hours or a change takes it off the schedule.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('dd6e3ff2-660a-47bf-8a78-89da119c84a1', '5ed0ee31-d996-40e4-ab6a-d941f118ea26', 4, 'Copy, rotation, and placing a credit', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A credit needs approved ", "type": "text"}, {"text": "copy", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/copy"}}]}, {"text": " behind it before it can run anywhere.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Copy", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the contract''s Copy tab, select ", "type": "text"}, {"text": "+ New message", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Link existing…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to attach a script. A draft message can be approved right from its card — only approved copy rotates or gets placed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Copy shared across more than one contract shows which others use it, right on its edit card.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Rotation", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Rotation is automatic: each contract cycles through its own linked messages in broadcast order, with nothing for staff to pick. An aired, frozen, or manager-overridden placement is a fixed point that rotation won''t move.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Rotation weights", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "By default every message on a contract airs equally often. When an order asks for one message to air more than another, open ", "type": "text"}, {"text": "Rotation weight…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from the message''s menu and set a whole number from 1 to 20.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Messages rotate in proportion to their weights: a weight of 2 against 1 airs the first twice as often, spread through the run rather than in a block.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Weights compare messages that rotate together: the contract''s general messages, or the messages dedicated to one line. Only approved messages count.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The card reads ", "type": "text"}, {"text": "airs 2 of every 3 spots", "type": "text", "marks": [{"type": "bold"}]}, {"text": " once the weights differ. Aired credits count toward the ratio, and changing a weight re-sequences only credits that have not aired.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A weight belongs to the message on this contract; the same message on another order keeps its own.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "A message for one line", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Some orders give a message to one line rather than to the whole contract — for example, “For Carpool: #1” and “For Total Program: #2”. When linking the message, choose the line under ", "type": "text"}, {"text": "Use on", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or use ", "type": "text"}, {"text": "Use on one line only…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from a linked message''s menu.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A message dedicated to a line airs only on that line.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "That line then airs only its own messages. If it has more than one, they rotate among themselves.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Every other line keeps rotating the contract''s other messages, as before.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If a revision replaces the line, the message''s card shows ", "type": "text"}, {"text": "Line replaced — set it again", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; choose the new line.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Placing a credit", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Manually, from a schedule line''s ", "type": "text"}, {"text": "Place a credit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " link: pick an open break (grouped by period), confirm or change the suggested message (already the next one in rotation), and select ", "type": "text"}, {"text": "Place credit", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Only messages that may air on that line are offered.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Or let auto-fill do it: ", "type": "text"}, {"text": "Auto-fill this line", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from a line''s own menu, ", "type": "text"}, {"text": "Auto-fill this contract", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for every line on one contract, or ", "type": "text"}, {"text": "Auto-fill everything", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for every active contract — the same placement path either way, just run in a loop.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A same-underwriter or same-industry adjacency warning is advisory on the manual placement form — it''s shown, never blocked.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Auto-fill generates the rundowns it needs as it goes, so a fresh contract can be filled for its whole campaign in one click even before a rundown for those dates exists yet.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('deaa8e79-810c-4c86-87b6-732ac7180449', '36f137cd-09ae-4085-9b57-c79d48ab87aa', 3, 'Copy in DAD', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Every ", "type": "text"}, {"text": "message", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/copy"}}]}, {"text": " on file has a DAD cut: the number DAD plays it from. A recorded spot plays its recording. A live read is read by the host when someone is on air, and DAD plays its recorded version in hours with no host.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "New recording", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A new message gets the next free cut when you save it, in the form ", "type": "text"}, {"text": "00548A", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Record the message into DAD under that number.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Messages that were on file before cuts existed kept their old number where only one current message used it, so Loyalty Credit Union''s copy 1 is ", "type": "text"}, {"text": "00013A", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To use another number, choose ", "type": "text"}, {"text": "Use a different cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the copy''s edit page. A cut belongs to one message, so a number already in use is refused.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Recorded in DAD", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A new cut isn''t in DAD until someone records the message under it. The copy page shows ", "type": "text"}, {"text": "To record", "type": "text", "marks": [{"type": "bold"}]}, {"text": " until production marks it with ", "type": "text"}, {"text": "Mark recorded", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "To record", "type": "text", "marks": [{"type": "bold"}]}, {"text": " filter in the copy library, and the dashboard''s ", "type": "text"}, {"text": "To record in DAD", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tile, list every message that can still air and isn''t recorded. Production can mark each one from that list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Changing a message''s cut, or the wording of a message under a new cut, clears the mark, since the recording no longer matches.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A message that plays an existing DAD spot is already recorded.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The DAD log can''t be released while a credit in automated hours isn''t recorded.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Existing DAD spot", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Some copy asks the host to play a spot that''s already in DAD, such as a Learning Minute in the PPA group. Choose ", "type": "text"}, {"text": "Existing DAD spot", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and search DAD''s library by cut number or title.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Copy like this starts without a cut. It shows ", "type": "text"}, {"text": "Pick a DAD spot", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the copy library, and the ", "type": "text"}, {"text": "Needs a DAD cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " filter lists every message still waiting.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The copy page''s ", "type": "text"}, {"text": "Copy", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button puts the cut on the clipboard for pasting into DAD.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the rundown, a recorded spot shows the cut the host fires. A live read shows no cut.", "type": "text"}]}]}]}]}', 'release', 'Contextual screen link in existing instructions', '2026-11-05 23:48:39.951425+00', NULL),
	('0c4d459e-a250-406c-ad9c-032f1cd88249', '2d242660-9e07-4b75-bf46-19df9022989b', 4, 'Bookings: from request to settlement', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Bookings helps WUWF evaluate a production request before accepting it: what the work requires, whether the station has capacity, and what the partner should pay. It then records delivery and actual cost. The ", "type": "text"}, {"text": "Requests screen", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/requests"}}]}, {"text": " is the starting point for an individual job.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Cost and capacity are separate decisions", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "rate card", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/rates/card"}}]}, {"text": " prices a defined scope of work using labor, equipment and other costs. University strategic or applied-learning work can receive a contribution of professional staff time where an eligible reserve is available; other university work and outside work receive their applicable rates. Being eligible for a contributed rate does not guarantee an available production window.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Calendar", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/calendar"}}]}, {"text": " accounts for labor, bookable resource pools, WUWF holds, reserved blocks and term capacity. Core obligations already excluded from available hours must not be counted again as holds. The airtime envelope shown in Bookings is a planning measure; actual announcements are placed in On Air or Traffic.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "From commitment to actuals", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A request combines an estimate, feasibility checks and planned dates. A tentative hold is not final approval. Where a partner has an agreement, review it under ", "type": "text"}, {"text": "Partners", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/partners"}}]}, {"text": " and confirm whether the requested work and any reserved blocks fall within its terms. After delivery, production confirms resources used; Finance posts the settlement. Actual effort affects WUWF''s measured cost, but does not automatically change the amount quoted to the partner.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Use the ", "type": "text"}, {"text": "Term report", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/bookings/report"}}]}, {"text": " to compare estimated work with settled results and inform future rate and capacity decisions. For specific buttons, stages and permissions, follow the detailed guides attached to each screen.", "type": "text"}]}]}', 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', '2026-11-05 23:48:40.000183+00', NULL),
	('b2c87d84-606b-488d-ba56-044eceef81a7', '11c15dd3-b605-4109-baef-9bd6aaf12c53', 4, 'Traffic: from signed order to fulfillment', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Traffic turns a signed underwriting order into an accountable broadcast obligation. Start with ", "type": "text"}, {"text": "Contracts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/contracts"}}]}, {"text": ": identify the sponsor, dates, flights, placement quantities and any restrictions before activating an order.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "An eligible slot is not an obligation fulfilled", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A contract may require a specified number of credits per week, on exact dates or within particular programs or inventory pools. Eligibility describes where a credit could air; demand describes what the signed order requires. Reconcile both when setting up the schedule. The ", "type": "text"}, {"text": "Traffic dashboard", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting"}}]}, {"text": " surfaces work needing attention.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A credit also needs approved, eligible copy. The ", "type": "text"}, {"text": "Copy library", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/copy"}}]}, {"text": " manages scripts and DAD cut references. Approval allows copy to be scheduled; a correct, recorded DAD cut is additionally necessary for unattended playback. Rotation weights determine how approved messages are distributed, but must respect line-specific copy restrictions.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Scheduled is not the same as aired", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Check fulfillment against broadcast evidence, not just the number of placed credits. Handle misses and preemptions under ", "type": "text"}, {"text": "Exceptions", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/exceptions"}}]}, {"text": ", observing any agency-approval requirement for makegoods. Prepare ", "type": "text"}, {"text": "Affidavits", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/underwriting/affidavits"}}]}, {"text": " from reconciled activity. For automation exports, use On Air''s ", "type": "text"}, {"text": "DAD log", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/dad-log"}}]}, {"text": "; releasing a file does not itself confirm import or playout.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Payment processing is separate from scheduling. For an approved card charge, use the station procedure ", "type": "text"}, {"text": "Process an underwriter card payment", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/procedures/process-an-underwriter-card-payment"}}]}, {"text": ".", "type": "text"}]}]}', 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', '2026-11-05 23:48:40.000183+00', NULL),
	('b78390cc-d8d8-4e71-9ce2-166326ba80aa', '8f7b79d0-d1af-4182-8585-29db621ed754', 4, 'On Air: producing, hosting and automation', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "On Air connects the station''s program schedule and clocks with daily rundowns, locally produced content and automation exports. A host begins on ", "type": "text"}, {"text": "Today", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log"}}]}, {"text": "; a producer also maintains reusable scripts and metadata in the ", "type": "text"}, {"text": "Content library", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/library"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "One schedule, different responsibilities", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The program clock defines the available breaks and fixed elements. ", "type": "text"}, {"text": "Programs", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": " determines what airs when; ", "type": "text"}, {"text": "Sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/sources"}}]}, {"text": " shows imported NPR and weather information that should be checked for freshness before use. Producers review a rundown''s timing and required content; hosts execute it and report deviations.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Operations defines unattended periods under ", "type": "text"}, {"text": "Automation", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/automated-hours"}}]}, {"text": " and controls which periods can accept underwriting under ", "type": "text"}, {"text": "Underwriting hours", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/underwriting-hours"}}]}, {"text": ". Those settings are related but not interchangeable: an unattended hour is not necessarily open to credits.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Export, import and broadcast are distinct", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Traffic reviews and releases the ", "type": "text"}, {"text": "DAD log", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/dad-log"}}]}, {"text": " for unattended hours after resolving missing or unrecorded cuts, ineligible copy and timing blockers. The export must then be imported into DAD, and actual playout checked through the station''s operational process. A change after release may require a new version.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "For equipment or transmission failure, do not improvise a recovery procedure from the scheduling tool. Use ", "type": "text"}, {"text": "Restart broadcast systems after a total power failure", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/procedures/restart-after-a-total-power-failure"}}]}, {"text": " or the applicable Operations and Technology SOP.", "type": "text"}]}]}', 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', '2026-11-05 23:48:40.000183+00', NULL);
INSERT INTO public.rc_article_versions (id, article_id, version, title, body, source, note, created_at, created_by) VALUES
	('3d97f54b-2406-4fe5-bab2-126a034b030d', 'af63e5a9-2f22-46d6-b9d5-39d39a786282', 4, 'Audience Listening: from questions to reporting', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Audience Listening collects people''s experiences and questions to inform reporting. Start in ", "type": "text"}, {"text": "Queries", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/audience-listening"}}]}, {"text": " with a specific editorial uncertainty, and ask open-ended questions that do not assume an answer.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Participation and permission are not interchangeable", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Before publication, review the query''s participant-information settings, consent language and attribution choices. Permission to contact someone is not the same as permission to name them; requests for anonymity must be handled according to the submitted record. Preview the participant experience before opening responses.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Treat responses as reporting leads", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Listen to submissions, consider whether a response merits follow-up, and send relevant audio into Sourcework using the supported handoff. Preserve the original question and consent context when further reporting begins.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An open-response listening query is not a representative poll. Recurring accounts can identify reporting questions, but response counts alone do not establish how common an experience is in the broader population. Corroborate consequential claims before publication.", "type": "text"}]}]}', 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', '2026-11-05 23:48:40.000183+00', NULL),
	('87dea85a-2698-46d5-adec-4786e3a19612', '758d8487-bc47-4c93-b81c-8eb526381d5e', 4, 'Roadmap: requests and decisions', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Roadmap board", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/roadmap"}}]}, {"text": " gathers product problems and proposed improvements. A useful request identifies who is affected, what happens today, why it matters, and what a successful change would make possible. Start from ", "type": "text"}, {"text": "New request", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/roadmap/new"}}]}, {"text": " when an existing item does not already capture the need.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "A request is not a delivery commitment", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Curators clarify and group requests, consider priority and feasibility, and move them through the board''s documented statuses. Comments should add evidence, reproduce a problem or describe a distinct use case rather than simply restate support.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "When a change is delivered, connect its release note and updated tool guide to the original request. Users should rely on the current board status and release documentation—not infer a ship date from an idea appearing on the roadmap.", "type": "text"}]}]}', 'release', 'Reconciled role-oriented overview; removed duplicate click-by-click instructions', '2026-11-05 23:48:40.000183+00', NULL),
	('809eb072-2115-4cd2-8352-08eeb581771f', '190e6cee-2d44-49ae-bc4b-2a39062598fd', 5, 'The rate model', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Rates", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab holds the production rate model: what each class of labor costs an hour, what a studio half-day, an event webcast, a field day or an editing hour costs WUWF, and the rates on the card a partner sees. Everything on the card is computed from the figures; nothing is typed in by hand.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Finding your way", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Rate card", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is where Rates opens: the rates a partner sees, computed from the figures.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Inputs", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a checklist of the four pages that feed the card — Assumptions, Labor, Resource pools and Service packages — with how many of each are validated. Select a row to open its page; ", "type": "text"}, {"text": "← Inputs", "type": "text", "marks": [{"type": "bold"}]}, {"text": " returns to the list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the change log. ", "type": "text"}, {"text": "Assets", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the equipment inventory.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Classes and pools", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Manage labor classes", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the Labor page, and ", "type": "text"}, {"text": "Manage resource pools", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the Resource pools page, list the two things the model is built from. A ", "type": "text"}, {"text": "labor class", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a kind of production staff — the production lead, student and OPS crew, later a second producer or an engineer — paid by salary or by the hour, and either charged in a strategic price (students) or baseline-funded (professionals).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "pool", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is something that can be booked — studio, field package, live package, edit suite, webcast operations — with its unit and how it is costed: a share of the shared production pool, or its own budget lines. Finance or the Director of Operations adds a class or a pool here; nothing is deleted, only retired.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A new class needs its pay figures on each draft version (the ", "type": "text"}, {"text": "Labor", "type": "text", "marks": [{"type": "bold"}]}, {"text": " page), and a new pool its figures on each draft version (the ", "type": "text"}, {"text": "Resource pools", "type": "text", "marks": [{"type": "bold"}]}, {"text": " page) and a resource on the term plan.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Versions", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The version picker at the top switches between versions. One version is ", "type": "text"}, {"text": "in use", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for estimates at a time. A version that has not been adopted is labelled provisional, and so is every figure from it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An adopted version never changes. To correct it, Finance selects ", "type": "text"}, {"text": "New version", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", which copies the chosen version''s figures and packages into a draft.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Assumptions, labor and resource pools", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Assumptions", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds the budget lines — the shared production pool''s, and the webcasting pool''s own — and the two working inputs the math reads directly: the external margin and the university assessment.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Labor", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds each class''s pay figures on this version: salary and paid hours or hourly wage, the fringe or payroll load, and the external planning rate. The loaded hourly cost is recomputed from them.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Resource pools", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds each pool''s share of the shared pool (or its own lines) and its available units a year. Cost per unit is the pool''s annual cost divided by its units.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Every row names who must validate it and what that takes. Finance selects ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change a figure on a draft, and ", "type": "text"}, {"text": "Validated", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Accept as is", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to resolve it. ", "type": "text"}, {"text": "What moves the price most", "type": "text", "marks": [{"type": "bold"}]}, {"text": " re-runs the model with one figure moved.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Service packages and the rate card", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "service package", "type": "text", "marks": [{"type": "bold"}]}, {"text": " states its hours per labor class and its units per pool, plus the external market floor. Strategic cost is resource units plus the hours of every class charged in a strategic price; incremental cost adds the other classes'' hours at their loaded rate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Every rate rounds up to the next $25. The external rate is the higher of the incremental cost grossed up for the margin and the assessment, and the package''s market floor. The card lists one labor line per class.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Record for estimates", "type": "text", "marks": [{"type": "bold"}]}, {"text": " saves the card as computed, so an estimate priced later keeps the rate it was priced at. ", "type": "text"}, {"text": "Print", "type": "text", "marks": [{"type": "bold"}]}, {"text": " prints the card alone.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Adopting a version", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Finance resolves every assumption, labor figure and pool, then selects ", "type": "text"}, {"text": "Submit for validation", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A version with anything still pending cannot be submitted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Executive Director selects ", "type": "text"}, {"text": "Adopt", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", recording the Budget/Controller''s destination index for recoveries. The previous adopted version is superseded, and the new one is in use.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists who changed what on each version.", "type": "text"}]}]}', 'release', 'Assets is a page in the Rates row', '2026-11-05 23:48:40.080207+00', NULL),
	('750848c4-d067-414c-b2e8-0fbaafedd5c7', '05a46041-4eda-40a8-8176-26e1c77d2cd0', 6, 'The dashboard', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The dashboard opens on what needs attention, in three groups. Every number links to the list it counts, filtered the same way.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Missed credits", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Need a decision", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": an exception with no makegood yet, or one the agency declined.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Waiting on the agency", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the order''s makegoods need the agency''s approval, and no answer is recorded yet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Makegoods awaiting a break", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the next auto-fill places these first.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Scheduling", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Units not yet scheduled", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": open periods on active contracts that auto-fill hasn''t reached yet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Capacity conflicts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": lines that can''t be placed in the next 14 days, listed below with what''s blocking each one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To record in DAD", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": messages under a new DAD cut that production hasn''t marked recorded yet.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Affidavits", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To generate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": contracts with aired credits not yet covered by an affidavit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Awaiting your signature", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": generated affidavits ready to sign. Only underwriting managers see this one.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Auto-fill everything", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the right-hand column to fill every active contract''s open periods, makegoods first.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If you can open On Air, ", "type": "text"}, {"text": "Log of record", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the right-hand column shows whether the DAD log is released for today and the next two days.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Finding your way", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Traffic has five tabs, one for each kind of job:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dashboard", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is this page.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Contracts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is every agreement, and where schedules, copy and placements are worked.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Needs attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds Exceptions and Affidavits. The number beside the tab counts exceptions waiting on a decision, plus affidavits waiting for a signature if you are an underwriting manager, and disappears when there are none. Choose Exceptions or Affidavits in the grey row beneath the tabs.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Library", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds Underwriters and Copy.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sits at the right edge: inventory pools, industries and the migration of legacy records.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The grey row beneath a tab lists that tab''s pages. The page you are on has a grey background.", "type": "text"}]}]}', 'release', 'Added how the five tabs are organised', '2026-11-05 23:48:40.080207+00', NULL),
	('2d121480-750a-4eac-a81a-2344fd0d9a61', 'd359da41-2d8d-4ac8-9280-b9d9a0e8d4da', 2, 'Changing a program''s clock for a few days', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Use a one-time change when a program needs a different clock for a set of dates, for example FPREN Phase I storm coverage. The normal weekly schedule stays as it is, and the one-time change replaces it on the dates you choose.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add the change", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the program from ", "type": "text"}, {"text": "Programs", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/programs"}}]}, {"text": ", then select ", "type": "text"}, {"text": "+ Add a time", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Set the entry type to ", "type": "text"}, {"text": "One-time change", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose the clock, and give the start and end dates, the air time and the length. A one-time change covers every day between its dates.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Save. On those dates, Today, the week view and any new rundown use this clock instead of the normal one.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Switch rundowns that already exist", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Traffic can build rundowns weeks ahead, so some of those dates may already have a rundown on the old clock. When that is so, the program page shows a notice that lists the dates, with a ", "type": "text"}, {"text": "Switch", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Switching keeps each old rundown as a record and builds a new one on the clock now in force. The old rundown is marked as replaced and can''t be started, edited or submitted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only a rundown that hasn''t started and has nothing recorded on it is switched. One that is on air, or has recorded outcomes, is left as it is.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Rundowns built from an imported program log are switched the same way as the others. Where the rundown came from doesn''t matter, only whether it has started or has anything recorded on it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What happens to underwriting", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Any underwriting credit already placed on a replaced rundown is recorded as missed, with the reason Special coverage. Each one appears in Traffic''s exception list, where staff decide on a makegood or a waiver. Nothing is placed again automatically, and nothing is counted as aired. Credits that came from an imported log have no Traffic placement behind them, so they can''t raise an exception. The notice after switching tells you how many there were. They stay on the old rundown, and you add them to the new one if they still apply.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "DAD", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "If a date already has a released DAD log, the notice after switching names the date. The DAD log screen also marks that release as out of date. Traffic needs to release a new version, because DAD plays what was released.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Going back", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "To end a change early, shorten its end date or remove the entry, then select ", "type": "text"}, {"text": "Switch", "type": "text", "marks": [{"type": "bold"}]}, {"text": " again on the program page. Exceptions that were already raised stay open for Traffic to resolve.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On Today, a program with a one-time change shows one row, labelled One-time change, not two.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Holiday is no longer an entry type. A holiday that needs a different clock is a one-time change; one that is only automated is set under Automation.", "type": "text"}]}]}]}]}', 'release', 'Imported rundowns can be switched; notices for unplaced credits and released DAD logs', '2026-11-05 23:48:40.336319+00', NULL),
	('e48d9797-e030-441d-8a3f-655d6bc20ec4', 'fe78fd65-3b6d-4836-9358-678c36977395', 8, 'Building a piece from narration and excerpts', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A piece is a reader, voicer, wrap, spot or feature you build from your own narration and the project''s excerpts. It starts blank. You can write it block by block, or let AI outline it from your accepted findings, write the outline out as narration, and then edit it by hand or with the assistant.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Start a piece", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open a project, select ", "type": "text"}, {"text": "Pieces", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "+ New piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The editor opens at once on an empty piece with its title ready to type, and a ", "type": "text"}, {"text": "Start your piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": " panel offers ", "type": "text"}, {"text": "+ Narration", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "+ Excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Outline with AI", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The Pieces list shows each piece''s length, how it was made and when it last changed, with a search box once there are pieces.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A format sets the piece''s target length and gives you a guide to write by. Choose one, or change it, any time from ", "type": "text"}, {"text": "Format", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under the length at the top of the piece, and ", "type": "text"}, {"text": "Show guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows its description. The guide is a reminder of what the format usually asks for; it doesn''t stop you doing something else. Choosing a format doesn''t change what you''ve written.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The formats are Reader / Voicer (about 0:30 to 0:45, no recorded excerpts), Cut and Copy (0:45, one excerpt), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). The excerpt counts are a usual range, not a requirement: a strong piece can use fewer.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Outline and write it out (optional)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On an empty piece, choose ", "type": "text"}, {"text": "Outline with AI", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It plans the story as beats, with your excerpts placed where they belong, from the findings you have accepted. A piece with beats shows ", "type": "text"}, {"text": "Write from outline", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", which turns each beat into narration in place. Both are versions you can undo, and nothing is written until you ask. ", "type": "text"}, {"text": "Outline a piece", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-outline"}}]}, {"text": " has the details.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add narration and excerpts", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Narration", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Write in a narration block. Press Enter at the end of a block to add another below it, and Shift+Enter for a new line. Backspace in an empty block removes it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Between every block, and before the first and after the last, there is a + row. Select it and choose ", "type": "text"}, {"text": "Excerpt from this project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to search the project''s audio excerpts by title, words, speaker or source. Arrow keys move through the results and Enter adds one. The same row adds a narration block or an outline beat.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An excerpt''s words always come from the transcript for the clip you hear. They cannot be retyped in the piece.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a block", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select the ⋮ beside a block for ", "type": "text"}, {"text": "Move up", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Move down", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Mark as anchor intro", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (on narration), ", "type": "text"}, {"text": "Swap excerpt…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Trim…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and removal. On a desktop you can also drag the ⋮⋮ handle to reorder.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An ", "type": "text"}, {"text": "anchor intro", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the lead-in the anchor reads before a reporter''s recorded piece. It is shown as its own block and isn''t counted in the piece''s length, so a 0:53 wrap stays 0:53 whatever the intro adds. Reader, voicer and cut and copy copy is part of the piece and is timed with it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Trim a clip in place", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Choose ", "type": "text"}, {"text": "Trim…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on an excerpt block. The clip''s words appear in their transcript context. Tap a word to move the nearer end of the clip there, or nudge the start and end with the −250, −50, +50 and +250 buttons. ", "type": "text"}, {"text": "Play as cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays what you have. The same panel shortens long pauses; see ", "type": "text"}, {"text": "Trim a clip and shorten its pauses", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-piece-trim-and-pauses"}}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "By default a trim belongs to this piece only and the excerpt itself is unchanged. Choose ", "type": "text"}, {"text": "Update the excerpt everywhere", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change the excerpt itself; the panel says how many other pieces use it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Length", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The length at the top adds up narration, estimated at 160 words a minute, and the clips'' own running time, without any anchor intro. Choosing a format sets a target; select ", "type": "text"}, {"text": "Change target", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to use a different one. The piece shows how far under or over it is.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Ask the assistant", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open the assistant from ", "type": "text"}, {"text": "Assistant", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the top of the piece (on a phone, the bar at the bottom). It knows which piece you have open and says so at the top: “Working in: …”. Ask it to tighten a passage, move a quote, trim a clip, add a line, or outline the piece again. Anything you have typed is saved before your message goes.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "It changes only what you ask, and says what it changed. Its reply lists the tools it used.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "It places and swaps excerpts by id. It can''t change what a speaker said, and the lengths it reports come from the same arithmetic as the screen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each block it changed is marked ", "type": "text"}, {"text": "Edited by the assistant", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Added by the assistant", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". ", "type": "text"}, {"text": "Undo", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the mark puts that block back. The marks stay until you next edit the piece yourself.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "From a + row, ", "type": "text"}, {"text": "Ask the assistant to write it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the assistant with a request for narration at that spot, for you to finish and send.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Saving and history", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A piece saves itself a moment after you stop typing. Every save is a version, including each change the assistant makes and every outline or write-out.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the versions with who saved each one, and whether it was you, an outline or a write-out, or the assistant. Restore saves an earlier version again as the newest, so nothing is lost.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If someone else saves the piece while you are editing, you are asked to reload instead of overwriting their work.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Take it with you, or delete it", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Copy as text", "type": "text", "marks": [{"type": "bold"}]}, {"text": " copies the narration and the quoted words, with each clip''s length and the total running time. ", "type": "text"}, {"text": "Export excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " downloads every excerpt in the project as one zip. ", "type": "text"}, {"text": "Delete piece…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", in the ⋮ at the top of the piece, removes the piece and its history after a confirmation; the project''s excerpts are not affected.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Only audio and video excerpts can go in a piece. Document excerpts have no sound.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If an excerpt is deleted after it was used, its block says so and can be swapped or removed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Everything on a piece works on a phone: menus and the + picker open as sheets, and Move up and Move down replace dragging.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Outlining, writing out and the assistant send the piece''s material (accepted findings and the excerpts'' words) to an outside service, as analysis does. Building a piece by hand doesn''t.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Pieces list says how each piece was made: Written by hand, or the format it was written from, then edited.", "type": "text"}]}]}]}]}', 'release', 'The Start your piece panel, search in the Pieces list, and Delete piece', '2026-11-05 23:48:42.540935+00', NULL),
	('5be95327-91d6-4d1b-9d60-0c1c3720be5a', '975b9e41-b70b-43c3-a05c-77541834297a', 4, 'Analyzing a source', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Analyze reads one source and tells you what in it matters: the few findings that add to what the project already knows, and a few passages that might work as audio. Everything it suggests waits for your decision, and nothing is quoted or used until you accept it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Analyze a source", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the project''s ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, choose ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the next-step panel''s button when sources are ready, or the one beside ", "type": "text"}, {"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " above the source list. Each source is read on its own, up to three at a time, and a panel under the tabs shows progress. You can leave the page while it runs, as long as the browser tab stays open. A source that is still transcribing can be analyzed once it finishes, and ", "type": "text"}, {"text": "Not analyzed", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under Show lists the ones still to do.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "From a source, choose ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Analyze again", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under the Data points panel.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A research question is not required. With one, the model looks for what bears on it; without one, it looks for what a reporter would need to know, check or cite. Questions on the Setup tab sharpen the result, and fewer, more specific questions work better than a list of topics.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What you get", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Findings", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": a short paraphrase with the passages it rests on, who said it, and one line on why it matters. The model is shown what the project has already accepted, so it adds to, sharpens or contradicts it instead of repeating it. Often it will find little in a source that repeats the others, and that is the intended result.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Clips to review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": a few passages that might work on the air. Play one, trim it, then accept it into an ordinary excerpt or reject it. Often there are none. See ", "type": "text"}, {"text": "Clips to review", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-suggested-quotes"}}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Pages consulted", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the model can search the web when it needs context to read a source, such as an unfamiliar place, term or claim. The pages it relied on are listed on the Setup tab and under ", "type": "text"}, {"text": "Pages the model looked up", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the Review tab, and a search never uses an interviewee''s name. They inform the model''s reading and never count as evidence.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Set up the project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open a project and select ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", at the right of the tabs. Where the project stands is the row of steps on the Notebook tab, above the sources, not repeated here.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add the questions you are trying to answer. The ⋮ beside a question moves it up or down, or archives it. Archived questions keep their findings and can be restored.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dismiss a page that is wrong or irrelevant and the model stops being shown it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Say who the interviewer is", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On a source, open the speakers menu and tick ", "type": "text"}, {"text": "Interviewer", "type": "text", "marks": [{"type": "bold"}]}, {"text": " beside the person asking the questions. What an interviewer says is not treated as a finding or a clip.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Decide on the project''s Review tab", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", the tab with the count of findings and clips waiting, lists everything Analyze left waiting from every source, grouped by source. Play a finding''s passage or a clip in place, or ", "type": "text"}, {"text": "Open in source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to read it beside the transcript. On a finding, ", "type": "text"}, {"text": "Accept", "type": "text", "marks": [{"type": "bold"}]}, {"text": " keeps it, ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " rewords the claim and accepts it, and ", "type": "text"}, {"text": "Reject", "type": "text", "marks": [{"type": "bold"}]}, {"text": " hides it; on a clip, Play, ", "type": "text"}, {"text": "Accept", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Reject", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". ", "type": "text"}, {"text": "Accept all", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for findings and for clips accepts everything waiting at once, after a confirmation. Nothing is deleted by deciding: an accepted finding offers ", "type": "text"}, {"text": "Undo", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and a rejected one ", "type": "text"}, {"text": "Put back for review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Review findings in the source", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open a source from its project and switch the panel beside the transcript from Excerpts to ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Each finding is underlined in lime where it is in the transcript. A dashed card and dashed underline are suggestions you have not reviewed yet. The chips show ", "type": "text"}, {"text": "To review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "All", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Rejected", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and the same Accept, Edit, Reject and Play buttons are on each card. Analyze again later: accepted and rejected findings and clips are kept, and only suggestions you have not reviewed are replaced.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A finding is a paraphrase. To use the speaker''s own words, accept a clip or make an excerpt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The findings you have decided on are listed under ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the project''s Notebook, filtered Accepted, Rejected or Both, each linking to its source.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Interview audio and text are sent to an outside service to be read, as they are for transcription.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Everything here works on a phone: the Excerpts tab holds the switch, and the player stays docked at the bottom.", "type": "text"}]}]}]}]}', 'release', 'Analyze from the Notebook tab, and the project''s Review tab', '2026-11-05 23:48:42.540935+00', NULL),
	('891b1b2f-5dbc-4627-ab36-ce4a1db67b23', 'c18c50ff-c90a-4cea-9b67-70632e202912', 1, 'Trim a clip and shorten its pauses', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Trim sets where a clip starts and ends in a piece. Pauses shortens the long gaps inside it. Both change only this piece unless you choose otherwise.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Trim a clip", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On an excerpt block, open the ", "type": "text"}, {"text": "⋮", "type": "text", "marks": [{"type": "bold"}]}, {"text": " menu and choose ", "type": "text"}, {"text": "Trim…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The clip''s words appear with a few words of transcript either side. Tap a word to move the start or end to it, whichever is nearer, or use the −250, −50, +50 and +250 buttons. ", "type": "text"}, {"text": "Play as cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays the clip as it is now.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The excerpt''s own trim buttons on the transcript screen work the same way: choose ", "type": "text"}, {"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on an excerpt card and tap a word to move its start or end.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "By default the trim applies to this piece only. Choose ", "type": "text"}, {"text": "Update the excerpt everywhere", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change the excerpt itself; the panel says how many other pieces use it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Shorten long pauses", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Pick a setting. ", "type": "text"}, {"text": "Long pauses only", "type": "text", "marks": [{"type": "bold"}]}, {"text": " looks for gaps over a second, ", "type": "text"}, {"text": "Standard", "type": "text", "marks": [{"type": "bold"}]}, {"text": " over 0.7 seconds and ", "type": "text"}, {"text": "Tight", "type": "text", "marks": [{"type": "bold"}]}, {"text": " over half a second. Each pause is cut down rather than removed, leaving a short beat so the speaker doesn''t sound clipped.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose ", "type": "text"}, {"text": "Find pauses", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Each one is marked between the words with how much it would save, for example ⏸ 1.4s.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose ", "type": "text"}, {"text": "Play as cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to hear the clip with those pauses skipped.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose ", "type": "text"}, {"text": "Remove these pauses", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to apply them, or ", "type": "text"}, {"text": "Cancel", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to leave the clip as it is.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Shortened pauses show as −1.4s in the words, the block says how many it has, and the piece''s length updates. ", "type": "text"}, {"text": "Put the pauses back", "type": "text", "marks": [{"type": "bold"}]}, {"text": " restores the clip. Pauses are found from the transcript''s word timings, so a line with no timings has nothing to find. Pauses are kept per piece; the same excerpt in another piece is not changed.", "type": "text"}]}]}', 'release', 'First version', '2026-11-05 23:48:41.705394+00', NULL),
	('50c8f0b4-1a61-4080-af29-ad2aa5eb41f6', '6c053a16-e34b-4f5b-85a7-ac45f8765fb7', 1, 'Play, trim and manage an excerpt on a phone', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "On a phone, tapping words that are part of a saved excerpt opens a sheet above the player. The transcript stays visible behind it. On a larger screen the same tap selects the excerpt''s card beside the transcript.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What the sheet shows first", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Play excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays just that excerpt, at the level it will be exported. It becomes ", "type": "text"}, {"text": "Pause", "type": "text", "marks": [{"type": "bold"}]}, {"text": " while it plays.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens everything you can do to the excerpt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Show in Excerpts tab", "type": "text", "marks": [{"type": "bold"}]}, {"text": " takes you to the excerpt''s card in the list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ✕ button closes the sheet.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit an excerpt", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Edit shows the same card as the Excerpts tab. Tap the title to rename it. Choose ", "type": "text"}, {"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to show the excerpt''s words and move its start or end by tapping a word. Choose ", "type": "text"}, {"text": "Original level", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Even out", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to change its level. ", "type": "text"}, {"text": "Export WAV", "type": "text", "marks": [{"type": "bold"}]}, {"text": " makes the file, and ", "type": "text"}, {"text": "Download", "type": "text", "marks": [{"type": "bold"}]}, {"text": " appears once it exists. Delete asks you to confirm. Play stays at the bottom of the sheet so you can hear each change; choose ", "type": "text"}, {"text": "Done", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to go back.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "When excerpts overlap", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "If the words you tapped are in more than one excerpt, the sheet says so and lets you pick which one to work on. The shortest is shown first.", "type": "text"}]}]}', 'release', 'First version', '2026-11-05 23:48:41.743596+00', NULL),
	('f1d9922a-c476-49a2-9f63-62b63de7c0b0', '46cde0d0-4229-482b-88a7-3727773bfee1', 5, 'Synthesis', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Synthesis reads every finding you have accepted in a project and says what they establish about each of your research questions. It is a reading aid: nothing on this tab is evidence, and every statement opens onto the findings behind it. The tab appears once the project has an accepted finding, and its badge counts the findings accepted since the version it shows was saved.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The top of the tab", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The header says which version you are reading, when it was written and how many findings and sources it reads. ", "type": "text"}, {"text": "Synthesize", "type": "text", "marks": [{"type": "bold"}]}, {"text": " writes the first version; afterwards the button reads ", "type": "text"}, {"text": "Update synthesis", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when findings have been accepted since the version shown, or ", "type": "text"}, {"text": "Synthesize again", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The version menu lists every earlier one; reading an old version is read-only. When a version is not the first, a line under the header says what changed since the previous run: new statements, removed ones, and statements whose certainty moved.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Under it, a summary shows the whole answer at once: how many statements are established, contested and uncertain, and how many tensions, open points and patterns there are. A count in red means statements that no longer have an accepted finding behind them. The chips under the summary show only statements of one certainty.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Reading a statement", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each statement carries a certainty. Five dots show how many different sources it rests on, and ", "type": "text"}, {"text": "One source''s account", "type": "text", "marks": [{"type": "bold"}]}, {"text": " marks a statement that rests on a single source.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Evidence", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a statement to open the findings behind it beside the synthesis, or in a sheet on a phone. Play at a time plays that finding in place, and ", "type": "text"}, {"text": "Open in source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " goes to the passage in the full recording or page.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Sections", "type": "text", "marks": [{"type": "bold"}]}, {"text": " list moves between questions, patterns, conflicts and the moments worth hearing.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Patterns, and what is still open", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Patterns across sources are things several people described separately that no question asked about. A pattern marked ", "type": "text"}, {"text": "Passages only", "type": "text", "marks": [{"type": "bold"}]}, {"text": " rests on moments the model found in the recordings, not on an accepted finding, so treat it as less firm. A pattern marked ", "type": "text"}, {"text": "New", "type": "text", "marks": [{"type": "bold"}]}, {"text": " was not in the previous run.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Track as a research question", "type": "text", "marks": [{"type": "bold"}]}, {"text": " adds a question on the Setup tab, so the next Analyze listens for it. The pattern then reads ", "type": "text"}, {"text": "Tracking", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and cannot be added twice.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dismiss", "type": "text", "marks": [{"type": "bold"}]}, {"text": " hides a pattern. Dismissed patterns are listed under the patterns, with ", "type": "text"}, {"text": "Restore", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and a new run does not offer them again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each open point has the same ", "type": "text"}, {"text": "Track as a question", "type": "text", "marks": [{"type": "bold"}]}, {"text": " action.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Choices you make here are saved as a new version marked as edited by a person, and a later run keeps them as they are. Because that is a version too, the badge and the Update synthesis label count findings accepted after it, not after the last model run.", "type": "text"}]}]}', 'release', 'The badge counts from the version shown, which a tracked or dismissed pattern also saves', '2026-11-05 23:48:42.616845+00', NULL),
	('0362b215-9cc7-4b55-8e12-968d99038d19', '74d6c342-6c61-43de-aee3-e371f6e072ba', 6, 'Searching across projects and sources', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The search box on the ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework?tab=notebook"}}]}, {"text": " tab of the Sourcework home page searches every project, source, transcript, document and excerpt you can open. Type what you are looking for and press Enter.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The Notebook tab", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Notebook holds everything you can reuse, in two sections: ", "type": "text"}, {"text": "Sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (every recording and document, whichever project it is in) and ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (every saved clip and passage). One search box sits under them. In Sources the same box also narrows the list by title as you type, so you can find a source by name; press Enter to search every transcript and excerpt instead. Projects stay on their own tab, where ", "type": "text"}, {"text": "+ New project", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts one.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How results work", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Results are grouped by project, so several hits from one interview read as one project. The first three show, and ", "type": "text"}, {"text": "Show more", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the rest. The words you searched for are highlighted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The chips above the results narrow them by kind: ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "In transcripts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "In documents", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Projects", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", each with its count.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Clear search", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to return to the Notebook.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Searching inside a project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In a project''s ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", the Excerpts section has a search box that covers only that project. To find a word inside one transcript, use ", "type": "text"}, {"text": "Find in this transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " above it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The line under the search box says what kind of search is running. Administrators also see whether topic search, which finds a passage by what it is about and not only its exact words, is switched on.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Topic search depends on an optional service. When it is off, keyword search still finds everything; it just will not catch a paraphrase.", "type": "text"}]}]}]}]}', 'release', 'One search box in the Notebook, which also narrows Sources by title', '2026-11-05 23:48:42.502699+00', NULL),
	('3f6590f9-2362-4391-ab4b-1742adcb6968', '68b622a9-b552-4c10-9e07-91ba851dc058', 1, 'From interview recording to radio script', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sourcework can take a recorded interview all the way to a usable script without any of the analysis steps. This walkthrough covers transcription, excerpts you pick yourself, and the piece editor. Research questions, Analyze, Synthesis and Outline are optional.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "1. Add the recording", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open ", "type": "text"}, {"text": "Sourcework", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework"}}]}, {"text": " and select ", "type": "text"}, {"text": "+ New project", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the Projects tab. Name the project, then drop the recording onto the box or select ", "type": "text"}, {"text": "Choose files", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or add it later. For a recording that is already in the ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework?tab=notebook"}}]}, {"text": ", open the project and use ", "type": "text"}, {"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Find existing", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", instead of uploading another copy. See ", "type": "text"}, {"text": "Starting a project and adding sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-starting-a-project"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "2. Check the transcript", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select the source in the project''s list to open it. When transcription finishes, listen while following the words, which move with the audio. Check names, figures, who is speaking and any wording you might quote against the recording, and name the speakers from the ", "type": "text"}, {"text": "Speakers", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button. ", "type": "text"}, {"text": "Find in this transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " locates a phrase so you can listen around it. See ", "type": "text"}, {"text": "Working with the transcript and creating excerpts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-transcript-and-excerpts"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "3. Pick the excerpts yourself", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Find a passage that gives the story something: a concrete detail, a telling phrase, a firsthand account. A clip should make sense on its own and have clean entry and exit points. Select its words in the transcript, keep or change the suggested title, and save it as an excerpt. Play it from its card, and use ", "type": "text"}, {"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to move its start or end to a word. Repeat for other passages. Nothing has to be analyzed first.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "4. Build the script by hand", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the project, open ", "type": "text"}, {"text": "Pieces", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and select ", "type": "text"}, {"text": "+ New piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Write narration in a block, and use the ", "type": "text"}, {"text": "+", "type": "text", "marks": [{"type": "bold"}]}, {"text": " rows between blocks to add the project''s excerpts in order. Reorder, swap or remove blocks as you revise; ", "type": "text"}, {"text": "Trim…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on an excerpt block refines the cut in this piece without changing the saved excerpt. Pick a ", "type": "text"}, {"text": "Format", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under the length if you want a target, and read the length as an estimate: narration is timed at 160 words a minute, so read it aloud. See ", "type": "text"}, {"text": "Building a piece from narration and excerpts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-pieces"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "5. Prepare for production", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Listen to each finished cut against the original audio, and verify attribution, wording, context and sequence. ", "type": "text"}, {"text": "Copy as text", "type": "text", "marks": [{"type": "bold"}]}, {"text": " copies the script, and ", "type": "text"}, {"text": "Export excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " downloads the project''s clips as one zip, each at an even level. The piece saves a version as you work; ", "type": "text"}, {"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " restores an earlier one.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Optional next steps", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "From here you can ", "type": "text"}, {"text": "search across projects and sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-search"}}]}, {"text": ", have a source ", "type": "text"}, {"text": "analyzed", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-research"}}]}, {"text": " for findings and clips to review, or let AI ", "type": "text"}, {"text": "outline a piece", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-outline"}}]}, {"text": " from the findings you have accepted. They are additional ways of working, not prerequisites for a script.", "type": "text"}]}]}', 'release', 'Brought into the repository and updated: Notebook, Find existing, the format under the length', '2026-11-05 23:48:42.540935+00', NULL),
	('8d0f0e35-5e87-44e4-aaed-0ec547cadfd6', 'd48232a1-bf86-4f3c-9e03-cf88578c8009', 5, 'Starting a project and adding sources', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A project is the workspace for one story. It starts with a name; sources, which are recordings and PDFs, are added to it now or later.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Create a project", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Projects tab of the ", "type": "text"}, {"text": "Sourcework home page", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework"}}]}, {"text": ", select ", "type": "text"}, {"text": "+ New project", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Type a title and, if you like, notes: what the project is about and who set it up.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Add sources now if you have them. Drag recordings or PDFs onto the box, or select ", "type": "text"}, {"text": "Choose files", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Several at once is fine; each becomes its own source, titled from its file name. Rename any title before you upload.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Create project", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or ", "type": "text"}, {"text": "Create project and upload", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the number of files.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "While files upload", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Files upload three at a time. One bar shows overall progress, with a line for each file in progress. A file that fails stays at the top with the reason and a ", "type": "text"}, {"text": "Retry", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and the rest carry on. An upload is not resumable, so a retry starts that file over.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Stop", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lets the files already uploading finish and leaves the rest waiting; ", "type": "text"}, {"text": "Resume", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts them again. Keep the page open until it finishes. When every file is uploaded you land on the project. If some failed, the project is still created, and you can open it and add the rest later.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "After the upload", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Processing continues in the background. The project''s source list shows each source''s status and a progress bar, and the page updates on its own when it is done.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Audio and video get a transcript. A PDF''s text is extracted automatically: a plain read of the file first, falling back to OCR only when that is not enough.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If processing fails, the source says why under its title. Open it for ", "type": "text"}, {"text": "Retry", "type": "text", "marks": [{"type": "bold"}]}, {"text": "; the file itself is already safely uploaded.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The Sourcework home", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Pick up where you left off", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", at the top, shows up to three projects: ones with a source that failed or findings waiting for review first, then the most recently active.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Projects", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab lists the most recently active projects first, 25 to a page. The filters show how many projects each holds: ", "type": "text"}, {"text": "All", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Started by me", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Needs attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (a source failed, or findings are waiting for review) and ", "type": "text"}, {"text": "No sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Each row shows a bar of the five steps done (Sources, Analyze, Review, Synthesis, Piece) with the step it is on, its sources, its excerpts, who started it, its last activity and its status. Select anywhere on a row to open the project.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab holds every source and every excerpt, whichever project they are in. See ", "type": "text"}, {"text": "Browse the Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-browse-source-library"}}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Deleting a project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Only the person who started a project can delete it: open the project and choose ", "type": "text"}, {"text": "Delete project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " from the ⋮ menu beside its title. It asks once more and names what will happen: sources that only this project uses are removed with their transcripts and excerpts, and sources that another project also uses stay in the Notebook. A long list shows five names and a count.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A project does not need a source. One without any shows ", "type": "text"}, {"text": "No sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the list, and opens with an ", "type": "text"}, {"text": "Add the first source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Anything outside the accepted audio, video and PDF types is refused before the upload starts, with a message naming what is accepted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The file goes straight from your browser to storage. A long recording can take a few minutes to upload.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once a source is uploaded, it can be used in more than one project with no re-upload. See ", "type": "text"}, {"text": "Add another source to a project", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-reference-another-source"}}]}, {"text": ".", "type": "text"}]}]}]}]}', 'release', 'Projects and Notebook tabs, the Pick up strip, progress in the list, Delete project in the ⋮ menu', '2026-11-05 23:48:42.540935+00', NULL),
	('4ad2b542-ff39-479b-8d6e-0cea6b2842c0', 'bf81b991-4ed9-4463-a805-98d6a84df1b1', 6, 'Add another source to a project', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A project can draw on more than one recording or document. When the same interview matters to more than one story, add it to each project instead of uploading it again. Every project then shares one original and one transcript.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add a source", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the project. On its ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, ", "type": "text"}, {"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sits with the filters above the source list. A project with no sources shows ", "type": "text"}, {"text": "Add the first source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " instead.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On ", "type": "text"}, {"text": "Find existing", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", search for the source by title and select ", "type": "text"}, {"text": "Reference", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". It is added right away, with no confirmation step.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On ", "type": "text"}, {"text": "Upload new", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", drag in recordings or PDFs that are not in Sourcework yet, or select ", "type": "text"}, {"text": "Choose files", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". They upload the same way as from a new project.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Move between sources", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The project screen lists its sources, and each one opens as its own screen with the player, transcript and excerpts. The back link at the top of a source returns to the project, which is the way to its other sources. The link carries the project, so ", "type": "text"}, {"text": "Remove from this project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the source''s ⋮ menu knows which project to take it out of. A source opened from the home Notebook instead gains a ", "type": "text"}, {"text": "Projects", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab listing every project that uses it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The project''s Notebook also has an ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " section with every excerpt from every one of its sources, behind a search box that covers only this project, and a ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": " section with the findings decided on across them.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Take a source out of a project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Remove from this project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", in the ⋮ at the end of a source''s row or in the source''s own menu, detaches it. The recording, its transcript and its excerpts stay in the Notebook and in any other project that uses it. ", "type": "text"}, {"text": "Delete source…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", on the source''s own screen only, deletes it everywhere, with its transcript and every excerpt made from it, and asks you to confirm.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An excerpt belongs to the source it was made from, so it shows in every project that uses that source.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Retrying a failed transcription retries that source alone.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "PDF documents are added the same way as audio. They open in the document viewer instead of the player.", "type": "text"}]}]}]}]}', 'release', 'The source switcher is gone: each source is its own screen, reached from the project''s list', '2026-11-05 23:48:42.540935+00', NULL),
	('6bd33c6b-20d3-4b23-861c-cf6d7d54af24', 'efb5f849-e15a-43f7-b1f1-ecb08dc9212c', 1, 'Clips to review', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A clip is a literal cut of a recording that Analyze thought might work on air, as against a finding, which is a paraphrase. Nothing becomes an excerpt until you accept it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Where clips are", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Analyzing a source proposes up to five clips. They appear on the project''s ", "type": "text"}, {"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab, grouped with that source''s findings, and on the source''s own page under ", "type": "text"}, {"text": "Clips to review", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", above the findings in the Data points panel. The section is absent when none is waiting; often there are none.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Decide on each clip", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each card shows who says it, the words, its length and why it works.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Play", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays the clip as it will cut, from the original audio. Check the words as you listen: the transcript is itself a machine reading of the audio.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Accept", "type": "text", "marks": [{"type": "bold"}]}, {"text": " saves the clip as an ordinary excerpt on its source. It then appears in the source''s excerpts, in the project''s Excerpts section and in the piece editor''s excerpt picker.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " opens the start and end with the −250, −50, +50 and +250 buttons; ", "type": "text"}, {"text": "Back to the suggested cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " undoes them. Play again to hear the new cut, then Accept. The words are read again from the transcript for the range you accept.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Reject", "type": "text", "marks": [{"type": "bold"}]}, {"text": " hides the clip. It is kept, so the same stretch is not suggested again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Review tab, ", "type": "text"}, {"text": "Accept all N clips", "type": "text", "marks": [{"type": "bold"}]}, {"text": " accepts every waiting clip at the range proposed, after a confirmation.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Clips are only ever taken from the speaker''s own words, one speaker at a time, at sentence edges, between 1.5 and 60 seconds.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Everything here works on a phone: cards stack, and the buttons are larger.", "type": "text"}]}]}]}]}', 'release', 'Rewritten for Analyze''s clips; themes and tiers are gone', '2026-11-05 23:48:42.540935+00', NULL),
	('46ebfa4a-0b39-46a5-9df5-cdd57e989520', '3d67c4db-6fd6-45ed-a81f-1e6849124247', 5, 'Maintaining the prompts', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Editors maintain the wording the model works from. You need the Editor role on Sourcework, which an administrator grants on the user''s access screen; with it, a ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab appears at the right of the Sourcework tabs, with ", "type": "text"}, {"text": "Prompts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Piece formats", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a prompt", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Prompts", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Choose a guide on the left (on a phone, from the list at the top): the ", "type": "text"}, {"text": "Analyze guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " decides what makes a finding worth keeping and a clip worth offering; the ", "type": "text"}, {"text": "Synthesis guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " how the accepted findings are weighed against the research questions; the ", "type": "text"}, {"text": "Outline guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " what makes a good outline and which clips earn a place in it; and the ", "type": "text"}, {"text": "Writing guide", "type": "text", "marks": [{"type": "bold"}]}, {"text": " the house style of the narration Write from outline produces, such as the tense of attribution. Edit the text and it saves itself as a draft only you can see. The shape of the answer is fixed by the code, and ", "type": "text"}, {"text": "What the model is given and returns", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows both. ", "type": "text"}, {"text": "Discard draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " goes back to the live text.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Publish and roll back", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Publish", "type": "text", "marks": [{"type": "bold"}]}, {"text": " asks for a one-line note about what changed, then makes the draft the live version for every project''s next run.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists earlier versions with their notes and, for the Analyze guide, the share of its findings people accepted. ", "type": "text"}, {"text": "Edit from this version", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts a draft from it, and ", "type": "text"}, {"text": "Make live again", "type": "text", "marks": [{"type": "bold"}]}, {"text": " moves an earlier version back into use. Nothing is deleted.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Until something is published, a prompt runs on its built-in text.", "type": "text"}]}]}]}]}', 'release', 'Reached from the Setup tab; the Writing guide', '2026-11-05 23:48:42.540935+00', NULL),
	('a3fd5b6f-17e2-4857-a4bc-50eaec352761', '4a3381bb-1762-4cb1-a518-02508148687c', 5, 'Maintaining piece formats', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A piece format is the shape and wording an outline, and writing the outline out, follow: its length, how many actualities it usually uses, a free-text description and style, and whether an anchor leads in. These are guardrails: the model decides the beats and chooses the actualities freely from the material, so every story can take its own shape. Editors maintain formats; you need the Editor role on Sourcework, which an administrator grants on the user''s access screen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a format", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", at the right of the Sourcework tabs, then ", "type": "text"}, {"text": "Piece formats", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Pick a format on the left (on a phone, from the list at the top). Your changes save themselves as a draft only you can see, and ", "type": "text"}, {"text": "Rename", "type": "text", "marks": [{"type": "bold"}]}, {"text": " changes its name everywhere.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Length", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Plus or minus", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the length the piece should run and the range that counts as on target, such as 0:53 within 0:08, which is 0:45 to 1:01.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Usual actualities", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the fewest and most clips the piece usually uses. It is a guide, not a quota: an outline may use fewer, and only going over the most is flagged in a trial.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Description and style", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": what the piece does and how it sounds, such as who reads it and what a listener should come away with. Write placeholders the reporter fills in, such as [REPORTER NAME], in square brackets. Don''t lay out its blocks or their order: the model decides how many beats the story needs and where the actualities go. Tick ", "type": "text"}, {"text": "An anchor may read a lead-in first", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for formats where the anchor can introduce a reporter''s recorded piece. It is always optional, since a piece the anchor reads itself has none, and it isn''t counted in the length.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The model writes beats, and narration when an outline is written out; actualities are always the project''s own excerpts. A format can''t change that, and it can''t make the model type out a quote.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Try a draft", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Try this draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " outlines a piece from one project''s accepted findings and excerpts with your draft and with the live version, and shows the two side by side with how many beats and actualities each used and how much clip time. Add a direction if you want to test one. Nothing is added to the project, and results are kept for 14 days under ", "type": "text"}, {"text": "Recent trials", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", visible only to you.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Publish and roll back", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Publish", "type": "text", "marks": [{"type": "bold"}]}, {"text": " asks for a one-line note about what changed, then makes the draft the live version. Reporters'' next outlines follow it; pieces already outlined keep the version they followed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "History", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists every version with its note and how many pieces it made. ", "type": "text"}, {"text": "Edit from this version", "type": "text", "marks": [{"type": "bold"}]}, {"text": " starts a draft from it, and ", "type": "text"}, {"text": "Make live again", "type": "text", "marks": [{"type": "bold"}]}, {"text": " moves an earlier version back into use. Nothing is deleted. ", "type": "text"}, {"text": "Discard draft", "type": "text", "marks": [{"type": "bold"}]}, {"text": " goes back to the live version.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "+ New format", "type": "text", "marks": [{"type": "bold"}]}, {"text": " adds a format. It isn''t offered to reporters until you publish it.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The formats to start with", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Five formats come built in, each a description and a set of guardrails: Reader / Voicer (about 0:30 to 0:45, no actualities), Cut and Copy (0:45, one actuality), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). Anything else, such as a two-way or an interview, is a format you can add. Change the built-in ones like any other format.", "type": "text"}]}]}', 'release', 'Reached from the Setup tab', '2026-11-05 23:48:42.540935+00', NULL),
	('853affe5-db19-4112-a38a-9697414e96ac', '303db882-a2f3-47ad-9a3a-cbac5ef0e4c0', 4, 'Accepting suggestions in bulk', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "When Analyze suggests a lot of findings, you do not have to decide on each one separately. Each accept-all button asks you to confirm first, because you are deciding on many things without reading each.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "On the project''s Review tab", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The panel at the top says how many findings and clips, from how many sources, are waiting. ", "type": "text"}, {"text": "Accept all", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the count accepts every waiting finding in the project. ", "type": "text"}, {"text": "Accept all", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the count of clips makes every waiting clip into an excerpt at the range Analyze proposed; each can still be trimmed or deleted in its source afterwards, and a clip that couldn''t be accepted stays waiting, which the message says.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "In one source", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "On a source''s Data points panel, with the ", "type": "text"}, {"text": "To review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " filter showing and more than one finding waiting, ", "type": "text"}, {"text": "Accept all", "type": "text", "marks": [{"type": "bold"}]}, {"text": " accepts the findings waiting in that source only. Findings you have already decided on are left as they are.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Taking a decision back", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nothing is deleted by accepting. A finding can be rejected or put back for review afterwards, and an accepted clip is an ordinary excerpt you can delete.", "type": "text"}]}]}', 'release', 'The Review tab''s two accept-all buttons', '2026-11-05 23:48:42.540935+00', NULL),
	('5e107fc6-7889-4ff0-925f-4edafef1f212', 'b1df2fcc-78bb-4240-b5bc-5613359dd8ae', 5, 'A project at a glance', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A project opens on where it stands and what to do next. You can do every step yourself, ask AI to do any step, or hand it the rest.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The steps and the next step", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The row of steps runs Sources, Analyze, Review, Synthesis, Piece. A finished step is a link back to its tab. Under it, one panel names the next step and gives you one button for it: ", "type": "text"}, {"text": "Add the first source", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when sources are ready, ", "type": "text"}, {"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the count waiting, ", "type": "text"}, {"text": "Open Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when nothing has been accepted yet, then ", "type": "text"}, {"text": "Open Synthesis", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Start a piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The steps only report and suggest; you can use any tab at any time. Once the project has a piece, the strip and the panel are gone and the Pieces tab carries on. On a phone the row of steps is left out, since the tabs and the Review badge say the same, and the panel is one line with its button and the hand-over link side by side.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The title and background", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The project''s title and background sit at the top; the background is shown on every excerpt and search result from the project, so say what it was about. ", "type": "text"}, {"text": "Add background", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "Edit details", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under the title opens them for editing, as does ", "type": "text"}, {"text": "Edit title and background", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the ⋮ menu beside the title, which is the way in on a phone. The same menu holds ", "type": "text"}, {"text": "Delete project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", with a list of what goes and what stays.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tabs", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds what you browse, in three sections. ", "type": "text"}, {"text": "Sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the project''s sources, ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the findings you have accepted or rejected (filtered Accepted, Rejected or Both, each linking to its source), and ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists the excerpts made from them, with ", "type": "text"}, {"text": "Export excerpts (zip)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is where you decide on the findings and clips Analyze suggested, from every source at once. The number beside it is how many are waiting.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Synthesis", "type": "text", "marks": [{"type": "bold"}]}, {"text": " appears once a finding has been accepted. ", "type": "text"}, {"text": "Pieces", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Setup", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", which holds the research questions and the pages the model consulted, complete the row.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Run the remaining steps with AI", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The link under the button opens a dialog that runs the steps still to do, one after another, and hands control back where you choose: after Analyze, after Synthesis, after Outline, or after a first draft. It starts on Analyze, so the Review tab stays yours. Going past Analyze accepts every suggested finding and clip without your review, and the dialog says so before you start; they can be put back for review afterwards. Keep the page open while it runs. ", "type": "text"}, {"text": "Stop after this step", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ends the run, and what finished is kept.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find a source", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each source has a bar showing how far it has come: processed, analyzed, reviewed. The word under it says which step it is on.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Filter sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " searches titles. ", "type": "text"}, {"text": "Show", "type": "text", "marks": [{"type": "bold"}]}, {"text": " narrows the list to sources ", "type": "text"}, {"text": "Not analyzed", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or that ", "type": "text"}, {"text": "Need attention", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and ", "type": "text"}, {"text": "Sort", "type": "text", "marks": [{"type": "bold"}]}, {"text": " puts the newest first or sorts by title. The list shows 25 at a time.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select a row to open the source. A source that failed to process says why under its title. The ⋮ menu at the end of the row opens the source or removes it from this project.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and, except when it is the panel''s own button, ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sit with the filters above the source list.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Hints that go away", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Short how-to notes on some screens, such as how to select words into an excerpt, show a ", "type": "text"}, {"text": "Got it", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button. Select it and that note stays hidden in this browser.", "type": "text"}]}]}', 'release', 'The strip is left out on a phone and once a piece exists; the tabs and the header as they are now', '2026-11-05 23:48:42.540935+00', NULL),
	('f8ac4395-2f0f-4c22-97fd-730f5970f3b5', '82b6e8dd-0fd7-438a-a656-99320afb3e45', 4, 'Browse the Notebook', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab on the Sourcework home lists everything you can reuse, independent of the projects that use it, in two sections.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Sources", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Every recording and document, as cards showing its kind, date, length or page count, and how many projects use it. The chips narrow the cards to ", "type": "text"}, {"text": "Audio", "type": "text", "marks": [{"type": "bold"}]}, {"text": " or ", "type": "text"}, {"text": "PDF", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and typing in the search box narrows them by title as you type; Enter searches every transcript and excerpt instead, see ", "type": "text"}, {"text": "Searching across projects and sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-search"}}]}, {"text": ". Select a card to open the source on its own: the same player, transcript and excerpts a project shows, or the page viewer and text for a PDF, plus a ", "type": "text"}, {"text": "Projects", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab listing every project that uses it, with a filter once there are eight.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Excerpts", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Every saved clip and passage. The title opens the source at that excerpt, and the project name opens the project it belongs to.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A source is the original recording or document. It is never edited; a project is the work that refers to it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To use a source in another story, add it from that project with ", "type": "text"}, {"text": "+ Add source", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", then ", "type": "text"}, {"text": "Find existing", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A source opened from the Notebook can be deleted from its ⋮ menu, everywhere at once; one opened from a project can also be removed from just that project.", "type": "text"}]}]}]}]}', 'release', 'The Source Library became the Notebook''s Sources section', '2026-11-05 23:48:42.540935+00', NULL);
INSERT INTO public.rc_article_versions (id, article_id, version, title, body, source, note, created_at, created_by) VALUES
	('55e0c5fa-2767-4b3c-98cd-0bccbc68c1f8', 'f8a5cab8-aa99-4e53-83fc-1afe798573aa', 3, 'Configure the pitch form and rubric', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Settings", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial/settings"}}]}, {"text": " is for editors. It has three parts: ", "type": "text"}, {"text": "Submission form", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Pillars", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and ", "type": "text"}, {"text": "Rubric", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Retired entries stay on the pitches and scores that used them, so nothing changed here rewrites history.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Submission form", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "+ Add field", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to add a question to the pitch form. A field''s type is fixed once it exists; its label, help text, options, and whether it''s required can change later.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Reorder fields with the arrows. Retire a field you no longer need; restore it any time.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Pillars", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Pillars are the station''s coverage priorities. Each has a guiding question, shown to writers on the pitch form. Retire a pillar to take it off the form; a retired pillar can be deleted.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Rubric", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Core criteria are weighted and averaged; the active weights should add up to 100. Modifiers are scored separately and never count toward the core average.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each criterion can carry anchored descriptions — what each score means — which reviewers see when they hover a score.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A weight change applies to future scoring only. The scoring scale and the modifier threshold are set at the bottom of the page.", "type": "text"}]}]}]}]}', 'release', 'One rubric: criteria no longer belong to a profile', '2026-11-05 23:48:42.708196+00', NULL),
	('522f1508-e3c0-4e63-ba89-b87f5b7f0be3', 'd600ea92-8b1d-4ddd-9515-184acce74f7e', 4, 'Submit a pitch', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Every story idea starts as a pitch in the backlog. An editor picks pitches from the backlog for a weekly planning meeting, where reviewers score them and the editor records a decision.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Submit one", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Backlog tab, select ", "type": "text"}, {"text": "New pitch", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Give it a title — one line that says what the story is — and fill in the fields below it. Fields marked with an asterisk are required.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose a ", "type": "text"}, {"text": "Primary coverage pillar", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". If you choose one of the station''s pillars, say how the story contributes to sustained coverage of it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Submit pitch", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". You land on the pitch''s own page.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find a pitch in the backlog", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The band at the top of the Backlog says where this week''s meeting stands and what you can do next: start or continue scoring, or, for an editor, build the slate, close scoring or conclude. It is not shown between meetings.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Type in ", "type": "text"}, {"text": "Search pitches", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to find a pitch by its title or any of its answers. ", "type": "text"}, {"text": "Filter", "type": "text", "marks": [{"type": "bold"}]}, {"text": " holds the status chips — Open, Stale, Assigned and Archived, each with a count — and the Pillar, Format and Urgency lists.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A pitch marked ", "type": "text"}, {"text": "On slate", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is on the current meeting; ", "type": "text"}, {"text": "Stale", "type": "text", "marks": [{"type": "bold"}]}, {"text": " means it has gone 90 days without a review or has been deferred three times. Editors can archive stale pitches in bulk from the Stale view.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit it", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "You can keep editing your pitch with ", "type": "text"}, {"text": "Edit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " until an editor adds it to a meeting''s slate. While that meeting is scoring, edits are locked; they reopen if the pitch comes back to the backlog.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Follow it", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The pitch page opens with the summary, then the other answers. ", "type": "text"}, {"text": "Where it stands", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", on the right, shows the status, which meeting it is on, how many meetings have reviewed it, the last decision and whether edits are open.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Review history", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lists each meeting that discussed the pitch with its adjusted score and decision; open ", "type": "text"}, {"text": "Scores, decision and comments", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for the breakdown, reviewers'' comments and the rationale.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Editors use the ⋮ menu on a pitch to add it to the open slate, archive it with an optional reason, or restore an archived pitch to the backlog.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Once a pitch is assigned, the page shows who is reporting it. The pipeline ends there; reporting itself is not tracked in this tool.", "type": "text"}]}]}]}]}', 'release', 'The This week band, search and Filter, and the pitch page''s Where it stands and ⋮ menu', '2026-11-05 23:48:42.75501+00', NULL),
	('feb17906-2b42-480c-a69f-adc50dc8c7f5', 'd98b0090-6ccd-4091-b422-601d7326ece0', 4, 'Run a planning meeting', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A planning meeting moves through three stages: Scoring open, Agenda, and Concluded. Editors run it; reviewers and editors score; contributors can follow along. The Meetings tab lists every meeting with its slate, filtered by In progress or Concluded.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Set it up (editors)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Meetings tab, select ", "type": "text"}, {"text": "New meeting", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", choose the date and select ", "type": "text"}, {"text": "Create meeting", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Open the meeting. Select ", "type": "text"}, {"text": "+ Add pitch", "type": "text", "marks": [{"type": "bold"}]}, {"text": " above the slate, choose a pitch from the backlog and select ", "type": "text"}, {"text": "Add to slate", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Repeat for each pitch. A pitch can also be added from its own page''s ⋮ menu.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Score the slate (reviewers and editors)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The slate is a list beside the pitch: a filled dot marks each pitch you have scored. On a phone the list becomes a strip above the pitch, with ", "type": "text"}, {"text": "Previous", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Next", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and a picker. ", "type": "text"}, {"text": "Show the full pitch", "type": "text", "marks": [{"type": "bold"}]}, {"text": " expands the answers below the summary.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose a score for each criterion. On a computer, hover a number to read what it means; on a touch screen the meaning of the chosen number is shown under the scale. Institutional modifiers are optional.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose a recommendation, flag any concerns, and add a comment if it helps the room. ", "type": "text"}, {"text": "Save review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " saves and stays; ", "type": "text"}, {"text": "Save and go to next unscored", "type": "text", "marks": [{"type": "bold"}]}, {"text": " saves and opens the next pitch you have not scored.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Scoring is independent: nobody sees anyone else''s scores or comments until the editor closes scoring.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Decide (editors)", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Close scoring & build agenda", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The slate is ranked by adjusted score, and the strip at the top counts pitches, reviews and decisions made.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "An amber ", "type": "text"}, {"text": "Split", "type": "text", "marks": [{"type": "bold"}]}, {"text": " badge means reviewers'' core scores are far apart — worth discussing. Open ", "type": "text"}, {"text": "Scores, recommendations and comments", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to see why.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For each pitch, choose a ", "type": "text"}, {"text": "Decision", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — Assign, Defer or Archive — and select ", "type": "text"}, {"text": "Record", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Assign asks for the reporter; Defer and Archive take an optional rationale. A decided pitch shows its outcome; select ", "type": "text"}, {"text": "Change", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to revise it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Conclude meeting", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the main action once the agenda is built. It asks you to confirm and names any pitch still undecided, which is recorded as deferred. A concluded meeting is a permanent record.", "type": "text"}]}]}]}]}', 'release', 'The slate list and strip, Save and go to next unscored, the Decision select, and Conclude as the main action', '2026-11-05 23:48:42.75501+00', NULL),
	('52e33707-c1f5-4ef4-b06a-79022f19951b', '9ca1ed5a-cb45-4867-a41b-723d23df58f8', 12, 'Working with the transcript and creating excerpts', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A recording opens as its own screen: the player, the transcript and, beside it, a panel of this source''s excerpts. Excerpts are short clips saved for reuse. On a phone the same screen is three tabs, ", "type": "text"}, {"text": "Transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Speakers", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", with the player docked at the bottom.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find your way", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Find in this transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " looks for a word or phrase from two characters on. Matching words are highlighted. Select the arrows, or press Enter, to step through the matches.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Each line begins with the time it starts. A long answer is cut into lines of about half a minute, at the end of a sentence, so there is always a time to point someone to — “what she said at 14:20.” Transcripts made earlier have been cut the same way. Select a word to play from it; on a word that is part of an excerpt, that also opens the excerpt. Selecting a stretch of text, to make an excerpt, still works as before.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The marks under the progress bar show where your excerpts are; select one to open it. With many excerpts the marks merge into a shaded strip, and darker means more excerpts there. Select a stretch of the strip to zoom the progress bar in until the excerpts separate into their own marks, and select ", "type": "text"}, {"text": "Show the whole recording", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to zoom back out.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The player steps back and forward five seconds, changes speed, and follows the transcript as it plays; ", "type": "text"}, {"text": "Jump to playhead", "type": "text", "marks": [{"type": "bold"}]}, {"text": " scrolls back to the line being played. Space plays and pauses, and the ", "type": "text"}, {"text": "?", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button lists the other keyboard shortcuts.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Speakers", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button names the speakers, with the first few names after it. It opens a list ordered by who spoke most. Type a name to rename a speaker, select ", "type": "text"}, {"text": "Hear an example", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", or tick ", "type": "text"}, {"text": "Interviewer", "type": "text", "marks": [{"type": "bold"}]}, {"text": " beside the person asking the questions, so Analyze leaves their words out. ", "type": "text"}, {"text": "Add", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the bottom adds a speaker the transcript missed. From seven speakers a find box and an ", "type": "text"}, {"text": "Unnamed only", "type": "text", "marks": [{"type": "bold"}]}, {"text": " switch appear.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "If the transcript split one person into two voices, select ", "type": "text"}, {"text": "Merge…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the extra speaker and choose who it really was. All of its lines move to that speaker.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a line", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select the ⋮ at the end of any line for ", "type": "text"}, {"text": "Edit text", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Make an excerpt from this line", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ", "type": "text"}, {"text": "Change speaker…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Merge with the next line", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Double-clicking the text, or pressing E on the current line, also starts an edit, and while editing you can split the line at the cursor. Choosing ", "type": "text"}, {"text": "＋ New speaker…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " when changing a line''s speaker names someone new. ", "type": "text"}, {"text": "Copy transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Download .txt", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", above the transcript, take the whole text with you, with the time at the start of each line.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Edit a source''s details", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select the ⋮ beside the source''s title and choose ", "type": "text"}, {"text": "Edit details", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A card opens with the title and, for a recording, the date it was recorded. Select ", "type": "text"}, {"text": "Save", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to keep the change; the source''s search entries update with it. A PDF has a title only. The same menu has ", "type": "text"}, {"text": "Rebuild search index", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", for a source transcribed before search existed or after a round of corrections, and the two ways out: ", "type": "text"}, {"text": "Remove from this project…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Delete source…", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", each saying what it does before you confirm.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Create an excerpt", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Drag to select the stretch of text you want. On a phone, touch and hold a word, then drag.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "New excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": " bar opens at the bottom of the transcript with a title already filled in, and the time range beside it. The title starts as the first words you selected and, a moment later, is replaced by a short description of what the speaker says, if you haven''t started typing. When you save, the excerpt is named in full: the project, then who is speaking, then your title, such as Hurricane Isaias_Chip Simmons_Second fatality from generator fumes. That is also the name of the file you download.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Change the title if you like, then press Enter or select ", "type": "text"}, {"text": "Save excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". ", "type": "text"}, {"text": "Preview", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays the exact range; Esc cancels.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Working with excerpts", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The panel lists this source''s excerpts. ", "type": "text"}, {"text": "In order", "type": "text", "marks": [{"type": "bold"}]}, {"text": " follows the recording and ", "type": "text"}, {"text": "Newest", "type": "text", "marks": [{"type": "bold"}]}, {"text": " puts the latest first. From nine excerpts a filter box appears, and twenty show at a time with ", "type": "text"}, {"text": "Show more", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The round ", "type": "text"}, {"text": "play button", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a card plays that excerpt. While it plays the button turns into a pause button, so you can stop it from the card without going to the player. Playing another excerpt switches to that one.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trim", "type": "text", "marks": [{"type": "bold"}]}, {"text": " shows the clip''s words. Tap a word to move the start or end there, or nudge them with the −250, −50, +50 and +250 buttons. ", "type": "text"}, {"text": "Play as cut", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plays the result, and ", "type": "text"}, {"text": "Done trimming", "type": "text", "marks": [{"type": "bold"}]}, {"text": " closes it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Export WAV", "type": "text", "marks": [{"type": "bold"}]}, {"text": " renders the clip to its own audio file; ", "type": "text"}, {"text": "Download", "type": "text", "marks": [{"type": "bold"}]}, {"text": " appears when it is ready, and the button then reads ", "type": "text"}, {"text": "Re-export", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". ", "type": "text"}, {"text": "Show in transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " scrolls to the clip''s words.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Level", "type": "text", "marks": [{"type": "bold"}]}, {"text": " line on a card shows the volume change applied to that excerpt, such as +4.2 dB. Every excerpt is measured when you create or trim it, then played and exported at a fixed level of -18 LUFS, the level the team preps actualities at in Audition, followed by a hard limiter that holds peaks at -6 dBFS. One actuality no longer comes in much hotter or quieter than the last. The level is one volume setting for the whole excerpt, so a speaker who drops to a whisper stays that far below their own normal voice; only the peaks are limited. Select ", "type": "text"}, {"text": "Original level", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to play and export an excerpt as recorded, for example when the quiet is the point, and ", "type": "text"}, {"text": "Even out", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to go back. A card that says ", "type": "text"}, {"text": "measuring…", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is still being measured and updates by itself in a few seconds. If it says the excerpt couldn''t be measured, it plays and exports as recorded.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Export excerpts (zip)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", in the Excerpts section of the project''s Notebook, exports every excerpt in the project at once.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select a card''s title to rename it. ", "type": "text"}, {"text": "Delete", "type": "text", "marks": [{"type": "bold"}]}, {"text": " asks you to confirm.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "When the source is in a project", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Opened from a project, the panel has a switch between ", "type": "text"}, {"text": "Excerpts", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Data points", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the findings and clips Analyze proposed for this source, underlined in the transcript where they are. See ", "type": "text"}, {"text": "Analyzing a source", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-research"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A PDF source works the same way, but you select a stretch of the extracted text instead of a time range. Its screen has ", "type": "text"}, {"text": "Document", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Text", "type": "text", "marks": [{"type": "bold"}]}, {"text": " views and a search box for the document.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trimming a clip after it has been exported makes that export stale. Re-export before you rely on the download.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Line menus and the speaker list work on a tablet or phone too: nothing waits on hovering. Tapping an excerpt''s words on a phone opens it in a sheet; see ", "type": "text"}, {"text": "Play, trim and manage an excerpt on a phone", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-excerpt-sheet-on-a-phone"}}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Level is never applied to the recording itself, only to playback and to exports. Very quiet field tape can need a boost of 35 to 45 dB. Past 20 dB the card notes that the boost raises the background noise along with the voice. If a clip is stereo with the voice in one channel only, the voice is played and exported on both sides. Re-export after changing an excerpt''s level, since an earlier export keeps the level it was made at.", "type": "text"}]}]}]}]}', 'release', 'Transcript lines are about half a minute long, each with its time, and a word plays from itself', '2026-11-05 23:48:42.831951+00', NULL),
	('d47ab946-f493-428e-b688-a2236c9fd9ce', '815ae5eb-5e2c-4b7d-9952-68249640e7fd', 7, 'Editorial Planning: pitch to assignment', '{"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Submit a useful pitch", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A pitch should make a potential story legible to a colleague without requiring a separate conversation. State what is happening; whom it affects; why it matters now; what remains unknown; what evidence or sources might answer the question; and what reporting effort is likely required. Choose the coverage pillar that best describes the underlying public question, not merely the institution involved.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Example:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Rather than \"A university hosts a military program,\" frame the public question: whether a university''s expansion of military-to-civilian training is changing access to civilian employment and for whom. The institutional activity is a lead to investigate, not necessarily the story''s conclusion.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The existing workflow permits a ", "type": "text"}, {"text": "submitted pitch", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial"}}]}, {"text": " to be edited until it enters ", "type": "text"}, {"text": "meeting scoring", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial/meetings"}}]}, {"text": "; use review history to understand whether it was assigned, deferred or archived.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Run a planning meeting", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Editors create the meeting and add eligible pitches to the slate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Reviewers score independently against the published anchored criteria and record substantive concerns. An institutional alignment modifier must not substitute for the story''s civic value, evidence or feasibility.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "After scoring closes, consider the ranked agenda, disagreements and written comments. Scores inform editorial judgment; they do not make the assignment decision themselves.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Record the disposition and assignment clearly. A deferred pitch should have an understandable next step where possible; an assigned pitch should identify the responsible reporter.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Conclude the meeting only after decisions are recorded. The concluded meeting is a permanent historical record.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "After assignment", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The pipeline ends at the assignment. The pitch page records who is reporting the story and keeps every round''s scores, comments and decision as the newsroom''s record; the reporting itself is not tracked here.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Administration", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Configuration guides should explain the difference between weighted core criteria and separate modifiers, how archived rubric elements preserve historical scores, and when changing criteria is justified. Any numerical example must match the live rubric.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Direct portal screen links", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Open these routes in the portal. Individual records must be opened from their list; no record ID is assumed.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Pitch backlog", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial"}}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Meetings", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial/meetings"}}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Settings", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/editorial/settings"}}]}]}]}]}]}', 'release', 'Station name removed so the guide reads for any station', '2026-11-05 23:48:43.198941+00', NULL),
	('64bbc8bc-d34a-460d-a680-5cebc8dfe6bd', '493a2ac4-d894-490a-ab9b-58e5bc027f27', 6, 'Building the content library', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The content library holds everything a rundown can pull from — news, promos, membership messages, PSAs, legal IDs, and more. Anyone with On Air access can add to it, not just the program director.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find an item", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Type in the search box to search titles, DAD cart numbers, and scripts. The list updates as you type; pressing Enter searches straight away.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Clear the box to see the whole library again.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Use the status chips (All, Approved, Draft, Retired) and the content type chips to narrow the list. Each status chip shows how many items it would show.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The library shows 25 items a page, newest first. The page links under the table move between pages.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add a content item", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the library, select ", "type": "text"}, {"text": "+ New content item", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fill in a title, content type, summary, script, expected duration, and effective dates.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Create content item", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Add its components", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the item''s page, expand ", "type": "text"}, {"text": "Add a component", "type": "text", "marks": [{"type": "bold"}]}, {"text": " — choose a type (live intro, recorded audio, live outro, or an optional tag), a sequence, a duration, and a script. Select ", "type": "text"}, {"text": "Add component", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A required component counts toward the item''s total time; an optional one doesn''t.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Approve it", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An item starts as a draft. Set its status to Approved, in the Status panel on its page, before it can be picked for a rundown — only approved items are offered when filling a break.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Import the station''s DAD cut library", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "From the library, open the import screen and upload the Standard Library export from DAD (Library screen → Generate Reports → Standard Library) — optionally with its companion Groups report.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Preview import", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to see the plan: new items, updates to existing ones, and anything it couldn''t place.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Import", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to confirm.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "There''s no audio upload here. The station''s playback system (ENCO/DAD) is where recorded material actually plays from — a content item is metadata and a script, not an audio file.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Re-running the import later updates an already-imported item in place (matched by its DAD cart number) instead of creating a duplicate.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Retiring stale content is an ordinary status change, not a delete — nothing in the library is ever removed outright.", "type": "text"}]}]}]}]}', 'release', 'Station name removed so the guide reads for any station', '2026-11-05 23:48:43.198941+00', NULL),
	('2c543fdc-7a3d-4fb1-8691-c370c708b94d', '28d2b516-e45e-4948-9ce0-5bec78d7b0c2', 7, 'Sources: NPR, weather and Florida News Exchange', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/log/sources"}}]}, {"text": " tab holds the outside feeds On Air reads. It opens on one card per source, showing whether its saved data is current, when it was last updated, and what it holds. Select a card''s ", "type": "text"}, {"text": "Open", "type": "text", "marks": [{"type": "bold"}]}, {"text": " button to go to that source''s page, and ", "type": "text"}, {"text": "← Sources", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to come back.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What the cards say", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Up to date", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the saved data is inside its normal refresh window.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Stale", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the saved data is older than that, or the last refresh failed. What was saved is still shown.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Not fetched yet", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": nothing has been read from this source so far.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Not configured", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": the portal has no access set up for this source yet.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "NPR", "type": "text"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the NPR page, choose a program and a show date, then select ", "type": "text"}, {"text": "Switch", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The table lists each story''s estimated air time (marked with “~”, since NPR doesn''t supply exact times), title, teaser, and length.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Refresh", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to pull the latest episode data.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "The NPR card reports the most recently read episode. NPR is read one program and date at a time, so it is refreshed from the NPR page rather than the card.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Weather", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The weather page shows the current forecast as a row of days, with the text for today and tonight under it. Select a day to read its forecast. Select ", "type": "text"}, {"text": "Refresh", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on the page or on the weather card to force an update.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Weather alerts", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "When the National Weather Service has a warning, watch or statement active for the studio''s area, a row appears under the forecast. It names the most severe alert and how many more there are. Select the row to see them all, select an alert to read it, and select ", "type": "text"}, {"text": "Full NWS text", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for everything the Weather Service said.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Warnings come first, then watches, then statements.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The same row appears above ", "type": "text"}, {"text": "Full forecast", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in a rundown''s Weather panel and on a weather item''s card.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Alerts are checked every 15 minutes. If a check fails, the row shows the last alerts it had, with the time it last checked. If alerts have never been checked, the page says so instead of showing nothing.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Florida News Exchange", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This page lists the stories other Florida stations shared through PRX in the last 24 hours, newest first. A wrap and its cut are listed together. Each version has a player (its menu has a download option), the feed description, and a link to its page on PRX.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The feed description is often only a summary. The full script can be on the story''s PRX page: select ", "type": "text"}, {"text": "Open on PRX", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A hold note from the feed, such as Hold until 10/8, appears beside the story. It is there for you to follow; the portal does not enforce it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Select ", "type": "text"}, {"text": "Add to library", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to open the new content item form with the title, the type News, and a summary already filled in. The summary holds the description, any hold note and the PRX link. Paste the script, save, then add its components (live intro, recorded audio, outro) on the item''s page, as for any library item.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Audio is not copied into the portal. Load it into DAD to air it. The links in the feed expire after an hour, so if a player will not play, reload the page.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Good to know", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sources refresh themselves when you open them and their data is past its window. Refresh is a manual option, not something you need to do routinely.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A fetch failure shows as a plain message, with whatever was last read still on screen. No page goes blank because of a temporary outage.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "NPR''s estimated times need a rundown to already exist for that program and date. Without one, the table has nothing to anchor its estimates to.", "type": "text"}]}]}]}]}', 'release', 'Station name removed so the guide reads for any station', '2026-11-05 23:48:43.198941+00', NULL),
	('ec20d053-3c03-4136-864c-171d16d1096b', '2330ed51-67a6-4097-b54c-0a7c00ddf9d8', 7, 'Read a clock', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Open a clock from the program that airs on it: on the program''s page, select ", "type": "text"}, {"text": "Open clock", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The link at the top left of the clock''s page goes back to that program.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Timeline and Ring", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The diagram shows one hour of the clock. Switch between ", "type": "text"}, {"text": "Timeline", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Ring", "type": "text", "marks": [{"type": "bold"}]}, {"text": " at the top right of the diagram; both behave the same way.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The network''s structure comes first: segments, newscasts (dark), and promos and credits. Local opportunities are marked in blue: a dashed outline for optional, solid for required.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hover over or tab to a slot to read its name, times, and length. Select a slot to fix it in the side panel and the slot list.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "The Slots list lists every slot. Hovering over a row highlights that slot in the diagram; selecting a row shows it in the side panel.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Shifts longer than an hour", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "When a program airs for more than an hour, the clock repeats every hour. Use the arrows beside ", "type": "text"}, {"text": "Hour 1 of 2", "type": "text", "marks": [{"type": "bold"}]}, {"text": " to step through the hours. The network structure is the same in each hour, but pinned content can differ, and a small number on a local slot shows how many items are pinned for the hour you''re looking at.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Floating breaks", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A break whose position isn''t fixed appears as a shaded window. A dashed edge can move and a solid edge is fixed; the darker area is always part of the break. Select it to see when it can start and end and how long it can run.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Versions", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Choose a version from the ", "type": "text"}, {"text": "Version", "type": "text", "marks": [{"type": "bold"}]}, {"text": " menu. A version can''t be edited once it exists — a correction is a new version, started with ", "type": "text"}, {"text": "+ New version", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Changing what the station can fill (program director)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Select a slot, then use the buttons in its panel: ", "type": "text"}, {"text": "Edit eligibility", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a local slot, or ", "type": "text"}, {"text": "Mark eligible for local content", "type": "text", "marks": [{"type": "bold"}]}, {"text": " on a network-only one. ", "type": "text"}, {"text": "Remove", "type": "text", "marks": [{"type": "bold"}]}, {"text": " takes a slot out of local eligibility.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Pinning content (program director or traffic)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A pin puts the same content item into a slot in every rundown made from this clock: the hourly station ID (see ", "type": "text"}, {"text": "Station IDs", "type": "text", "marks": [{"type": "bold"}]}, {"text": "), or a feature like BirdNote. Select a local slot, then ", "type": "text"}, {"text": "Pin content", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Choose the item, then the hour and days. ", "type": "text"}, {"text": "Every hour", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with no days checked covers the whole shift, every day. ", "type": "text"}, {"text": "Remove", "type": "text", "marks": [{"type": "bold"}]}, {"text": " under a pinned item takes the pin off.", "type": "text"}]}]}', 'release', 'Station name removed so the guide reads for any station', '2026-11-05 23:48:43.198941+00', NULL),
	('c626d641-2502-4859-ae38-216b514478e5', '3c10491a-91f2-4a50-87f7-0312b471b133', 6, 'Sourcework: from recordings to reporting', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sourcework takes recordings and documents from upload to a script. For an ordinary assignment you transcribe audio, pick your own actualities and write the piece by hand. The analysis steps, Analyze, Synthesis and Outline, are optional, and each one waits for your decision.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Start with the task you have", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For a complete first assignment, follow ", "type": "text"}, {"text": "From interview recording to radio script", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-interview-to-script"}}]}, {"text": ". It goes from uploading a recording through checking the transcript, saving excerpts and writing a piece, with no research questions and no AI.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "To work on one step, see ", "type": "text"}, {"text": "Starting a project and adding sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-starting-a-project"}}]}, {"text": ", ", "type": "text"}, {"text": "Working with the transcript and creating excerpts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-transcript-and-excerpts"}}]}, {"text": " or ", "type": "text"}, {"text": "Building a piece from narration and excerpts", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-pieces"}}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What each thing is", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A ", "type": "text"}, {"text": "source", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is an original recording or PDF. A ", "type": "text"}, {"text": "transcript", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is derived text, and an ", "type": "text"}, {"text": "excerpt", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a stretch of a source saved for reuse: a time range of a recording, or a passage of a PDF. A ", "type": "text"}, {"text": "project", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the work for one story and refers to sources; the same source can be in more than one project without a second upload. A ", "type": "text"}, {"text": "piece", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a script built from narration and excerpts.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Find and reuse what you already have", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/sourcework?tab=notebook"}}]}, {"text": " on the Sourcework home lists every source and every excerpt, whichever project they are in, and its search box finds spoken words, passages and excerpts across all of them. See ", "type": "text"}, {"text": "Browse the Notebook", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-browse-source-library"}}]}, {"text": " and ", "type": "text"}, {"text": "Searching across projects and sources", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-search"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The optional steps, in order", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "A project''s own Notebook tab shows where it stands and names the next step. ", "type": "text"}, {"text": "Analyze", "type": "text", "marks": [{"type": "bold"}]}, {"text": " reads a source and proposes findings and a few clips, which you decide on from the project''s ", "type": "text"}, {"text": "Review", "type": "text", "marks": [{"type": "bold"}]}, {"text": " tab. ", "type": "text"}, {"text": "Synthesis", "type": "text", "marks": [{"type": "bold"}]}, {"text": " reads the accepted findings and says what they establish for each research question. ", "type": "text"}, {"text": "Outline with AI", "type": "text", "marks": [{"type": "bold"}]}, {"text": " plans a piece as beats, and ", "type": "text"}, {"text": "Write from outline", "type": "text", "marks": [{"type": "bold"}]}, {"text": " turns the beats into narration. See ", "type": "text"}, {"text": "Analyzing a source", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-research"}}]}, {"text": ", ", "type": "text"}, {"text": "Synthesis", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-synthesis"}}]}, {"text": ", ", "type": "text"}, {"text": "Outline a piece", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-outline"}}]}, {"text": " and ", "type": "text"}, {"text": "A project at a glance", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/resources/tools/transcription/sourcework-project-overview"}}]}, {"text": ". Each of these steps sends the project''s material to an outside service; building by hand sends nothing.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Check the underlying material", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Before anything airs, verify quotations, speaker identities, names, numbers and the context of each excerpt against the original recording. Neither the transcript nor a finding replaces editorial judgment. Apply the station''s editorial and confidentiality requirements when handling sources.", "type": "text"}]}]}', 'release', 'Station name removed so the guide reads for any station', '2026-11-05 23:48:43.198941+00', NULL);
