insert into public.sw_piece_formats select * from jsonb_populate_recordset(null::public.sw_piece_formats, '[{"id": "405e7aae-5742-4165-89da-99b75afefbfb", "name": "Cut and Copy", "position": 2, "created_at": "2026-11-05T23:48:41.06857+00:00", "created_by": null, "updated_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_by": null}, {"id": "55b2c535-2790-4d47-a5e7-9fa03c2e08b8", "name": "Feature", "position": 5, "created_at": "2026-11-05T23:48:41.06857+00:00", "created_by": null, "updated_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_by": null}, {"id": "7f433b3f-0e82-45de-98dc-444b74e85469", "name": "Wrap", "position": 3, "created_at": "2026-11-05T23:48:41.06857+00:00", "created_by": null, "updated_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_by": null}, {"id": "e7725524-cc76-4cb8-a65c-bb59878f0d19", "name": "Reader / Voicer", "position": 1, "created_at": "2026-11-05T23:48:41.06857+00:00", "created_by": null, "updated_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_by": null}, {"id": "f1282d11-aeb1-4fa4-9c8d-1a991d56246e", "name": "Super Spot", "position": 4, "created_at": "2026-11-05T23:48:41.198934+00:00", "created_by": null, "updated_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_at": "2026-11-05T23:48:41.305136+00:00", "live_moved_by": null}]'::jsonb);
insert into public.sw_piece_format_versions select * from jsonb_populate_recordset(null::public.sw_piece_format_versions, E'[{"id": "1ff56ec4-acbd-425d-b7b1-9eb63154eb68", "note": "Built-in starting point", "spec": {"style": "Written for a host to read cold. Name the speaker before the clip, never only after it. Short sentences, plain words, no adjective the speaker did not use.", "sections": [{"type": "narration", "guidance": "Host copy: the news in one or two sentences, ending by naming who we hear next and why."}, {"type": "actuality", "guidance": "The clip: one clear, self-contained thought."}, {"type": "narration", "guidance": "Tag: one sentence after the clip with a fact or what happens next."}], "targetSeconds": 45, "maxActualities": 1, "minActualities": 1, "toleranceSeconds": 5}, "version": 1, "format_id": "405e7aae-5742-4165-89da-99b75afefbfb", "created_at": "2026-11-05T23:48:41.06857+00:00", "created_by": null}, {"id": "4bda4f35-61ee-4360-8072-0837d929d7be", "note": "Description and guardrails replace the ordered sections", "spec": {"style": "A fully reported piece with room for several voices and a shape of its own. It opens on a specific scene or the strongest fact, says why it matters now and what the piece will look at, develops the story with the history, the facts and the context from the accepted themes, brings in voices where each earns its place (one person can be heard more than once if that is the strongest material), includes the complication, the other side or what changed, and closes with where things stand and the sign-off. An anchor intro of two or three sentences a host reads ends by naming the reporter as [REPORTER NAME]. Write for the ear: one idea per sentence, present tense where it reads naturally, and attribute every claim. The clips carry the feeling and the narration the facts. Vary the rhythm. Complicating evidence is part of the story. Do not use an adjective the speaker did not use.", "anchorIntro": true, "targetSeconds": 240, "maxActualities": 6, "minActualities": 2, "toleranceSeconds": 30}, "version": 3, "format_id": "55b2c535-2790-4d47-a5e7-9fa03c2e08b8", "created_at": "2026-11-05T23:48:41.305136+00:00", "created_by": null}, {"id": "583e92cf-268b-448a-b14f-17e5e16b7cb1", "note": "Catalog revised to the five newsroom formats", "spec": {"style": "Spoken copy with no recorded excerpts, read by the anchor (a reader) or the reporter (a voicer). Short sentences, one idea each, attribution first (\\"the mayor says...\\"). Present tense where it reads naturally. Attribute what sources said in your own words rather than quoting at length. Do not use an adjective the speaker did not use, and never tell the audience what to feel.", "sections": [{"type": "anchor", "guidance": "Anchor intro, only when a reporter voices the story: one or two sentences with the newest fact, setting it up without repeating the reporter''s first line.", "optional": true}, {"type": "narration", "guidance": "Lead: the newest fact and where it happened, in one sentence."}, {"type": "narration", "guidance": "Context: what a listener needs to make sense of it, attributed to the people who said it."}, {"type": "narration", "guidance": "What happens next. A voicer ends with the sign-off, leaving [REPORTER NAME] as a placeholder; a reader just ends on its last fact.", "optional": true}], "targetSeconds": 38, "maxActualities": 0, "minActualities": 0, "toleranceSeconds": 8}, "version": 2, "format_id": "e7725524-cc76-4cb8-a65c-bb59878f0d19", "created_at": "2026-11-05T23:48:41.198934+00:00", "created_by": null}, {"id": "638c1ff4-cace-4613-b281-4b70a6654a91", "note": "Description and guardrails replace the ordered sections", "spec": {"style": "Copy an anchor reads cold, with one cut in it. The copy gives the news in a sentence or two and ends by naming who we hear next and why; the cut is one clear, self-contained thought, ideally under 20 seconds; a closing sentence after the cut can add a fact or what happens next. The whole thing is timed together. Name the speaker before the cut, never only after it. Do not say in the copy what the cut says. Short sentences, plain words, no adjective the speaker did not use.", "anchorIntro": false, "targetSeconds": 45, "maxActualities": 1, "minActualities": 1, "toleranceSeconds": 5}, "version": 3, "format_id": "405e7aae-5742-4165-89da-99b75afefbfb", "created_at": "2026-11-05T23:48:41.305136+00:00", "created_by": null}, {"id": "6ea127bd-ba59-486e-97dc-6f3714f0a739", "note": "Built-in starting point", "spec": {"style": "Plain and factual. Present tense where it reads naturally. Do not use an adjective the speaker did not use. Never tell the audience what to feel. Keep sentences short enough to read in one breath.", "sections": [{"type": "narration", "guidance": "Setup: name the place and the question in one sentence."}, {"type": "actuality", "guidance": "Voice: the strongest first-person moment."}, {"type": "narration", "guidance": "Turn: introduce a second voice or a complication."}, {"type": "actuality", "guidance": "Voice: a different speaker, ideally one who complicates."}, {"type": "narration", "guidance": "Close and sign-off. Leave [REPORTER NAME] as a placeholder."}], "targetSeconds": 60, "maxActualities": 3, "minActualities": 2, "toleranceSeconds": 5}, "version": 1, "format_id": "7f433b3f-0e82-45de-98dc-444b74e85469", "created_at": "2026-11-05T23:48:41.06857+00:00", "created_by": null}, {"id": "7c937b38-d39c-4a60-a985-b0a884e98726", "note": "Description and guardrails replace the ordered sections", "spec": {"style": "Spoken copy with no recorded excerpts: a reader is read by the anchor, a voicer by the reporter. Lead with the newest fact and where it happened, give a listener the context to make sense of it, attributed to the people who said it, and end on what happens next or the last fact. A voicer ends with the sign-off, leaving [REPORTER NAME] as a placeholder. When a reporter voices the story, an anchor intro of one or two sentences sets it up without repeating the reporter''s first line. Short sentences, one idea each, attribution first (\\"the mayor says...\\"). Present tense where it reads naturally. Attribute what sources said in your own words rather than quoting at length. Do not use an adjective the speaker did not use, and never tell the audience what to feel.", "anchorIntro": true, "targetSeconds": 38, "maxActualities": 0, "minActualities": 0, "toleranceSeconds": 8}, "version": 3, "format_id": "e7725524-cc76-4cb8-a65c-bb59878f0d19", "created_at": "2026-11-05T23:48:41.305136+00:00", "created_by": null}, {"id": "83705daa-4b24-482d-94b8-67ef45a28f4a", "note": "Description and guardrails replace the ordered sections", "spec": {"style": "A short report with room to develop one idea. It opens with the news or a specific scene that puts the listener in the story, hears from the people who lived it or can speak to it directly, gives the context and the facts a listener needs to judge the claims, includes the complication or other side when the material has one, and closes with where things stand and the sign-off. Each voice should move the story forward or complicate it, not repeat an earlier one. An anchor intro of two or three sentences ends by naming the reporter as [REPORTER NAME]. Write for the ear: one idea per sentence, present tense where it reads naturally, and attribute every claim. Let the clips carry the feeling and the narration carry the facts. Complicating evidence belongs in the story. Do not use an adjective the speaker did not use.", "anchorIntro": true, "targetSeconds": 120, "maxActualities": 3, "minActualities": 1, "toleranceSeconds": 10}, "version": 2, "format_id": "f1282d11-aeb1-4fa4-9c8d-1a991d56246e", "created_at": "2026-11-05T23:48:41.305136+00:00", "created_by": null}, {"id": "8cfa6b16-14dc-4077-95ef-949ece9fbc30", "note": "Catalog revised to the five newsroom formats", "spec": {"style": "A fully reported piece, with room for several voices and a shape of its own. Write for the ear: one idea per sentence, present tense where it reads naturally, and attribute every claim. The clips carry the feeling and the narration the facts. Vary the rhythm; do not alternate narration and clips mechanically. Complicating evidence is part of the story. Do not use an adjective the speaker did not use.", "sections": [{"type": "anchor", "guidance": "Anchor intro: two or three sentences a host reads, ending by naming the reporter as [REPORTER NAME]. Not timed with the piece.", "optional": true}, {"type": "narration", "guidance": "Opening: a specific scene, or the strongest fact, from what the sources describe."}, {"type": "actuality", "guidance": "First voice: someone who lived it."}, {"type": "narration", "guidance": "Why it matters now, and what the piece will look at, in a sentence or two."}, {"type": "actuality", "guidance": "A second voice that adds to the first, or sees it differently."}, {"type": "narration", "guidance": "Body: develop the story with the history, the facts and the context from the accepted themes. Bring in further voices where each one earns its place; the story decides how the narration and clips alternate."}, {"type": "actuality", "guidance": "More voices, as the story needs them. One person can be heard more than once if that is the strongest material.", "optional": true}, {"type": "narration", "guidance": "The complication, the other side, or what changed.", "optional": true}, {"type": "narration", "guidance": "Close: where things stand now, then the sign-off."}], "targetSeconds": 240, "maxActualities": 6, "minActualities": 2, "toleranceSeconds": 30}, "version": 2, "format_id": "55b2c535-2790-4d47-a5e7-9fa03c2e08b8", "created_at": "2026-11-05T23:48:41.198934+00:00", "created_by": null}, {"id": "990b56cb-1e32-4230-bd82-6f7406236db8", "note": "Description and guardrails replace the ordered sections", "spec": {"style": "A reporter''s voiced story with tape wrapped inside it. It sets up the news and the place, lets a voice carry what narration can''t (an experience, a feeling, an explanation in the speaker''s own words), supplies the facts and any complication or other side, and closes on the last fact or what happens next with the reporter''s sign-off, leaving [REPORTER NAME] as a placeholder. A second clip belongs only if it adds something the first did not. An anchor intro of one or two sentences sets the story up without repeating the reporter''s first line. Plain and factual, present tense where it reads naturally, attribution first. Name the speaker before each clip. Do not use an adjective the speaker did not use, and never tell the audience what to feel. Short enough to read in one breath.", "anchorIntro": true, "targetSeconds": 53, "maxActualities": 2, "minActualities": 1, "toleranceSeconds": 8}, "version": 3, "format_id": "7f433b3f-0e82-45de-98dc-444b74e85469", "created_at": "2026-11-05T23:48:41.305136+00:00", "created_by": null}, {"id": "b8962c50-39dd-4408-859d-c94d13263581", "note": "Built-in starting point", "spec": {"style": "Write for the ear. One idea per sentence, present tense where it reads naturally, and attribute every claim. Let the actualities carry the feeling; the narration carries the facts. Do not use an adjective the speaker did not use.", "sections": [{"type": "narration", "guidance": "Host introduction: two or three sentences a host reads, ending by naming the reporter as [REPORTER NAME]."}, {"type": "narration", "guidance": "Scene: put the listener somewhere specific, from what the sources describe."}, {"type": "actuality", "guidance": "First voice: someone who lived it."}, {"type": "narration", "guidance": "Context: the history or facts a listener needs, from the accepted themes."}, {"type": "actuality", "guidance": "Second voice: a different speaker or source."}, {"type": "narration", "guidance": "Turn: the complication, the other side, or what changed."}, {"type": "actuality", "guidance": "Third voice: ideally one who complicates the first."}, {"type": "narration", "guidance": "Close: where things stand now, then the sign-off."}], "targetSeconds": 180, "maxActualities": 6, "minActualities": 3, "toleranceSeconds": 15}, "version": 1, "format_id": "55b2c535-2790-4d47-a5e7-9fa03c2e08b8", "created_at": "2026-11-05T23:48:41.06857+00:00", "created_by": null}, {"id": "c861cc6b-790d-4db8-9d7e-df4f80dacf6e", "note": "Catalog revised to the five newsroom formats", "spec": {"style": "Written for an anchor to read cold, and timed as a whole: the copy, the cut and the tag. Name the speaker before the cut, never only after it. Do not say in the copy what the cut says. Short sentences, plain words, no adjective the speaker did not use.", "sections": [{"type": "narration", "guidance": "Anchor copy: the news in one or two sentences, ending by naming who we hear next and why."}, {"type": "actuality", "guidance": "The cut: one clear, self-contained thought, ideally under 20 seconds."}, {"type": "narration", "guidance": "Tag: one sentence after the cut with a fact or what happens next.", "optional": true}], "targetSeconds": 45, "maxActualities": 1, "minActualities": 1, "toleranceSeconds": 5}, "version": 2, "format_id": "405e7aae-5742-4165-89da-99b75afefbfb", "created_at": "2026-11-05T23:48:41.198934+00:00", "created_by": null}, {"id": "c97fb6cc-7ec1-40ad-880e-f6620df94fa4", "note": "Catalog revised to the five newsroom formats", "spec": {"style": "A reporter''s voiced story with tape wrapped inside it. Plain and factual, present tense where it reads naturally, attribution first. Name the speaker before each clip. Do not use an adjective the speaker did not use, and never tell the audience what to feel. Short enough to read in one breath.", "sections": [{"type": "anchor", "guidance": "Anchor intro: one or two sentences with the newest fact, setting up the story. It is not timed with the piece, and should not repeat the reporter''s first line.", "optional": true}, {"type": "narration", "guidance": "Setup: the news and the place in a sentence or two, then who we hear."}, {"type": "actuality", "guidance": "Voice: the strongest moment, one the narration can''t give: an experience, a feeling, an explanation in the speaker''s own words."}, {"type": "narration", "guidance": "Context and turn: the facts a listener needs, and the complication or other side if the material has one."}, {"type": "actuality", "guidance": "A second clip, only if it adds something the first did not: another view, a complication, the human stakes.", "optional": true}, {"type": "narration", "guidance": "Close and sign-off: the last fact or what happens next, then [REPORTER NAME] as a placeholder. Not a summary."}], "targetSeconds": 53, "maxActualities": 2, "minActualities": 1, "toleranceSeconds": 8}, "version": 2, "format_id": "7f433b3f-0e82-45de-98dc-444b74e85469", "created_at": "2026-11-05T23:48:41.198934+00:00", "created_by": null}, {"id": "dae44e06-3811-4ea9-afbf-227f83070118", "note": "Built-in starting point", "spec": {"style": "The reporter''s voice only, with no actualities. Attribute what sources said in your own words (\\"she says\\") rather than quoting at length. Plain, factual and in the present tense where it reads naturally.", "sections": [{"type": "narration", "guidance": "Lead: the newest fact and where it happened, in one sentence."}, {"type": "narration", "guidance": "Context: what a listener needs to make sense of it, attributed to the people who said it."}, {"type": "narration", "guidance": "What happens next, then the sign-off. Leave [REPORTER NAME] as a placeholder."}], "targetSeconds": 45, "maxActualities": 0, "minActualities": 0, "toleranceSeconds": 5}, "version": 1, "format_id": "e7725524-cc76-4cb8-a65c-bb59878f0d19", "created_at": "2026-11-05T23:48:41.06857+00:00", "created_by": null}, {"id": "e9be9963-90fe-4297-89c4-659619e6ab62", "note": "Built-in starting point", "spec": {"style": "A short report with room to develop one idea. Write for the ear: one idea per sentence, present tense where it reads naturally, and attribute every claim. Let the clips carry the feeling and the narration carry the facts. Complicating evidence belongs in the story. Do not use an adjective the speaker did not use.", "sections": [{"type": "anchor", "guidance": "Anchor intro: two or three sentences setting up the story, ending by naming the reporter as [REPORTER NAME]. Not timed with the piece.", "optional": true}, {"type": "narration", "guidance": "Lead: the news, or a specific scene that puts the listener in the story, in the fewest words that work."}, {"type": "actuality", "guidance": "First voice: someone who lived it or can speak to it directly."}, {"type": "narration", "guidance": "Context: what happened before, the numbers and the facts a listener needs to judge the claims, from the accepted themes."}, {"type": "actuality", "guidance": "Another voice, if it moves the story forward or complicates it.", "optional": true}, {"type": "narration", "guidance": "The other side, the complication, or what changed.", "optional": true}, {"type": "actuality", "guidance": "A third voice, only if it is not saying what an earlier one did.", "optional": true}, {"type": "narration", "guidance": "Close: where things stand and what comes next, then the sign-off."}], "targetSeconds": 120, "maxActualities": 3, "minActualities": 1, "toleranceSeconds": 10}, "version": 1, "format_id": "f1282d11-aeb1-4fa4-9c8d-1a991d56246e", "created_at": "2026-11-05T23:48:41.198934+00:00", "created_by": null}]'::jsonb);
